INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Enigmora/devtrail/devtrail-new', 'devtrail-new', 'Enigmora', 'devtrail', 'community', 'devtrail-new Enigmora devtrail community devtrail-new是一个为AI辅助开发提供文档管理框架的AI智能开发助手，帮助开发者更高效地管理代码和文档 devtrail-newはAIエージェントによる開発を支援するドキュメント管理フレームワークで、開発者がコードとドキュメントをより効率的に管理できるようにします devtrail-new는 AI 에이전트가 개발을 지원하는 문서 관리 프레임워크로 개발자가 코드와 문서를 더 효율적으로 관리할 수 있도록 도와줍니다 devtrail-new es un marco de gobernanza de documentación para el desarrollo asistido por IA, mejorando la eficiencia y la colaboración devtrail-new est un cadre de gouvernance de la documentation pour le développement assisté par l''IA, améliorant l''efficacité et la collaboration devtrail-new ist ein Dokumentations-Governance-Framework für die AI-gestützte Entwicklung, verbessert die Effizienz und Zusammenarbeit O devtrail-new é um framework de governança de documentação para desenvolvimento assistido por IA, melhorando a eficiência e a colaboração devtrail-new - это фреймворк управления документацией для разработки с помощью ИИ, улучшающий эффективность и сотрудничество devtrail-new هو إطار حوكمة وثائقية للتنمية المدعومة بالذكاء الاصطناعي، يحسن الفعالية والتعاون Documentation governance framework for AI-assisted development AI智能开发助手 如何使用devtrail-new devtrail-new安装指南 devtrail-new替代品 devtrail-new与其他工具的比较 AI辅助开发工具 代码管理最佳实践 文档管理工具 Documentation governance framework for AI-assisted development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('adithya-s-k/manim_skill/manimce-best-practices', 'community', 'adithya-s-k', 'manim_skill', 'adithya-s-k/manim_skill', 'manimce-best-practices', 0, 0, 46, '2026-03-04T13:07:01.900Z', '2026-03-04T14:56:49.509Z', 'ae09751ec9e3e9389b85f923f4e34b706a32e01b18e378759163d1d855f90d4e', '{"id":"adithya-s-k/manim_skill/manimce-best-practices","name":"manimce-best-practices","description":{"zh":"Manim最佳实践指南，用于创建3Blue1Brown风格的动画，帮助开发者掌握AI智能代理技术","ja":"3Blue1Brownスタイルのアニメーションを作成するためのManimのベストプラクティスガイド、AIエージェント技術をマスターする","ko":"3Blue1Brown 스타일의 애니메이션을 생성하기 위한 Manim의 최고의 관행 가이드, AI 에이전트 기술을 마스터하는 데 도움이 됩니다","es":"Manimce es una herramienta para crear animaciones estilo 3Blue1Brown con Agentes de IA. Aprende a utilizarla con nuestras mejores prácticas","fr":"Manimce est un outil pour créer des animations de style 3Blue1Brown avec des Outils de IA. Découvrez comment l''utiliser avec nos meilleures pratiques","de":"Manimce ist ein Tool zum Erstellen von Animationsvideos im Stil von 3Blue1Brown mit KI-Agents. Erfahren Sie, wie Sie es mit unseren Best Practices verwenden","pt":"Manimce é uma habilidade de agente de IA para criar animações no estilo 3Blue1Brown. Aprenda a usar essas ferramentas para melhorar seu desenvolvimento.","ru":"Manimce - это навык ИИ Агента для создания анимаций в стиле 3Blue1Brown. Узнайте, как использовать эти инструменты для улучшения своего разработки.","ar":"منيمسي هي مهارة للوكيل الذكاء الاصطناعي لإنشاء رسومات متحركة بنمط 3Blue1Brown. تعلم كيفية استخدام هذه الأدوات لتحسين تطويرك.","en":"Agent skills for Manim to create 3Blue1Brown style animations."},"seo":{"title":{"zh":"AI智能代理Manim最佳实践","ja":"AIエージェントManimベストプラクティス","ko":"AI 에이전트 Manim 최고의 관행","es":"Mejores prácticas de Manimce con Agentes de IA","fr":"Meilleures pratiques de Manimce avec des Outils de IA","de":"Best Practices für Manimce mit KI