INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('powroom/flins/clack-guidelines', 'clack-guidelines', 'powroom', 'flins', 'community', 'clack-guidelines powroom flins community agent agentic-ai ai ai-agents ai-tools Clack Guidelines是通用技能安装器，为AI编码代理提供简化的开发流程 Clack Guidelinesは、AIコードエージェント用の汎用スキルインストーラーであり、開発プロセスを簡素化します 클랙 가이드라인은 AI 코딩 에이전트를 위한 범용 스킬 설치기로서 개발 과정을 간소화합니다 El instalador de habilidades clack-guidelines es una herramienta universal para agentes de IA que simplifica la instalación de habilidades L''installateur de compétences clack-guidelines est un outil universel pour les agents IA qui simplifie l''installation de compétences Der Skill-Installer clack-guidelines ist ein universelles Tool für KI-Agents, das die Installation von Fähigkeiten vereinfacht O clack-guidelines é um instalador universal de ferramentas de agente de IA para codificação mais eficiente Clack-guidelines - это универсальный установщик инструментов ИИ Агентов для более эффективного кодирования مثبت أدوات وكلاء الذكاء الاصطناعي لتصميم برمجي أكثر كفاءة Universal skill installer for AI coding agents AI代理安装器 AI编码代理 Clack Guidelines 如何使用Clack Guidelines AI代理开发 AI工具安装 Clack Guidelines安装指南 AI代理管理 Universal skill installer for AI coding agents');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aicodingstack/aicodingstack.io/i18n', 'community', 'aicodingstack', 'aicodingstack.io', 'aicodingstack/aicodingstack.io', 'i18n', 28, 7, 45, '2026-02-04T01:02:14Z', '2026-03-02T07:39:39.165Z', 'd46e075d29f64514056a20d1b66ddc46a7f0b325d23601db9a9455bedd197087', '{"id":"aicodingstack/aicodingstack.io/i18n","name":"i18n","description":{"zh":"AI智能工具i18n是您的AI编码栈，提供全面性的代码编写解决方案","ja":"AIエージェントi18nは、コーディングを支援するための包括的なツールです","ko":"AI 에이전트 i18n은 코딩을 위한 종합적인 도구입니다","es":"El AI Coding Stack es un hub de ecosistema de codificación de AI que ofrece herramientas de i18n para desarrolladores","fr":"L''AI Coding Stack est un hub d''écosystème de codage AI qui propose des outils de i18n pour les développeurs","de":"Der AI Coding Stack ist ein Hub für das AI-Coding-Ökosystem, das i18n-Tools für Entwickler bietet","pt":"O i18n é uma ferramenta de AI que facilita o desenvolvimento de aplicativos multinacionais","ru":"И18н - это инструмент ИИ, который упрощает разработку многонациональных приложений","ar":"i18n هو أداة ذكاء اصطناعي تسهل تطوير التطبيقات متعددة اللغات","en":"AI Coding Stack - Your AI Coding Ecosystem Hub."},"seo":{"title":{"zh":"AI智能工具i18n -您的代码编写伴侣","ja":"AIエージェントi18n - コーディングを支援するツール","ko":"AI 에이전트 i18n - 코딩을 위한 최적의 도구","es":"Herramientas de i18n para Desarrolladores de AI","fr":"Outils de i18n pour Développeurs d''AI","de":"i18n-Tools für AI-Entwickler","pt":"Ferramentas de AI: i18n para Desenvolvedores","ru":"ИИ Агенты: i18n для Разработчиков","ar":"أدوات الذكاء الاصطناعي: i18n للمطورين","en":"i18n"},"description":{"zh":"AI智能工具i18n是您的AI编码栈，提供全面性的代码编写解决方案","ja":"AIエージェントi18nは、コーディングを支援するための包括的なツールです","ko":"AI 에이전트 i18n은 코딩을 위한 종합적인 도구입니다","es":"El AI Coding Stack es un hub de ecosistema de codificación de AI que ofrece herramientas de i18n para desarrolladores","fr":"L''AI Coding Stack est un hub d''écosystème de codage AI qui propose des outils de i18n pour les développeurs","de":"Der AI Coding Stack ist ein Hub für das AI-Coding-Ökosystem, das i18n-Tools für Entwickler bietet","pt":"O i18n é uma ferramenta de AI que facilita o desenvolvimento de aplicativos multinacionais","ru":"И18н - это инструмент ИИ, который упрощает разработку многонациональных приложений","ar":"i18n هو أداة ذكاء اصطناعي تسهل تطوير التطبيقات متعددة اللغات","en":"AI Coding Stack - Your AI Coding Ecosystem Hub."},"definition":{"en":"AI Coding Stack - Your AI Coding Ecosystem Hub."},"features":{"zh":["支持多语言和区域设置","提供CLI和IDE集成","拥有强大的代码编写能力","支持多种编程语言","提供代码分析和优化工具"],"ja":["多言語・多地域対応","CLIとIDEの統合","強力なコード作成機能","複数のプログラミング言語をサポート","コード分析・最適化ツールを提供"],"ko":["다중 언어와 지역 설정 지원","CLI와 IDE 통합","강력한 코드 작성을 제공","다중 프로그래밍 언어 지원","코드 분석 및 최적화 도구 제공"],"es":["Soporte para múltiples idiomas","Integración con herramientas de desarrollo de AI","Compatibilidad con CLI y IDE","Acceso a modelos de lenguaje y proveedores de modelos","Extensión para desarrolladores de AI","Herramientas de codificación de AI"],"fr":["Prise en charge de plusieurs langues","Intégration avec des outils de développement d''AI","Compatibilité avec CLI et IDE","Accès à des modèles de langage et des fournisseurs de modèles","Extension pour les développeurs d''AI","Outils de codage d''AI"],"de":["Unterstützung für mehrere Sprachen","Integration mit AI-Entwicklungstools","Kompatibilität mit CLI und IDE","Zugriff auf Sprachmodelle und Modelanbieter","Erweiterung für AI-Entwickler","AI-Coding-Tools"],"pt":["Suporte a múltiplas línguas","Integração com ferramentas de desenvolvimento","Facilidade de uso e implementação","Compatibilidade com diferentes plataformas","Otimização para aplicativos multinacionais"],"ru":["Поддержка нескольких языков","Интеграция с инструментами разработки","Легкость использования и внедрения","Совместимость с различными платформами","Оптимизация для многонациональных приложений"],"ar":["دعم اللغات المتعددة","التكامل مع أدوات التطوير","سهولة الاستخدام والتنفيذ","التوافق مع منصات مختلفة","تحسين الأداء للتطبيقات متعددة اللغات"]},"keywords":{"zh":["如何使用i18n","什么是国际化","i18n替代工具","i18n vs 其他工具","i18n安装指南","i18n设置教程","AI智能工具","代码编写效率","编码体验"],"ja":["i18nの使い方","国際化とは","i18nの代替ツール","i18n vs 他のツール","i18nのインストール方法","i18nの設定ガイド","AIエージェント","コーディングの効率","コーディング体験"],"ko":["i18n 사용법","국제화란 무엇인가","i18n 대체 도구","i18n vs 다른 도구","i18n 설치 가이드","i18n 설정 튜토리얼","AI 에이전트","코딩 효율","코딩 경험"],"es":["herramientas de i18n para desarrolladores de AI","cómo utilizar herramientas de i18n","qué es i18n","alternativas a herramientas de i18n","herramientas de i18n vs herramientas de traducción","instalación de herramientas de i18n","guía de configuración de herramientas de i18n"],"fr":["outils de i18n pour les développeurs d''AI","comment utiliser les outils de i18n","qu''est-ce que i18n","alternatives aux outils de i18n","outils de i18n vs outils de traduction","installation des outils de i18n","guide de configuration des outils de i18n"],"de":["i18n-Tools für AI-Entwickler","wie man i18n-Tools verwendet","was ist i18n","Alternativen zu i18n-Tools","i18n-Tools vs Übersetzungs-Tools","Installation von i18n-Tools","Konfigurationsanleitung für i18n-Tools"],"pt":["como usar i18n","o que é i18n","ferramentas de ai para desenvolvedores","i18n vs outras ferramentas","instalação do i18n","guia de configuração do i18n","desenvolvimento de aplicativos multinacionais","ferramentas de desenvolvimento de ai"],"ru":["как использовать и18н","что такое и18н","инструменты ИИ для разработчиков","и18н против других инструментов","установка и18н","руководство по настройке и18н","разработка многонациональных приложений","инструменты разработки ИИ"],"ar":["كيفية استخدام i18n","ما هو i18n","أدوات الذكاء الاصطناعي للمطورين","i18n مقابل أدوات أخرى","تثبيت i18n","دليل إعداد i18n","تطوير تطبيقات متعددة اللغات","أدوات تطوير الذكاء الاصطناعي"]}},"owner":"aicodingstack","repo":"aicodingstack.io","repoPath":"aicodingstack/aicodingstack.io","stars":28,"forks":7,"updatedAt":"2026-02-04T01:02:14Z","topics":["ai","ai-development","cli","coding-tools","developer-tools","extension","ide","llm","model-provider","models"],"category":"community","skillMd":{"name":"i18n","description":"Internationalization management tool for syncing and translating language files","bodyPreview":"# I18n Management Skill\n\nManage multilingual content in the `translations/` directory. This skill provides tools to synchronize language files with the English reference and assist with translations.\n\n## Overview\n\nThis project uses `next-intl` for internationalization with JSON message files organized in `translations/`:\n\n```\ntranslations/\n├── en/                    # English (source of truth)\n│   ├── index.ts           # Main export file\n│   ├── shared.json\n│   ├── components.json\n│   └── pages","body":"# I18n Management Skill\n\nManage multilingual content in the `translations/` directory. This skill provides tools to synchronize language files with the English reference and assist with translations.\n\n## Overview\n\nThis project uses `next-intl` for internationalization with JSON message files organized in `translations/`:\n\n```\ntranslations/\n├── en/                    # English (source of truth)\n│   ├── index.ts           # Main export file\n│   ├── shared.json\n│   ├── components.json\n│   └── pages/\n│       ├── home.json\n│       ├── manifesto.json\n│       ├── docs.json\n│       ├── articles.json\n│       ├── curated-collections.json\n│       ├── stacks.json\n│       ├── comparison.json\n│       ├── landscape.json\n│       ├── open-source-rank.json\n│       └── search.json\n├── de/                    # German\n├── es/                    # Spanish\n├── fr/                    # French\n├── id/                    # Indonesian\n├── ja/                    # Japanese\n├── ko/                    # Korean\n├── pt/                    # Portuguese\n├── ru/                    # Russian\n├── tr/                    # Turkish\n├── zh-Hans/               # Simplified Chinese\n└── zh-Hant/               # Traditional Chinese\n```\n\n**Important:** Each locale must maintain the exact same file structure and JSON key order as `en/`.\n\n## I18n Architecture\n\nThe project has **two separate internationalization systems** that share the same 12 locale configuration:\n\n### 1. UI Translation System (next-intl)\n- **Purpose:** Translates static UI strings (buttons, labels, page content, etc.)\n- **Location:** `translations/{locale}/*.json`\n- **Usage:** Via `useTranslations()` hook or `getTranslations()` server function\n- **Managed by:** This skill''s sync and translate commands\n\n### 2. Manifest Translation System\n- **Purpose:** Translates manifest data (IDEs, CLIs, models, providers, etc.)\n- **Location:** `manifests/**/*.json` (in each manifest file''s `translations` field)\n- **Usage:** Via `localizeManifestItem()` and `localizeManifestItems()` functions\n- **Managed by:** Manual editing of manifest files or manifest automation tools\n\n**This skill manages only the UI Translation System.** For manifest translations, edit the manifest JSON files directly or use the manifest-automation skill.\n\n## Enabled Locales\n\nCurrently enabled locales in `src/i18n/config.ts`:\n- `en` - English (source of truth)\n- `de` - Deutsch (German)\n- `es` - Español (Spanish)\n- `fr` - Français (French)\n- `id` - Bahasa Indonesia (Indonesian)\n- `ja` - 日本語 (Japanese)\n- `ko` - 한국어 (Korean)\n- `pt` - Português (Portuguese)\n- `ru` - Русский (Russian)\n- `tr` - Türkçe (Turkish)\n- `zh-Hans` - 简体中文 (Simplified Chinese)\n- `zh-Hant` - 繁體中文 (Traditional Chinese)\n\nAll 12 locales are fully enabled and must be maintained in sync.\n\n## Subcommands\n\n### `sync`\n\nSynchronize all enabled locale directories with `en/` as the source of truth.\n\n**What it does:**\n\n- Scans all locale directories in `translations/` that are enabled in config\n- Compares each JSON file''s keys with the corresponding English file\n- **Adds missing keys** with English text as placeholder (needs translation)\n- **Removes extra keys** not present in English files\n- **Preserves JSON structure, key order, and formatting** (2-space indentation)\n- **Keeps the `index.ts` file structure** for each locale\n\n**Usage:**\n\nWhen you need to sync language files, use this command in Claude Code:\n\n```\nPlease run the i18n sync command\n```\n\nClaude Code will execute:\n\n```bash\nnode .claude/skills/i18n/scripts/sync.mjs\n```\n\n**Output Example:**\n\n```\n🔄 Syncing translation files with en/...\n\n✓ Synced de/\n  + Added 3 keys in components.json\n  + Added 5 keys in pages/home.json\n  - Removed 1 key in shared.json\n\n✓ Synced zh-Hans/\n  + Added 8 keys in pages/stacks.json\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n✓ Sync complete!\n  Modified: 2 locales\n  Added: 16 keys\n  Removed: 1 key\n```\n\n**When to use:**\n\n- After adding new keys to any English JSON file\n- After removing obsolete keys from any English JSON file\n- After adding new JSON files to the English structure\n- Before starting translation work (ensures all keys exist)\n- When adding a new locale\n\n---\n\n### `translate <locale>`\n\nGenerate translation tasks for Claude Code to translate missing content.\n\n**What it does:**\n\n- Reads all JSON files from `en/` and `<locale>/`\n- Identifies keys that need translation (currently in English or missing)\n- Outputs a structured translation task with guidelines\n- Provides context and instructions for accurate translation\n\n**Usage:**\n\nWhen you need to translate content, use this command in Claude Code:\n\n```\nPlease run the i18n translate command for ja\n```\n\nClaude Code will execute:\n\n```bash\nnode .claude/skills/i18n/scripts/translate.mjs ja\n```\n\n**Workflow:**\n\n1. The script outputs content that needs translation in JSON format\n2. Claude Code reads the guidelines and translates the content\n3. You provide the translated JSON back\n4. Claude Code updates the locale JSON files\n\n**Translation Guidelines (automatically enforced):**\n\n✓ **Preserve brand names:** `AI Coding Stack`, `Claude Code`, etc.\n✓ **Keep placeholders intact:** `{count}`, `{name}`, `${variable}`\n✓ **Don''t translate URLs:** `https://example.com`\n✓ **Don''t translate file paths:** `/path/to/file`\n✓ **Maintain terminology consistency** throughout the translation\n✓ **Preserve reference syntax:** `@:path.to.key` for internal references\n\n**Output Example:**\n\n```\n🌐 Translation Assistant for ja\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n📝 Translation Task\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nTarget Language: 日本語 (Japanese)\nEntries to translate: 15\n\nFiles affected:\n  - components.json: 5 entries\n  - pages/home.json: 8 entries\n  - shared.json: 2 entries\n\n⚠ Translation Guidelines:\n  1. Preserve brand names: \"AI Coding Stack\", \"Claude Code\"\n  2. Keep placeholders intact: {count}, {name}, ${variable}\n  3. Don''t translate URLs and file paths\n  4. Maintain consistent terminology\n  5. Preserve reference syntax: @:path.to.key\n\nContent to translate:\n\n```json\n{\n  \"components.languageSwitcher.english\": \"English\",\n  \"pages.home.hero.title\": \"Welcome to AI Coding Stack\",\n  \"shared.navigation.docs\": \"Documentation\",\n  ...\n}\n```\n```\n\n---\n\n## File Structure\n\n```\n.claude/skills/i18n/\n├── SKILL.md              # This documentation\n└── scripts/\n    ├── sync.mjs          # Synchronization script\n    └── translate.mjs     # Translation assistant script\n```\n\n## Technical Details\n\n**Language:** Node.js (ES Modules)\n**Dependencies:** Built-in Node.js modules only (`fs`, `path`)\n**JSON Format:** 2-space indentation, trailing newline\n**Encoding:** UTF-8\n\n### Translation File Structure\n\nEach locale has:\n1. **JSON files**: Contain the actual message data\n2. **index.ts**: Imports and assembles messages\n\n```typescript\n// translations/en/index.ts\nimport components from ''./components.json''\nimport articles from ''./pages/articles.json''\nimport comparison from ''./pages/comparison.json''\nimport curatedCollections from ''./pages/curated-collections.json''\nimport docs from ''./pages/docs.json''\nimport home from ''./pages/home.json''\nimport landscape from ''./pages/landscape.json''\nimport manifesto from ''./pages/manifesto.json''\nimport openSourceRank from ''./pages/open-source-rank.json''\nimport search from ''./pages/search.json''\nimport stacks from ''./pages/stacks.json''\nimport shared from ''./shared.json''\n\nconst messages = {\n  shared,\n  components,\n  pages: {\n    home,\n    manifesto,\n    docs,\n    articles,\n    curatedCollections,\n    stacks,\n    comparison,\n    landscape,\n    openSourceRank,\n    search,\n  },\n}\n\nexport default messages\n```\n\n### How Keys Are Compared\n\nThe scripts use recursive traversal to handle nested JSON structures. Keys are compared using dot notation:\n\n```json\n{\n  \"pages\": {\n    \"home\": {\n      \"hero\": {\n        \"title\": \"Welcome\"\n      }\n    }\n  }\n}\n```\n\nBecomes: `pages.home.hero.title = \"Welcome\"`\n\n### Adding a New Language\n\n**Note:** The project currently supports 12 locales. To add a new locale (e.g., Italian ''it''):\n\n1. Add the locale to `src/i18n/config.ts`:\n\n```typescript\nexport const locales = [\n  ''en'', ''de'', ''es'', ''fr'', ''id'', ''ja'', ''ko'', ''pt'', ''ru'', ''tr'', ''zh-Hans'', ''zh-Hant'',\n  ''it''  // Add new locale\n] as const;\n```\n\n2. Update locale names:\n\n```typescript\nexport const localeNames: Record<Locale, string> = {\n  // ... existing locales\n  it: ''Italiano'',\n}\n\nexport const localeToOgLocale: Record<Locale, string> = {\n  // ... existing locales\n  it: ''it_IT'',\n}\n```\n\n3. Add to translate.mjs LOCALE_NAMES (`.claude/skills/i18n/scripts/translate.mjs`):\n\n```javascript\nconst LOCALE_NAMES = {\n  // ... existing locales\n  it: ''Italiano (Italian)'',\n}\n```\n\n4. Create the locale directory structure:\n\n```bash\nmkdir -p translations/it/pages\ncp translations/en/index.ts translations/it/index.ts\ncp translations/en/*.json translations/it/\ncp translations/en/pages/*.json translations/it/pages/\n```\n\n5. Run sync to ensure structure matches:\n\n```\nPlease run the i18n sync command\n```\n\n6. Run translate to generate translation tasks:\n\n```\nPlease run the i18n translate command for it\n```\n\n## Best Practices\n\n1. **Always run `sync` before `translate`** to ensure all keys exist\n2. **Make changes to English files first**, then sync other locales\n3. **Review translations** for context accuracy, especially technical terms\n4. **Use Git** to track changes and review diffs before committing\n5. **Keep brand names consistent** across all languages\n6. **Test translations** in the actual UI to verify formatting and length\n7. **Preserve key order** to make diffs easier to review\n8. **Use reference syntax** (`@:path.to.key`) for reused content\n\n## Troubleshooting\n\n**Problem:** Script says \"directory not found\"\n\n- **Solution:** Ensure you''re running from project root\n- Check that `translations/` directory exists\n\n**Problem:** Keys are out of sync after adding new content\n\n- **Solution:** Run `sync` command to update all locale files\n\n**Problem:** Translation contains placeholders like `{0}` instead of `{count}`\n\n- **Solution:** Verify the English source uses named placeholders, re-translate\n\n**Problem:** Some text appears in English in the translated app\n\n- **Solution:** Run `translate` to find missing translations, check for English fallbacks\n\n**Problem:** index.ts imports are wrong after sync\n\n- **Solution:** The sync script preserves index.ts structure; manually check imports match actual JSON files\n\n## Integration with next-intl\n\nThis skill is designed to work with the project''s `next-intl` setup:\n\n```typescript\n// src/i18n/request.ts\nconst rawMessages = (await import(`../../translations/${locale}/index.ts`)).default\nconst messages = resolveReferences(rawMessages)\n```\n\nThe JSON files are loaded through the index.ts for each locale, and the `resolveReferences` function handles reference syntax.\n\n### Reference Resolution\n\nThe project supports **reference syntax** for reusing translations:\n\n**Basic Reference:** `@:path.to.key`\n```json\n{\n  \"shared\": {\n    \"appName\": \"AI Coding Stack\",\n    \"welcome\": \"Welcome to @:shared.appName\"\n  }\n}\n// Result: \"Welcome to AI Coding Stack\"\n```\n\n**Reference with Modifiers:** `@.modifier:path.to.key`\n\nSupported modifiers:\n- `@.upper:path` - Convert to UPPERCASE\n- `@.lower:path` - Convert to lowercase\n- `@.capitalize:path` - Capitalize first letter\n\n```json\n{\n  \"terms\": {\n    \"documentation\": \"documentation\",\n    \"title\": \"@.capitalize:terms.documentation Guide\"\n  }\n}\n// Result: \"Documentation Guide\"\n```\n\n**Important:**\n- References are resolved at runtime by `src/i18n/lib-core.ts`\n- Circular references are detected and will throw an error\n- References can be nested (references within references)\n- Keep reference syntax intact during translation\n\n## License\n\nThis skill is part of the AI Coding Stack project and follows the project''s Apache 2.0 license.\n"},"lastSynced":"2026-03-02T07:39:39.165Z","agentAnalysis":{"suitability":{"en":"Perfect for Multilingual AI Agents needing advanced internationalization capabilities with JSON message files","zh":"非常适合需要高级国际化功能的多语言AI代理，支持JSON消息文件","ja":"高度な国際化機能を必要とするマルチリンガルAIエージェントに最適で、JSONメッセージファイルをサポート","ko":"고급 국제화 기능이 필요한 다국어 AI 에이전트에게 적합하며, JSON 메시지 파일을 지원합니다","es":"Perfecto para Agentes de Inteligencia Artificial multilingües que necesitan capacidades de internacionalización avanzadas con archivos de mensajes JSON","fr":"Parfait pour les Agents d''Intelligence Artificielle multilingues ayant besoin de capacités d''internationalisation avancées avec des fichiers de messages JSON","de":"Perfekt für multilinguale KI-Agents, die erweiterte Internationalisierungsfunktionen mit JSON-Nachrichtendateien benötigen","pt":"Perfeito para Agentes de IA Multilíngues que necessitam de capacidades de internacionalização avançadas com arquivos de mensagens JSON","ru":"Идеально подходит для многоязычных агентов ИИ, которым необходимы расширенные возможности интернационализации с файлами сообщений JSON","ar":"مثالي لعميل الذكاء الاصطناعي المتعددة اللغات الذي يحتاج إلى إمكانيات دولية متقدمة مع ملفات رسائل JSON"},"recommendation":{"en":"Empowers agents to synchronize language files with English references and assist with translations using next-intl, providing seamless internationalization with JSON message files organized in the translations/ directory","zh":"赋予代理人使用next-intl与英语参考同步语言文件和协助翻译的能力，提供无缝的国际化功能，JSON消息文件组织在translations/目录中","ja":"next-intlを使用して英語の参照と言語ファイルを同期し、翻訳を支援する機能をエージェントに与え、translations/ディレクトリに組織されたJSONメッセージファイルを使用したシームレスな国際化を提供","ko":"next-intl을 사용하여 영어 참조와 언어 파일을 동기화하고, 번역을 지원하는 기능을 에이전트에게 부여하여, translations/ 디렉토리에 조직된 JSON 메시지 파일을 사용한 무шов한 국제화를 제공합니다","es":"Habilita a los agentes a sincronizar archivos de lenguaje con referencias en inglés y ayudar con traducciones utilizando next-intl, proporcionando una internacionalización fluida con archivos de mensajes JSON organizados en el directorio translations/","fr":"Permet aux agents de synchroniser les fichiers de langage avec des références en anglais et d''aider à la traduction à l''aide de next-intl, fournissant une internationalisation fluide avec des fichiers de messages JSON organisés dans le répertoire translations/","de":"Ermächtigt Agents, Sprachdateien mit englischen Referenzen zu synchronisieren und bei Übersetzungen mit next-intl zu helfen, wodurch eine nahtlose Internationalisierung mit JSON-Nachrichtendateien im translations/-Verzeichnis ermöglicht wird","pt":"Habilita os agentes a sincronizar arquivos de idioma com referências em inglês e ajudar com traduções usando next-intl, fornecendo uma internacionalização sem problemas com arquivos de mensagens JSON organizados no diretório translations/","ru":"Позволяет агентам синхронизировать файлы языка с английскими ссылками и помогать с переводами, используя next-intl, обеспечивая бесперебойную интернационализацию с файлами сообщений JSON, организованными в директории translations/","ar":"يتمكن العميل من مزامنة ملفات اللغة مع المراجع الإنجليزية ومساعدة الترجمات باستخدام next-intl، وتوفير دولية بدون مشاكل مع ملفات رسائل JSON المنظمة في الدليل translations/"},"useCases":{"en":["Synchronizing language files with English references","Assisting with translations for multilingual content","Managing JSON message files for internationalization"],"zh":["与英语参考同步语言文件","为多语言内容协助翻译","管理国际化的JSON消息文件"],"ja":["英語の参照と言語ファイルを同期","マルチリンガルコンテンツの翻訳を支援","国際化のJSONメッセージファイルを管理"],"ko":["영어 참조와 언어 파일을 동기화","다국어 콘텐츠의 번역을 지원","국제화의 JSON 메시지 파일을 관리합니다"],"es":["Sincronizar archivos de lenguaje con referencias en inglés","Ayudar con traducciones para contenido multilingüe","Administrar archivos de mensajes JSON para la internacionalización"],"fr":["Synchroniser les fichiers de langage avec des références en anglais","Aider à la traduction pour du contenu multilingue","Gérer les fichiers de messages JSON pour l''internationalisation"],"de":["Sprachdateien mit englischen Referenzen synchronisieren","Bei Übersetzungen für mehrsprachige Inhalte helfen","JSON-Nachrichtendateien für die Internationalisierung verwalten"],"pt":["Sincronizar arquivos de idioma com referências em inglês","Ajudar com traduções para conteúdo multilíngue","Gerenciar arquivos de mensagens JSON para internacionalização"],"ru":["Синхронизировать файлы языка с английскими ссылками","Помогать с переводами для многоязычного контента","Управлять файлами сообщений JSON для интернационализации"],"ar":["مزامنة ملفات اللغة مع المراجع الإنجليزية","مساعدة الترجمات للمحتوى المتعدد اللغات","إدارة ملفات رسائل JSON للتوحيد"]},"limitations":{"en":["Requires next-intl library","JSON message files must be organized in translations/ directory"],"zh":["需要next-intl库","JSON消息文件必须组织在translations/目录中"],"ja":["next-intlライブラリが必要","JSONメッセージファイルはtranslations/ディレクトリに組織する必要がある"],"ko":["next-intl 라이브러리가 필요","JSON 메시지 파일은 translations/ 디렉토리에 조직해야 합니다"],"es":["Requiere la biblioteca next-intl","Los archivos de mensajes JSON deben estar organizados en el directorio translations/"],"fr":["Nécessite la bibliothèque next-intl","Les fichiers de messages JSON doivent être organisés dans le répertoire translations/"],"de":["Benötigt die next-intl-Bibliothek","JSON-Nachrichtendateien müssen im translations/-Verzeichnis organisiert werden"],"pt":["Exige a biblioteca next-intl","Arquivos de mensagens JSON devem ser organizados no diretório translations/"],"ru":["Требует библиотеку next-intl","Файлы сообщений JSON должны быть организованы в директории translations/"],"ar":["يتطلب مكتبة next-intl","يجب تنظيم ملفات رسائل JSON في الدليل translations/"]},"version":3},"contentHash":"d46e075d29f64514056a20d1b66ddc46a7f0b325d23601db9a9455bedd197087","qualityScore":45}');
