INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wiggitywhitney/telemetry-agent-research/prd-phase', 'community', 'wiggitywhitney', 'telemetry-agent-research', 'wiggitywhitney/telemetry-agent-research', 'prd-phase', 0, 0, 45, '2026-03-03T01:53:42Z', '2026-03-03T04:00:13.354Z', '032f497723ef40b1792a383ea4790772cb6235922c83ac60ce9685b9f6ce816e', '{"id":"wiggitywhitney/telemetry-agent-research/prd-phase","name":"prd-phase","description":{"zh":"prd-phase框架是一种用于AI智能体的遥测仪表化代理研究和评估框架，能够高效地评估和优化AI系统","ja":"prd-phaseフレームワークは、AIエージェントのテレメトリーシステムの研究と評価フレームワークです。AIシステムを効率的に評価および最適化することができます","ko":"prd-phase 프레임워크는 AI 에이전트의 원격 측정 시스템 연구 및 평가 프레임워크로서 효율적으로 AI 시스템을 평가 및 최적화할 수 있습니다","es":"prd-phase es un marco de investigación y evaluación para agentes de telemetría con inteligencia artificial. Permite a los desarrolladores evaluar y mejorar la eficiencia de sus proyectos","fr":"prd-phase est un cadre de recherche et d''évaluation pour les agents de télémétrie avec intelligence artificielle. Il permet aux développeurs d''évaluer et d''améliorer l''efficacité de leurs projets","de":"prd-phase ist ein Bewertungsframework für Telemetrie-Agenten mit künstlicher Intelligenz. Es ermöglicht Entwicklern, die Effizienz ihrer Projekte zu bewerten und zu verbessern","pt":"O prd-phase é uma estrutura de pesquisa e avaliação para agentes de instrumentação de telemetria com IA, permitindo a integração com React, Python, Node.js e CLI","ru":"prd-phase - это исследовательская и оценочная база для ИИ агентов телеметрической инструментации, поддерживающая интеграцию с React, Python, Node.js и CLI","ar":"prd-phase هو إطار بحث وتقييم للوكلاء仪ات تелеметريا الذكاء الاصطناعي، يدعم التكامل مع React، Python، Node.js و CLI","en":"Research and evaluation framework for AI-powered telemetry instrumentation agents"},"seo":{"title":{"zh":"AI智能体prd-phase框架","ja":"AIエージェントのprd-phaseフレームワーク","ko":"AI 에이전트 prd-phase 프레임워크","es":"Agentes de Telemetría AI - prd-phase","fr":"Agents de Télémétrie IA - prd-phase","de":"AI-Telemetrie-Agenten - prd-phase","pt":"Ferramentas de Inteligência Artificial - prd-phase","ru":"ИИ Агенты - prd-phase","ar":"أدوات الذكاء الاصطناعي - prd-phase","en":"prd-phase"},"description":{"zh":"prd-phase框架是一种用于AI智能体的遥测仪表化代理研究和评估框架，能够高效地评估和优化AI系统","ja":"prd-phaseフレームワークは、AIエージェントのテレメトリーシステムの研究と評価フレームワークです。AIシステムを効率的に評価および最適化することができます","ko":"prd-phase 프레임워크는 AI 에이전트의 원격 측정 시스템 연구 및 평가 프레임워크로서 효율적으로 AI 시스템을 평가 및 최적화할 수 있습니다","es":"prd-phase es un marco de investigación y evaluación para agentes de telemetría con inteligencia artificial. Permite a los desarrolladores evaluar y mejorar l...","fr":"prd-phase est un cadre de recherche et d''évaluation pour les agents de télémétrie avec intelligence artificielle. Il permet aux développeurs d''évaluer et d''a...","de":"prd-phase ist ein Bewertungsframework für Telemetrie-Agenten mit künstlicher Intelligenz. Es ermöglicht Entwicklern, die Effizienz ihrer Projekte zu bewerten...","pt":"O prd-phase é uma estrutura de pesquisa e avaliação para agentes de instrumentação de telemetria com IA, permitindo a integração com React, Python, Node.js e...","ru":"prd-phase - это исследовательская и оценочная база для ИИ агентов телеметрической инструментации, поддерживающая интеграцию с React, Python, Node.js и CLI","ar":"prd-phase هو إطار بحث وتقييم للوكلاء仪ات تелеметريا الذكاء الاصطناعي، يدعم التكامل مع React، Python، Node.js و CLI","en":"Research and evaluation framework for AI-powered telemetry instrumentation agents"},"definition":{"en":"Research and evaluation framework for AI-powered telemetry instrumentation agents"},"features":{"zh":["支持AI智能体的遥测仪表化代理研究","提供高效的评估和优化方法","适用于各种AI系统和应用","支持多种编程语言和开发框架","提供详细的文档和示例代码"],"ja":["AIエージェントのテレメトリーシステムの研究をサポート","効率的な評価と最適化方法を提供","様々なAIシステムとアプリケーションに対応","多種のプログラミング言語と開発フレームワークをサポート","詳細なドキュメントとサンプルコードを提供"],"ko":["AI 에이전트의 원격 측정 시스템 연구를 지원","효율적인 평가 및 최적화 방법을 제공","다양한 AI 시스템 및 애플리케이션에 대응","다양한 프로그래밍 언어 및 개발 프레임워크를 지원","詳細한 문서 및 샘플 코드를 제공"],"es":["Marco de evaluación para agentes de telemetría","Integración con inteligencia artificial","Análisis de datos en tiempo real","Mejora de la eficiencia de los proyectos","Compatibilidad con múltiples plataformas"],"fr":["Cadre d''évaluation pour les agents de télémétrie","Intégration avec l''intelligence artificielle","Analyse de données en temps réel","Amélioration de l''efficacité des projets","Compatibilité avec plusieurs plates-formes"],"de":["Bewertungsframework für Telemetrie-Agenten","Integration mit künstlicher Intelligenz","Echtzeit-Datenanalyse","Verbesserung der Effizienz von Projekten","Kompatibilität mit mehreren Plattformen"],"pt":["Estrutura de pesquisa e avaliação para agentes de instrumentação de telemetria com IA","Integração com React, Python, Node.js e CLI","Suporte a agentes de telemetria para coletar dados de desempenho","Análise de dados em tempo real com IA","Relatórios personalizados para visualização de dados"],"ru":["Исследовательская и оценочная база для ИИ агентов телеметрической инструментации","Интеграция с React, Python, Node.js и CLI","Поддержка агентов телеметрии для сбора данных о производительности","Анализ данных в реальном времени с ИИ","Пользовательские отчеты для визуализации данных"],"ar":["إطار بحث وتقييم للوكلاء仪ات تليميتيا الذكاء الاصطناعي","التكامل مع React، Python، Node.js و CLI","دعم وكلاء التليميتيا لجمع بيانات الأداء","تحليل البيانات في الوقت الفعلي بالذكاء الاصطناعي","تقارير مخصصة لتصور البيانات"]},"keywords":{"zh":["AI智能体","遥测仪表化代理","prd-phase框架","AI系统优化","如何使用prd-phase","prd-phase教程","AI智能体开发","遥测仪表化代理研究","AI系统评估"],"ja":["AIエージェント","テレメトリーシステム","prd-phaseフレームワーク","AIシステム最適化","prd-phaseの使い方","prd-phaseチュートリアル","AIエージェント開発","テレメトリーシステム研究","AIシステム評価"],"ko":["AI 에이전트","원격 측정 시스템","prd-phase 프레임워크","AI 시스템 최적화","prd-phase 사용법","prd-phase 튜토리얼","AI 에이전트 개발","원격 측정 시스템 연구","AI 시스템 평가"],"es":["cómo usar prd-phase","qué es un agente de telemetría AI","prd-phase alternativa","prd-phase vs New Relic","instalación de prd-phase","guía de configuración de prd-phase"],"fr":["comment utiliser prd-phase","qu''est-ce qu''un agent de télémétrie IA","alternative à prd-phase","prd-phase vs New Relic","installation de prd-phase","guide de configuration de prd-phase"],"de":["wie man prd-phase verwendet","was ist ein AI-Telemetrie-Agent","Alternative zu prd-phase","prd-phase vs New Relic","Installation von prd-phase","Konfigurationsanleitung für prd-phase"],"pt":["como usar prd-phase","o que é prd-phase","alternativas para prd-phase","prd-phase vs new relic","instalar prd-phase","guia de configuração do prd-phase","desenvolvimento de agentes de telemetria com IA","integração de prd-phase com React","prd-phase e Python"],"ru":["как использовать prd-phase","что такое prd-phase","альтернативы prd-phase","prd-phase vs new relic","установка prd-phase","руководство по настройке prd-phase","разработка агентов телеметрии с ИИ","интеграция prd-phase с React","prd-phase и Python"],"ar":["كيفية استخدام prd-phase","ما هو prd-phase","بديلات ل prd-phase","prd-phase مقابل new relic","تثبيت prd-phase","دليل إعداد prd-phase","تطوير وكلاء التليميتيا بالذكاء الاصطناعي","تكامل prd-phase مع React","prd-phase و Python"]}},"owner":"wiggitywhitney","repo":"telemetry-agent-research","repoPath":"wiggitywhitney/telemetry-agent-research","stars":0,"forks":0,"updatedAt":"2026-03-03T01:53:42Z","topics":[],"category":"community","skillMd":{"name":"prd-phase","description":"Create implementation phase PRDs from pre-existing research for the telemetry agent. Translates already-complete research into focused, bounded PRDs. Use when the user says prd-phase N or wants to create a PRD for a specific build phase (1-7). Do NOT use for new feature discovery — use prd-create for that.","bodyPreview":"# Phase PRD Creation\n\n## Purpose\n\nCreate implementation phase PRDs for the telemetry agent by assembling content from existing research documents. All research is complete. The job is to route to the right documents, extract the right details, and produce a focused PRD.\n\n## Critical Principles\n\n1. **Bounded context**: Read ONLY what this phase needs. Do not read the full spec or full tech stack document. Read the specific sections listed in the routing tables below.\n2. **No detail loss**: Versio","body":"# Phase PRD Creation\n\n## Purpose\n\nCreate implementation phase PRDs for the telemetry agent by assembling content from existing research documents. All research is complete. The job is to route to the right documents, extract the right details, and produce a focused PRD.\n\n## Critical Principles\n\n1. **Bounded context**: Read ONLY what this phase needs. Do not read the full spec or full tech stack document. Read the specific sections listed in the routing tables below.\n2. **No detail loss**: Version numbers, API patterns, config field names, and code snippets must be copied verbatim from source documents into the PRD. Do not summarize technical details.\n3. **Excerpt, don''t just reference**: Critical details (acceptance gates, API patterns, rubric rules) must be IN the PRD, not just referenced by section name.\n4. **One phase at a time**: Never create multiple phase PRDs in one session. Each phase gets a fresh context.\n5. **TypeScript and ESM**: The agent is TypeScript (`\"type\": \"module\"` in package.json, native Node.js type stripping via `erasableSyntaxOnly`). All code samples use ESM `import` syntax and TypeScript interface notation. ts-morph is used for AST analysis (it handles JavaScript target files via `allowJs: true`).\n\n## Process\n\n### Step 1: Identify the Phase\n\nParse the phase number (1-7) from the user''s command.\n\n### Step 2: Read the Phase Definition\n\nRead the specific phase section from `docs/specs/research/implementation-phasing.md`. Each phase contains:\n- What Gets Built\n- Acceptance Gate\n- Rubric Rules That Apply\n- Why This Boundary\n- Spec Sections (table mapping to spec sections and subsections)\n\n**Also read these cross-cutting sections** (they apply to every phase):\n- \"Two-Tier Validation Architecture\" section\n- \"Cross-Cutting: The DX Principle\" section\n\n### Step 2b: Read Previous Phase PRD (Phase 2+ only)\n\n**Skip this step for Phase 1** — it has no predecessor.\n\nFor Phase 2+, read the previous phase''s PRD file (`prds/[id]-phase-[N-1]-*.md`). Focus on:\n\n1. **Decision Log**: Extract any decisions that changed interfaces, types, or contracts from what the design document planned\n2. **Interface changes**: Compare the previous phase''s delivered interface with what `docs/architecture/design-document.md` defines for the Phase N-1 → Phase N boundary\n\nInclude deviations in the new PRD''s Dependencies section as:\n> Phase N-1 delivered [interface/type] (with these modifications from plan: [list changes]).\n\nIf the previous phase''s decision log and design document agree (no deviations), note: \"Phase N-1 delivered interfaces as planned in the design document.\"\n\n### Step 3: Read Source Documents (Routing)\n\nRead ONLY the sections relevant to this phase.\n\n#### 3a. Spec Sections\n\nThe phase definition contains a \"Spec Sections\" table. For each row:\n- **Full** -> read the entire section from `docs/specs/telemetry-agent-spec-v3.9.md`\n- **Subsection only** -> read only the named subsection\n- **Fields only** -> extract just the named configuration fields\n- **Row only** -> extract just the named row from the Technology Stack table\n\n**Note**: The spec was renamed from v3.5.md → v3.6.md → v3.7.md → v3.8.md → v3.9.md as content versions evolved.\n\n**Spec section landmarks** (line numbers for the 1,791-line spec):\n\n| Section | Line | Key Subsections |\n|---------|------|-----------------|\n| Architecture | 55 | Coordinator+Agents 57, Coordinator API 130, Error Handling 160, Interfaces 193, Tech Stack 220, Weaver Integration 253 |\n| Init Phase (Required) | 290 | What Init Does 294, Prerequisites 324 |\n| Complete Workflow | 334 | (diagram through ~397) |\n| How It Works | 397 | Input 399, Processing (per file) 404, Output 420, Agent Output Format 424, System Prompt Structure 438, Known Failure Modes 468, Elision Detection 484 |\n| File/Directory Processing | 494 | File Revert Protocol 506, Periodic Schema Checkpoints 512 |\n| What Gets Instrumented | 528 | Priority Hierarchy 530, Review Sensitivity 543, Patterns Not Covered 560 |\n| What the Agent Actually Does to Code | 573 | Path 1: Auto-Instrumentation 577, Path 2: Manual Span 647, Decision: Which Path? 711 |\n| Attribute Priority Chain | 721 | Schema Extension Guardrails 731 |\n| Auto-Instrumentation Libraries | 745 | Why Libraries First 749, Detection Flow 755, Library Discovery 774 |\n| Validation Chain | 874 | Per-File Validation (with fix loop) 878, End-of-Run Validation 983 |\n| Agent Self-Instrumentation | 1020 | |\n| Handling Existing Instrumentation | 1079 | |\n| Schema as Source of Truth | 1097 | |\n| Result Data | 1106 | Result Structure 1116, Run-Level Result 1211, PR Summary 1241, Schema Hash Tracking 1255 |\n| Configuration | 1261 | What Goes Where 1312, Dependency Strategy 1352, Cost Visibility 1367 |\n| Minimum Viable Schema Example | 1381 | |\n| PoC Scope | 1577 | In Scope 1579, Out of Scope 1626 |\n| Evaluation & Acceptance Criteria | 1642 | Two-Tier Validation Architecture 1676, Required Verification Levels 1710 |\n\n#### 3b. Tech Stack Sections\n\nRead `references/tech-stack-by-phase.md` (bundled with this skill) to find which sections of `docs/architecture/tech-stack-evaluation.md` to read for this phase. Extract:\n- Version numbers (exact)\n- API patterns (code snippets, verbatim)\n- Caveats and limitations\n- Recommendation summaries\n\n#### 3c. Rubric Rules\n\nThe phase definition lists rubric rule IDs (e.g., NDS-001, CDQ-003). Look up each rule''s full definition in `research/evaluation-rubric.md`. The code-level rules are in **Part 2: Code-Level Evaluation** (line 136), organized as:\n\n| Dimension | Location | Rules |\n|-----------|----------|-------|\n| Gate Checks | ~line 140 | NDS-001, NDS-002, NDS-003, API-001 |\n| Non-Destructiveness | ~line 189 | NDS-004, NDS-005 |\n| Coverage | ~line 218 | COV-001 through COV-006 |\n| Restraint | ~line 282 | RST-001 through RST-005 |\n| API-Only Dependency | ~line 337 | API-002, API-003, API-004 |\n| Schema Fidelity | ~line 374 | SCH-001 through SCH-004 |\n| Code Quality | ~line 422 | CDQ-001 through CDQ-008 |\n\nFor each rule, extract: Rule ID, name, impact level, evaluation scope, full description including evaluation method, and automation classification (summary at ~line 514).\n\nFor Phase 2+, classify rules as Tier 1 (structural/blocking) vs Tier 2 (semantic/blocking or advisory) using the \"Two-Tier Validation Architecture\" section of implementation-phasing.md.\n\n#### 3d. Architectural Context (if needed)\n\nRead relevant sections of `docs/architecture/recommendations.md`:\n- Phases 1-3: \"Fix Loop Feedback Quality\" subsection\n- Phase 2: \"Two-Tier Validation (New Architecture)\" section\n- Phases 4-7: \"DX and Error Handling Architecture\" section\n- All phases: Summary table at end for quick reference\n\n#### 3e. Design Document\n\nRead relevant sections of `docs/architecture/design-document.md`. This document defines cross-phase interface contracts, module organization, and a consolidated decision register.\n\n**All phases — read these sections:**\n- Module Organization (line 312): Directory Structure (314), Module Dependency Rules (337)\n- Phase-to-Module Mapping (line 360): which modules get built in which phase\n- Consolidated Decision Register (line 376): design decisions that may affect implementation\n\n**Phase-specific interface contracts:**\n\n| Phase | Section | Line | Key Types/Contracts |\n|-------|---------|------|---------------------|\n| 1 | Phase 1 → Phase 2: Instrumentation Output | 29 | `instrumentFile` interface, `InstrumentationOutput` type |\n| 2 | Phase 2 → Phase 3: Validation Results | 84 | `validateFile` interface, `ValidationResult`/`CheckResult` types, `ValidateFileInput` |\n| 3 | Phase 3 → Phase 4: File-Level Result | 151 | `instrumentWithRetry` interface, `FileResult` evolution, schema re-resolution |\n| 4 | Phase 4 → Phase 5/6: Run-Level Result | 211 | `coordinate` interface, `RunResult` type, `CoordinatorCallbacks` |\n| 5 | Phase 5: Schema Integration Extensions | 254 | Schema integration extensions to `RunResult` |\n| 6 | Phase 6: Interface Layer | 262 | `CostCeiling`, `CoordinatorCallbacks` (wiring focus) |\n| 7 | Phase 7: Deliverables | 290 | `RunResult` consumption for git/PR, `advisoryAnnotations` flow |\n\nAlso read the Interface Contract Summary table (line 294) for a quick reference of all contracts.\n\nExtract from the design document into the PRD:\n- The interface contract relevant to this phase (input types, output types, function signature)\n- Any decision register entries that affect this phase''s implementation\n- The module directory paths this phase creates (from the Phase-to-Module Mapping)\n\n### Step 4: Assemble the PRD\n\nRead `references/phase-prd-template.md` (bundled with this skill) for the output template.\n\nFill in each section using content gathered in Steps 2-3. Key rules:\n\n**Tech Stack section:**\n- Copy version numbers exactly (e.g., \"Vitest 4.0.18\", not \"latest\")\n- Copy API code snippets verbatim — all TypeScript, ESM imports\n- Include caveats that affect THIS phase\n- Include only entries relevant to this phase\n\n**Rubric Rules section:**\n- Include the full rule definition, not just the ID\n- Group by Gate vs Dimension\n- Note which are Tier 1 vs Tier 2 (for Phase 2+)\n- Include impact level and automation classification\n\n**Acceptance Gate section:**\n- Copy the gate verbatim from the phasing document\n- Add specific, testable verification steps\n- Map each gate criterion to the rubric rules that verify it\n\n**Milestones:**\n- Define 5-8 milestones that build toward the acceptance gate incrementally\n- Each milestone should be independently testable\n- Final milestone: \"Acceptance gate passes end-to-end\"\n- Include a milestone for the DX cross-cutting requirement specific to this phase\n- Use the Phase-to-Module Mapping from the design document (Step 3e) to identify which module directories this phase creates — milestones should align with the module structure\n- Where a milestone directly satisfies a rubric rule, note the rule ID (e.g., \"Tier 1 syntax check works → NDS-001\"). Not every milestone maps to a rubric rule — Phase 1 milestones about prompt engineering and file I/O have no clean rubric connection, and stretching for one adds noise. Phase 2 (validation chain) maps naturally. Include the mapping where it''s real; omit it where it isn''t.\n\n**Spec Reference section:**\n- Reproduce the spec section map table from the phasing document\n- Add line number ranges from the landmarks table above\n\n### Step 5: Create GitHub Issue and PRD File\n\nFollow the same workflow as `/prd-create`:\n\n1. **Create GitHub Issue** with label \"PRD\":\n   ```markdown\n   ## PRD: Phase N — [Phase Name]\n\n   **Problem**: Implementation phase N of the telemetry agent — [what gets built]\n\n   **Solution**: [1-2 sentence summary from phasing document]\n\n   **Detailed PRD**: Will be added after PRD file creation\n\n   **Priority**: High\n   ```\n\n2. **Create PRD file** at `prds/[issue-id]-phase-N-[phase-name].md`\n\n3. **Update GitHub Issue** with PRD link\n\n4. **Commit** with `[skip ci]` flag:\n   ```text\n   docs(prd-[issue-id]): create Phase N PRD — [phase-name] [skip ci]\n   ```\n\n### Step 6: Post-Creation Verification\n\nBefore presenting the PRD to the user, verify:\n\n- [ ] Every rubric rule ID listed in the phasing document appears with its full definition\n- [ ] Every spec section from the phase''s spec section map is referenced with line numbers\n- [ ] Tech stack version numbers are exact (not \"latest\" or \"current\")\n- [ ] API code snippets are present and use TypeScript ESM syntax\n- [ ] The acceptance gate is copied verbatim from the phasing document\n- [ ] The DX cross-cutting requirement for this phase is included\n- [ ] No content from other phases leaked in\n- [ ] Milestones build incrementally toward the acceptance gate\n- [ ] All agent code samples are TypeScript; target file examples remain JavaScript\n\n## Source Documents\n\n| Document | Path | Purpose |\n|----------|------|---------|\n| Implementation Phasing | `docs/specs/research/implementation-phasing.md` | Phase definitions, spec section maps, cross-cutting architecture |\n| Telemetry Agent Spec | `docs/specs/telemetry-agent-spec-v3.9.md` | Source of truth for what to build |\n| Tech Stack Evaluation | `docs/architecture/tech-stack-evaluation.md` | Version numbers, API patterns, library choices |\n| Evaluation Rubric | `research/evaluation-rubric.md` | Full rule definitions for acceptance criteria |\n| Architectural Recommendations | `docs/architecture/recommendations.md` | Preserve/change verdicts, evidence base |\n| Design Document | `docs/architecture/design-document.md` | Interface contracts, module organization, decision register |\n| Tech Stack by Phase | `references/tech-stack-by-phase.md` (skill-bundled) | Routing table: which tech stack sections per phase |\n| Phase PRD Template | `references/phase-prd-template.md` (skill-bundled) | Output template |\n\n## Important Notes\n\n- **One phase per session.** Multiple phase PRDs in one context risks detail loss.\n- **The spec is the source of truth.** If the phasing document and spec disagree, the spec wins. Flag the discrepancy for the user.\n- **Don''t include evaluation findings.** The implementing AI needs what to build, not why the last attempt failed.\n- **Don''t include rejected alternatives.** No LangGraph comparisons, no Babel evaluations.\n- **Trust the routing tables.** Don''t add \"extra context that might be helpful.\"\n- **TypeScript for agent code, JavaScript for target files.** The agent code is TypeScript with ESM modules (native type stripping, `erasableSyntaxOnly`). ts-morph handles JavaScript target files via `allowJs: true`. Agent code samples use TypeScript; target file examples remain JavaScript.\n\n**Note**: If any `gh` command fails with \"command not found\", inform the user that GitHub CLI is required: https://cli.github.com/\n"},"lastSynced":"2026-03-03T04:00:13.354Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing structured content analysis for PRD creation","zh":"适合需要结构化内容分析以创建 PRD 的技术写作代理","ja":"技術文書作成エージェントが構造化されたコンテンツ分析を必要とする PRD 作成に適しています","ko":"구조화된 내용 분석이 필요한 기술 문서 에이전트를 위한 PRD 생성에 적합합니다","es":"Perfecto para Agentes de Escritura Técnica que necesitan análisis de contenido estructurado para la creación de PRD","fr":"Parfait pour les agents de rédaction technique ayant besoin d''une analyse de contenu structurée pour la création de PRD","de":"Perfekt für technische Schreibagenten, die eine strukturierte Inhaltsanalyse für die Erstellung von PRD benötigen","pt":"Perfeito para Agentes de Redação Técnica que necessitam de análise de conteúdo estruturada para criação de PRD","ru":"Идеально для технических писателей, которым требуется структурированный анализ контента для создания PRD","ar":"مثالي للوكيلين الكتابة الفنية الذين يحتاجون إلى تحليل المحتوى المنظم لإنشاء PRD"},"recommendation":{"en":"Empowers agents to assemble focused PRDs by extracting relevant details from existing research documents, utilizing routing tables and bounded context principles to ensure no detail loss, and supporting versio","zh":"赋予代理人通过从现有研究文档中提取相关细节、利用路由表和有界上下文原则以确保不会丢失细节并支持版本来编制集中式 PRD 的能力","ja":"ルーティングテーブルとバウンダリーコンテキストの原則を使用して、既存の研究文書から関連する詳細を抽出し、バージョンをサポートすることで、集中した PRD を作成するエージェントの能力を強化します","ko":"기존 연구 문서에서 관련된 세부 사항을 추출하고, 라우팅 테이블 및 경계 컨텍스트 원칙을 사용하여 세부 사항의 손실이 없도록 하며, 버전을 지원하여 집중된 PRD를 조립할 수 있는 에이전트의 능력을 강화합니다","es":"Habilita a los agentes a ensamblar PRD enfocados extrayendo detalles relevantes de documentos de investigación existentes, utilizando tablas de enrutamiento y principios de contexto acotado para garantizar que no se pierdan detalles y admitiendo versiones","fr":"Permet aux agents d''assembler des PRD ciblés en extrayant des détails pertinents de documents de recherche existants, en utilisant des tableaux de routage et des principes de contexte limité pour s''assurer qu''aucun détail ne soit perdu et en prenant en charge les versions","de":"Ermöglicht es Agenten, PRD zusammenzustellen, indem sie relevante Details aus bestehenden Forschungsdokumenten extrahieren, Routing-Tabellen und Prinzipien des begrenzten Kontexts verwenden, um sicherzustellen, dass keine Details verloren gehen, und Versionen unterstützen","pt":"Habilita os agentes a montar PRDs focados, extrair detalhes relevantes de documentos de pesquisa existentes, utilizando tabelas de roteamento e princípios de contexto limitado para garantir que nenhum detalhe seja perdido, e suportar versão","ru":"Наделяет агентов возможностью собрать сосредоточенные PRD, извлекая соответствующие детали из существующих исследовательских документов, используя маршрутизационные таблицы и принципы ограниченного контекста, чтобы гарантировать, что ни один деталь не будет потерян, и поддерживать версию","ar":"يمنح الوكلاء khảية تجميع PRDs محددة، واستخراج التفاصيل الرئيسية من وثائق البحث الحالية، باستخدام جداول التوجيه ومبادئ السياق المقيد لضمان عدم فقدان أي تفاصيل، ودعم الإصدار"},"useCases":{"en":["Assembling implementation phase PRDs","Extracting key details from research documents","Creating focused PRDs with bounded context"],"zh":["组装实现阶段 PRD","从研究文档中提取关键细节","使用有界上下文创建集中式 PRD"],"ja":["実装フェーズの PRD を組み立てる","研究文書から重要な詳細を抽出する","境界付きコンテキストを使用して集中した PRD を作成する"],"ko":["구현 단계의 PRD 조립","연구 문서에서 주요 세부 사항 추출","경계 컨텍스트를 사용하여 집중된 PRD 생성"],"es":["Ensamblar PRD de la fase de implementación","Extraer detalles clave de documentos de investigación","Crear PRD enfocados con contexto acotado"],"fr":["Assembler les PRD de la phase de mise en œuvre","Extraire des détails clés de documents de recherche","Créer des PRD ciblés avec un contexte limité"],"de":["Zusammenstellung von PRD in der Implementierungsphase","Extrahieren von Schlüsseldetails aus Forschungsdokumenten","Erstellen von PRD mit begrenztem Kontext"],"pt":["Montagem da fase de implementação de PRDs","Extração de detalhes-chave de documentos de pesquisa","Criação de PRDs focados com contexto limitado"],"ru":["Сборка фазы реализации PRD","Извлечение ключевых деталей из исследовательских документов","Создание сосредоточенных PRD с ограниченным контекстом"],"ar":["تجميع مرحلة التنفيذ من PRDs","استخراج التفاصيل الرئيسية من وثائق البحث","إنشاء PRDs محددة مع سياق مقيد"]},"limitations":{"en":["Requires existing research documents","Limited to specific sections listed in routing tables"],"zh":["需要现有的研究文档","仅限于路由表中列出的特定部分"],"ja":["既存の研究文書が必要","ルーティングテーブルに記載された特定のセクションのみに限定される"],"ko":["기존 연구 문서가 필요","라우팅 테이블에 나열된 특정 섹션만 제한"],"es":["Requiere documentos de investigación existentes","Limitado a secciones específicas enumeradas en las tablas de enrutamiento"],"fr":["Nécessite des documents de recherche existants","Limité à des sections spécifiques répertoriées dans les tableaux de routage"],"de":["Benötigt bestehende Forschungsdokumente","Begrenzt auf bestimmte in den Routing-Tabellen aufgeführte Abschnitte"],"pt":["Requer documentos de pesquisa existentes","Limitado a seções específicas listadas em tabelas de roteamento"],"ru":["Требует существующих исследовательских документов","Ограничен конкретными разделами, перечисленными в маршрутизационных таблицах"],"ar":["يتطلب وثائق بحث موجودة","محدود إلى أقسام محددة مدرجة في جداول التوجيه"]},"version":3},"contentHash":"032f497723ef40b1792a383ea4790772cb6235922c83ac60ce9685b9f6ce816e","qualityScore":45}');
