INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('boisenoise/skills-collections/fastapi-templates', 'fastapi-templates', 'boisenoise', 'skills-collections', 'community', 'fastapi-templates boisenoise skills-collections community fastapi-templates是用于学习FastAPI的最佳实践，帮助开发者提高开发效率 fastapi-templatesはFastAPIのベストプラクティスを学ぶためのツールで、開発者の開発効率を向上させる fastapi-templates는 FastAPI의 베스트 프랙티스를 학습하여 개발자의 개발 효율을 향상시키는 데 도움을 주는 툴입니다 Nuestras plantillas FastAPI están diseñadas para ayudar a los desarrolladores a aprender de los mejores y mejorar sus habilidades con herramientas AI Nos modèles FastAPI sont conçus pour aider les développeurs à apprendre des meilleurs et améliorer leurs compétences avec des outils IA Unsere FastAPI-Vorlagen sind dafür entwickelt, Entwicklern zu helfen, von den Besten zu lernen und ihre Fähigkeiten mit KI-Tools zu verbessern O fastapi-templates é uma ferramenta de IA para desenvolvedores que busca reunir as melhores habilidades para aprender com os melhores Fastapi-templates - это ИИ Агент для разработчиков, который объединяет лучшие навыки для обучения у лучших fastapi-templates هي أداة ذكاء اصطناعي للمطورين التي تهدف إلى جمع أفضل المهارات للتعلم من الأفضل Getting Skills Together to Learn from the Best FastAPI模板 FastAPI开发 AI工具 FastAPI框架 如何使用FastAPI FastAPI与Django对比 FastAPI安装 FastAPI设置指南 Getting Skills Together to Learn from the Best');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('holon-run/holon/ghx', 'community', 'holon-run', 'holon', 'holon-run/holon', 'ghx', 0, 0, 45, '2026-03-04T13:07:01.671Z', '2026-03-04T13:22:34.150Z', 'bb1a47edffee032ba03ed5d500e15eb527261f0c7125dc21a2b2191845f0826e', '{"id":"holon-run/holon/ghx","name":"ghx","description":{"zh":"ghx AI智能代理可以自动化代码问题的修复和总结，支持本地和CI环境","ja":"ghx AIエージェントはコードの問題を自動的に修復してサマリーを作成し、ローカルおよびCI環境をサポートする","ko":"ghx AI 에이전트는 코드 문제를 자동으로 수정하고 요약하며 로컬 및 CI 환경을 지원합니다","es":"Holon ejecuta agentes de codificación de IA de forma headless para convertir problemas en parches y resúmenes listos para PR","fr":"Holon exécute des agents de codage IA de manière headless pour convertir les problèmes en patches et résumés prêts pour PR","de":"Holon führt AI-Coding-Agenten headless aus, um Probleme in PR-fertige Patches und Zusammenfassungen umzuwandeln","pt":"O ghx é uma ferramenta de AI Agents que ajuda a automatizar a codificação e melhorar a produtividade dos desenvolvedores","ru":"ИИ Агенты ghx - это инструмент, который помогает автоматизировать кодирование и повысить производительность разработчиков","ar":"آداة ghx هي أداة إيمان عقلانية تساعد المطورين على تحسين الإنتاجية وتوفير الوقت","en":"Holon runs AI coding agents headlessly to turn issues into PR-ready patches and summaries — locally or in CI, without babysitting the agent."},"seo":{"title":{"zh":"AI智能代理ghx：自动化代码补丁和总结","ja":"AIエージェントghx：コードパッチとサマリーの自動化","ko":"AI 에이전트 ghx: 자동화된 코드 패치 및 요약","es":"Herramientas de Agentes de IA: ghx para desarrolladores","fr":"Outils d''Agents IA: ghx pour les développeurs","de":"AI-Tools: ghx für Entwickler","pt":"Ferramentas de AI Agents: ghx para Desenvolvedores","ru":"ИИ Агенты: ghx для Автоматизации Кодирования","ar":"أدوات الإيمان العقلانية: ghx لتنمية البرمجيات","en":"ghx"},"description":{"zh":"ghx AI智能代理可以自动化代码问题的修复和总结，支持本地和CI环境","ja":"ghx AIエージェントはコードの問題を自動的に修復してサマリーを作成し、ローカルおよびCI環境をサポートする","ko":"ghx AI 에이전트는 코드 문제를 자동으로 수정하고 요약하며 로컬 및 CI 환경을 지원합니다","es":"Holon ejecuta agentes de codificación de IA de forma headless para convertir problemas en parches y resúmenes listos para PR","fr":"Holon exécute des agents de codage IA de manière headless pour convertir les problèmes en patches et résumés prêts pour PR","de":"Holon führt AI-Coding-Agenten headless aus, um Probleme in PR-fertige Patches und Zusammenfassungen umzuwandeln","pt":"O ghx é uma ferramenta de AI Agents que ajuda a automatizar a codificação e melhorar a produtividade dos desenvolvedores","ru":"ИИ Агенты ghx - это инструмент, который помогает автоматизировать кодирование и повысить производительность разработчиков","ar":"آداة ghx هي أداة إيمان عقلانية تساعد المطورين على تحسين الإنتاجية وتوفير الوقت","en":"Holon runs AI coding agents headlessly to turn issues into PR-ready patches and summaries — locally or in CI, without babysitting the agent."},"definition":{"en":"Holon runs AI coding agents headlessly to turn issues into PR-ready patches and summaries — locally or in CI, without babysitting the agent."},"features":{"zh":["自动化代码问题的修复","支持本地和CI环境","代码总结和报告","提高开发效率","支持多种编程语言"],"ja":["コードの問題を自動的に修復","ローカルおよびCI環境をサポート","コードサマリーとレポート","開発効率の向上","複数のプログラミング言語をサポート"],"ko":["코드 문제를 자동으로 수정","로컬 및 CI 환경을 지원","코드 요약 및 보고","개발 효율성을 높임","여러 프로그래밍 언어를 지원"],"es":["Ejecución headless de agentes de codificación de IA","Conversión de problemas en parches y resúmenes listos para PR","Integración con CI/CD","Resumen automático de problemas","Parches listos para PR sin supervisión"],"fr":["Exécution headless des agents de codage IA","Conversion des problèmes en patches et résumés prêts pour PR","Intégration avec CI/CD","Résumé automatique des problèmes","Patches prêts pour PR sans surveillance"],"de":["Headless-Ausführung von AI-Coding-Agenten","Umwandlung von Problemen in PR-fertige Patches und Zusammenfassungen","Integration mit CI/CD","Automatische Zusammenfassung von Problemen","PR-fertige Patches ohne Aufsicht"],"pt":["Execução de codificação de forma automatizada","Melhoria da produtividade dos desenvolvedores","Integração com ferramentas de CI","Geração de patches e resumos PR-prontos","Execução headless sem supervisão"],"ru":["Автоматизированное кодирование","Повышение производительности разработчиков","Интеграция с инструментами CI","Генерация патчей и резюме PR-готовых","Выполнение без надзора"],"ar":["تنفيذ العمليات البرمجية بشكل تلقائي","تحسين الإنتاجية للمطورين","التكامل مع أدوات CI","توليد تصحيحات وملخصات PR-جاهزة","التنفيذ بدون إشراف"]},"keywords":{"zh":["AI智能代理","代码自动修复","代码总结","开发效率","ghx AI智能代理","代码问题解决","自动化代码修复","CI环境支持"],"ja":["AIエージェント","コード自動修復","コードサマリー","開発効率","ghx AIエージェント","コード問題解決","自動化コード修復","CI環境サポート"],"ko":["AI 에이전트","코드 자동 수정","코드 요약","개발 효율성","ghx AI 에이전트","코드 문제 해결","자동화 코드 수정","CI 환경 지원"],"es":["cómo usar ghx","qué es un agente de IA","ghx alternativa","ghx vs otros agentes de IA","instalación de ghx","guía de configuración de ghx","desarrollo de software con IA","automatización de codificación con IA"],"fr":["comment utiliser ghx","qu''est-ce qu''un agent IA","ghx alternative","ghx vs autres agents IA","installation de ghx","guide de configuration de ghx","développement de logiciels avec IA","automatisation de codage avec IA"],"de":["wie man ghx verwendet","was ist ein AI-Agent","ghx Alternative","ghx vs andere AI-Agenten","Installation von ghx","Einrichtungsanleitung für ghx","Softwareentwicklung mit AI","Automatisierung von Codierung mit AI"],"pt":["como usar ghx","o que é ghx","ferramentas de AI Agents","alternativas ao ghx","ghx vs outras ferramentas","instalar ghx","guia de configuração do ghx"],"ru":["как использовать ghx","что такое ghx","инструменты ИИ Агентов","альтернативы ghx","ghx vs другие инструменты","установить ghx","руководство по настройке ghx"],"ar":["كيفية استخدام أداة ghx","ما هي أداة ghx","أدوات الإيمان العقلانية","بديلات أداة ghx","أداة ghx مقابل أدوات أخرى","تثبيت أداة ghx","دليل إعداد أداة ghx"]}},"owner":"holon-run","repo":"holon","repoPath":"holon-run/holon","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.671Z","topics":[],"category":"community","skillMd":{"name":"ghx","description":"GitHub enhanced operations skill. Provides unified context collection and publishing commands for PR/issue workflows.","bodyPreview":"# GHX Skill\n\n`ghx` is an enhanced reliability layer on top of `gh`, used by higher-level skills.\nIt standardizes common GitHub operations and prevents common agent mistakes (especially shell escaping and multi-line payload issues).\n\nIt provides two capabilities:\n- Context collection with a stable artifact manifest\n- Publishing for PR/review/comment workflows\n\n## Environment Variables\n\n- `GITHUB_OUTPUT_DIR`: artifact directory (caller-provided; defaults to a temp dir when unset)\n- `GITHUB_CONTEXT","body":"# GHX Skill\n\n`ghx` is an enhanced reliability layer on top of `gh`, used by higher-level skills.\nIt standardizes common GitHub operations and prevents common agent mistakes (especially shell escaping and multi-line payload issues).\n\nIt provides two capabilities:\n- Context collection with a stable artifact manifest\n- Publishing for PR/review/comment workflows\n\n## Environment Variables\n\n- `GITHUB_OUTPUT_DIR`: artifact directory (caller-provided; defaults to a temp dir when unset)\n- `GITHUB_CONTEXT_DIR`: context directory (default `${GITHUB_OUTPUT_DIR}/github-context`)\n- `GITHUB_TOKEN` / `GH_TOKEN`: token used by `gh`\n- `DRY_RUN`: preview mode for publish commands (`true|false`)\n\n## Commands\n\nUse `scripts/ghx.sh` as the entrypoint.\n\n### Context collection\n\n```bash\nscripts/ghx.sh context collect holon-run/holon#123\nscripts/ghx.sh context collect 123 holon-run/holon\n```\n\n### Publish commands\n\n```bash\nscripts/ghx.sh review publish --pr=holon-run/holon#123 --body-file=review.md --comments-file=review.json\nscripts/ghx.sh pr create --repo=holon-run/holon --title=\"Title\" --body-file=summary.md --head=feature/x --base=main\nscripts/ghx.sh pr update --pr=holon-run/holon#123 --title=\"New title\" --body-file=summary.md\nscripts/ghx.sh pr comment --pr=holon-run/holon#123 --body-file=summary.md\n# stdin body is also supported\nscripts/ghx.sh pr comment --pr=holon-run/holon#123 --body-file=- <<''EOF''\nMultiline body from stdin.\nEOF\n```\n\n### Batch mode\n\n```bash\nscripts/ghx.sh batch run --batch=${GITHUB_OUTPUT_DIR}/publish-batch.json\n```\n\nUse batch mode when one run needs multiple publish actions.\nUse direct commands for single-action publish.\n\n## Contract Boundary\n\n- Public contract for other skills:\n  - Call `ghx.sh` commands.\n  - Read `${GITHUB_CONTEXT_DIR}/manifest.json` for context artifacts.\n  - Read `${GITHUB_OUTPUT_DIR}/publish-results.json` for publish execution results.\n  - Use `publish-batch.json` schema when running `ghx.sh batch run` (defined below and in `references/github-publishing.md`).\n- Integration guidance for third-party skills:\n  - Prefer direct commands for single actions.\n  - Use batch mode only when one run needs multiple publish actions.\n  - Do not depend on undocumented fields or script internals outside this documented schema.\n\n## Context Output Contract\n\n`context collect` writes:\n- `${GITHUB_CONTEXT_DIR}/manifest.json`\n- Context files under `${GITHUB_CONTEXT_DIR}/github/` (for example `pr.json`, `pr.diff`, `comments.json`)\n\n`manifest.json` is the source of truth for collected context:\n\n```json\n{\n  \"schema_version\": \"2.0\",\n  \"provider\": \"ghx\",\n  \"kind\": \"pr|issue\",\n  \"ref\": \"owner/repo#123\",\n  \"success\": true,\n  \"artifacts\": [\n    {\n      \"id\": \"pr_metadata\",\n      \"path\": \"github/pr.json\",\n      \"required_for\": [\"review\"],\n      \"status\": \"present|missing|error\",\n      \"format\": \"json|text\",\n      \"description\": \"What this artifact contains\"\n    }\n  ],\n  \"notes\": []\n}\n```\n\nConsumers must use `artifacts[]` instead of assuming fixed context filenames.\n\n## Publish Output Contract\n\nPublish commands write `${GITHUB_OUTPUT_DIR}/publish-results.json` with per-action status and summary totals.\n\n## Batch Input Contract (Public)\n\n`ghx.sh batch run` consumes `${GITHUB_OUTPUT_DIR}/publish-batch.json` (or any path passed by `--batch`).\n\n```json\n{\n  \"version\": \"1.0\",\n  \"pr_ref\": \"owner/repo#123\",\n  \"actions\": [\n    {\n      \"type\": \"post_comment\",\n      \"description\": \"optional\",\n      \"params\": {\n        \"body\": \"summary.md\"\n      }\n    }\n  ]\n}\n```\n\nSchema summary:\n- Top-level required fields: `pr_ref`, `actions`\n- Top-level optional field: `version` (default `1.0`)\n- Action required field: `type`\n- Action optional fields: `description`, `params`\n- `params` is action-specific payload; legacy inline action fields are also accepted.\n\nSupported `type` values:\n- `create_pr`\n- `update_pr`\n- `post_comment`\n- `reply_review`\n- `post_review`\n\n## Notes\n\n- Prefer `ghx` for multi-step or error-prone GitHub operations.\n- `context collect` also prints a human-readable artifact summary; this is informational only.\n- For long or multi-line text, never inline shell arguments; always write to a file and pass `--body-file`/`--comments-file`.\n- Command selection:\n  - single action: use direct commands (`review publish`, `pr create|update|comment`)\n  - multiple actions in one run: use `batch run`\n\n## Safety Rules (Text Payloads)\n\nTo reduce failure rate from quoting/newline/markdown escaping:\n\n1. Never pass large markdown/JSON payloads inline on command line.\n2. Always pass payloads via file arguments:\n   - `ghx`: `--body-file`, `--comments-file` (`--body-file=-` is allowed to read from stdin)\n   - raw `gh`: `--body-file`\n3. Apply this rule to PR reviews, PR comments/description, issue comments, and issue creation.\n\nGood:\n\n```bash\ncat > /tmp/issue-body.md <<''EOF''\n## Summary\nDetailed markdown with quotes, backticks, and newlines.\nEOF\ngh issue create --repo owner/repo --title \"Bug report\" --body-file /tmp/issue-body.md\n```\n\nBad:\n\n```bash\ngh issue create --repo owner/repo --title \"Bug report\" --body \"## Summary\nDetailed markdown with quotes, backticks, and newlines.\"\n```\n"},"lastSynced":"2026-03-04T13:22:34.150Z","agentAnalysis":{"suitability":{"en":"Essential for GitHub Automation Agents requiring reliable, headless issue-to-PR workflows.","zh":"对于需要可靠、无头 issue-to-PR 工作流的 GitHub Automation Agents 至关重要。","ja":"信頼性の高いヘッドレスな issue-to-PR ワークフローを必要とする GitHub Automation Agents に不可欠です。","ko":"신뢰할 수 있는 헤드리스 issue-to-PR 워크플로우가 필요한 GitHub Automation Agents에 필수적입니다.","es":"Esencial para los agentes de automatización de GitHub que requieren flujos de trabajo de problema a PR confiables y sin interfaz gráfica.","fr":"Essentiel pour les agents d''automatisation GitHub nécessitant des flux de travail de problème à PR fiables et sans interface graphique.","de":"Wesentlich für GitHub-Automatisierungsagenten, die zuverlässige, headless Issue-to-PR-Workflows erfordern.","pt":"Essencial para Agentes de Automação GitHub que exigem fluxos de trabalho confiáveis e headless de issue para PR.","ru":"Необходим для Агентов автоматизации GitHub, требующих надежных, headless рабочих процессов от issue к PR.","ar":"أساسي لوكلاء أتمتة GitHub التي تتطلب سير عمل موثوقًا وبدواجه من المشكلات إلى طلبات السحب (PR)."},"recommendation":{"en":"Provides a hardened reliability layer over standard `gh` CLI operations, preventing common agent failures in shell escaping and multi-line payload handling. Standardizes GitHub context collection with stable artifact manifests and enables robust PR/review/comment publishing workflows without requiring manual supervision.","zh":"为标准 `gh` CLI 操作提供了一个强化的可靠性层，防止了在 shell 转义和多行 payload 处理中常见的 agent 故障。通过稳定的 artifact manifests 标准化 GitHub context 收集，并实现了无需人工监督的、稳健的 PR/review/comment 发布工作流。","ja":"標準的な `gh` CLI 操作の上に強化された信頼性レイヤーを提供し、シェルエスケープや複数行ペイロード処理における一般的な agent 障害を防止します。安定した artifact manifests を使用して GitHub context 収集を標準化し、手動監視を必要としない堅牢な PR/review/comment 公開ワークフローを実現します。","ko":"표준 `gh` CLI 작업 위에 강화된 신뢰성 레이어를 제공하여 셸 이스케이핑 및 멀티라인 페이로드 처리에서 흔히 발생하는 agent 장애를 방지합니다. 안정적인 artifact manifests로 GitHub context 수집을 표준화하고 수동 감독 없이도 강력한 PR/review/comment 게시 워크플로우를 가능하게 합니다.","es":"Proporciona una capa de confiabilidad endurecida sobre las operaciones estándar de `gh` CLI, evitando fallos comunes de los agentes en la escapada de shell y el manejo de payloads multilínea. Estandariza la recopilación de contexto de GitHub con manifestos de artefactos estables y habilita flujos de trabajo de publicación de PR/revisión/comentario robustos sin requerir supervisión manual.","fr":"Fournit une couche de fiabilité durcie sur les opérations standard `gh` CLI, empêchant les défaillances courantes des agents dans l''échappement de shell et la gestion de charges utiles multiligne. Standardise la collecte de contexte GitHub avec des manifestes d''artefacts stables et permet des flux de travail de publication de PR/examen/commentaire robustes sans supervision manuelle.","de":"Bietet eine gehärtete Zuverlässigkeitsschicht über die Standard-`gh`-CLI-Operationen, verhindert häufige Agentenfehler bei der Shell-Escapade und der Verarbeitung von Multiline-Payloads. Standardisiert die GitHub-Kontextsammlung mit stabilen Artefaktmanifesten und ermöglicht robuste PR/Überprüfungs/Kommentar-Veröffentlichungsworkflows ohne manuelle Überwachung.","pt":"Fornece uma camada de confiabilidade reforçada sobre as operações padrão da CLI `gh`, prevenindo falhas comuns de agentes em escape de shell e manipulação de payloads multi-linha. Padroniza a coleta de contexto do GitHub com manifestos de artefatos estáveis e permite fluxos de trabalho robustos de publicação de PR/review/comment sem exigir supervisão manual.","ru":"Обеспечивает усиленный уровень надежности поверх стандартных операций CLI `gh`, предотвращая распространенные сбои агентов при экранировании оболочки и обработке многострочных полезных нагрузок. Стандартизирует сбор контекста GitHub со стабильными манифестами артефактов и обеспечивает надежные рабочие процессы публикации PR/обзоров/комментариев без необходимости ручного контроля.","ar":"يوفر طبقة موثوقية معززة فوق عمليات واجهة سطر الأوامر (CLI) `gh` القياسية، مما يمنع أعطال الوكلاء الشائعة في الهروب من shell ومعالجة حمولات متعددة الأسطر. يقوم بتوحيد جمع سياق GitHub مع بيانات manifests مستقرة للقطات الفنية ويمكّن من سير عمل قوي لنشر طلبات السحب (PR)/المراجعات/التعليقات دون الحاجة إلى إشراف يدوي."},"useCases":{"en":["Automating PR-ready patch generation from issues","Running headless GitHub operations in CI/CD pipelines","Collecting standardized GitHub context artifacts","Publishing code reviews and comments without agent babysitting"],"zh":["从 issue 自动化生成 PR-ready 补丁","在 CI/CD 流水线中运行无头 GitHub 操作","收集标准化的 GitHub context artifacts","无需 agent 持续监控即可发布代码审查和评论"],"ja":["issue から PR-ready パッチを自動生成","CI/CD パイプラインでのヘッドレス GitHub 操作の実行","標準化された GitHub context artifacts の収集","agent の常時監視なしでコードレビューとコメントを公開"],"ko":["issue로부터 PR-ready 패치 자동 생성","CI/CD 파이프라인에서 헤드리스 GitHub 작업 실행","표준화된 GitHub context artifacts 수집","agent의 지속적인 모니터링 없이 코드 리뷰 및 코멘트 게시"],"es":["Generación automática de parches listos para PR a partir de problemas","Ejecución de operaciones de GitHub sin interfaz gráfica en pipelines de CI/CD","Recopilación de artefactos de contexto de GitHub estandarizados","Publicación de revisiones de código y comentarios sin supervisión del agente"],"fr":["Génération automatique de correctifs prêts pour PR à partir de problèmes","Exécution d''opérations GitHub sans interface graphique dans les pipelines CI/CD","Collecte d''artefacts de contexte GitHub standardisés","Publication d''examen de code et de commentaires sans surveillance de l''agent"],"de":["Automatisierte Generierung von PR-fertigen Patches aus Problemen","Ausführung von GitHub-Operationen ohne Benutzeroberfläche in CI/CD-Pipelines","Sammlung von standardisierten GitHub-Kontextartefakten","Veröffentlichung von Code-Reviews und Kommentaren ohne Agentenüberwachung"],"pt":["Automatizando a geração de patches prontos para PR a partir de issues","Executando operações GitHub headless em pipelines de CI/CD","Coletando artefatos de contexto GitHub padronizados","Publicando revisões de código e comentários sem necessidade de monitoramento do agente"],"ru":["Автоматизация создания готовых к PR исправлений из issues","Выполнение headless операций GitHub в конвейерах CI/CD","Сбор стандартизированных артефактов контекста GitHub","Публикация рецензий кода и комментариев без необходимости присмотра за агентом"],"ar":["أتمتة إنشاء تصحيحات جاهزة لطلب السحب (PR) من المشكلات","تشغيل عمليات GitHub بدون واجهة (headless) في خطوط أنابيب CI/CD","جمع قطع فنية موحدة لسياق GitHub","نشر مراجعات التعليمات البرمجية والتعليقات دون الحاجة إلى مراقبة الوكيل"]},"limitations":{"en":["Requires GITHUB_OUTPUT_DIR environment variable for artifacts","Dependent on underlying gh CLI installation","Primarily designed for headless/CI environments"],"zh":["需要 GITHUB_OUTPUT_DIR 环境变量来存放 artifacts","依赖于底层 gh CLI 的安装","主要设计用于无头/CI 环境"],"ja":["artifacts には GITHUB_OUTPUT_DIR 環境変数が必要","基盤となる gh CLI のインストールに依存","主にヘッドレス/CI 環境向けに設計"],"ko":["artifacts를 위해 GITHUB_OUTPUT_DIR 환경 변수 필요","기반이 되는 gh CLI 설치에 의존","주로 헤드리스/CI 환경용으로 설계됨"],"es":["Requiere la variable de entorno GITHUB_OUTPUT_DIR para los artefactos","Depende de la instalación subyacente de `gh` CLI","Diseñado principalmente para entornos sin interfaz gráfica/CI"],"fr":["Nécessite la variable d''environnement GITHUB_OUTPUT_DIR pour les artefacts","Dépend de l''installation sous-jacente de `gh` CLI","Conçu principalement pour les environnements sans interface graphique/CI"],"de":["Benötigt die Umgebungsvariable GITHUB_OUTPUT_DIR für Artefakte","Hängt von der unterliegenden `gh`-CLI-Installation ab","Hauptsächlich für headless/CI-Umgebungen konzipiert"],"pt":["Requer a variável de ambiente GITHUB_OUTPUT_DIR para artefatos","Dependente da instalação subjacente da CLI gh","Projetado principalmente para ambientes headless/CI"],"ru":["Требует переменную окружения GITHUB_OUTPUT_DIR для артефактов","Зависит от базовой установки CLI gh","В первую очередь предназначен для headless/CI сред"],"ar":["يتطلب متغير البيئة GITHUB_OUTPUT_DIR للقطع الفنية","يعتمد على التثبيت الأساسي لواجهة سطر الأوامر (CLI) gh","مصمم أساسًا للبيئات بدون واجهة (headless)/CI"]},"version":3},"contentHash":"bb1a47edffee032ba03ed5d500e15eb527261f0c7125dc21a2b2191845f0826e","qualityScore":45}');
