INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ncrmro/deepwork-permanent-portfolio/deepwork_jobs', 'deepwork_jobs', 'ncrmro', 'deepwork-permanent-portfolio', 'community', 'deepwork_jobs ncrmro deepwork-permanent-portfolio community deepwork_jobs是一种基于Harry Browne的永久投资组合策略的AI智能工具，用于自动化每日投资组合分析 deepwork_jobsは、ハリー・ブラウンの永久ポートフォリオ戦略に基づくAIエージェントで、毎日のポートフォリオ分析を自動化します deepwork_jobs는 해리 브라운의 영구 포트폴리오 전략을 기반으로 하는 AI 에이전트로, 일일 포트폴리오 분석을 자동화합니다 Análisis de cartera automático diario implementando la estrategia de cartera permanente de Harry Browne Analyse de portefeuille automatisée quotidienne mettant en œuvre la stratégie de portefeuille permanent de Harry Browne Automatisierte tägliche Portfolioanalyse unter Verwendung der Permanent-Portfolio-Strategie von Harry Browne O deepwork_jobs é uma ferramenta de IA que implementa a estratégia de Carteira Permanente de Harry Browne para análise diária de portfólio ИИ Агент deepwork_jobs реализует стратегию Постоянного Портфеля Харри Брауна для ежедневного анализа портфеля أداة الذكاء الاصطناعي deepwork_jobs تنفذ استراتيجية المحفظة الدائمة لهاري براون لتحليل المحفظة اليومي Automated daily portfolio analysis implementing Harry Browne''s Permanent Portfolio strategy 如何使用deepwork_jobs 什么是永久投资组合策略 deepwork_jobs替代品 deepwork_jobs vs 其他AI工具 安装deepwork_jobs 设置deepwork_jobs指南 AI智能工具 投资组合分析 永久投资组合 Automated daily portfolio analysis implementing Harry Browne''s Permanent Portfolio strategy');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alexanderop/second-brain-nuxt/mermaid-diagrams', 'community', 'alexanderop', 'second-brain-nuxt', 'alexanderop/second-brain-nuxt', 'mermaid-diagrams', 0, 0, 45, '2026-03-04T13:07:01.695Z', '2026-03-04T13:36:14.774Z', '16429fea364ce18ddf284d366f073ca2379b9af49f75471cb46e9a753e709d6a', '{"id":"alexanderop/second-brain-nuxt/mermaid-diagrams","name":"mermaid-diagrams","description":{"zh":"mermaid-diagrams是一种个人知识库，使用Zettelkasten风格的wiki链接来捕获和连接内容","ja":"mermaid-diagramsは、ゼッテルカステンスタイルのWikiリンクを使用してコンテンツをキャプチャして接続する個人用ナレッジベースです","ko":"mermaid-diagrams는 제텔카ステン 스타일의 위키 링크를 사용하여 콘텐츠를 캡처하고 연결하는 개인 지식베이스입니다","es":"Mermaid-diagrams es una herramienta de inteligencia artificial para crear una base de conocimiento personal con enlaces de wiki estilo Zettelkasten","fr":"Mermaid-diagrams est un outil d''intelligence artificielle pour créer une base de connaissances personnelles avec des liens de wiki de style Zettelkasten","de":"Mermaid-Diagramme ist ein KI-Tool für die Erstellung einer persönlichen Wissensbasis mit Wiki-Links im Zettelkasten-Stil","pt":"mermaid-diagrams é uma ferramenta de AI para criar uma base de conhecimento pessoal com links de wiki no estilo Zettelkasten","ru":"mermaid-diagrams - это инструмент ИИ для создания личной базы знаний с использованием Zettelkasten-style wiki-links","ar":"مرmaid-diagrams هي أداة ذكاء اصطناعي لإنشاء قاعدة معرفة شخصية مع روابط ويكي بالنمط الزتلكاستن","en":"Personal knowledge base for capturing and connecting content using Zettelkasten-style wiki-links"},"seo":{"title":{"zh":"AI智能工具 mermaid-diagrams：基于Zettelkasten的个人知识库","ja":"AIエージェント mermaid-diagrams：ゼッテルカステンスタイルのWikiリンクを使用した個人用ナレッ...","ko":"AI 에이전트 mermaid-diagrams: 제텔카ステン 스타일의 위키 링크를 사용한 개인 지식베이스","es":"Herramientas de inteligencia artificial para mermaid-diag...","fr":"Outils d''intelligence artificielle pour les diagrammes me...","de":"KI-Tools für Mermaid-Diagramme","pt":"Ferramentas de AI: mermaid-diagrams para Desenvolvedores","ru":"ИИ Агенты: mermaid-diagrams для Разработчиков","ar":"أدوات الذكاء الاصطناعي: مرmaid-diagrams для المطورين","en":"mermaid-diagrams"},"description":{"zh":"mermaid-diagrams是一种个人知识库，使用Zettelkasten风格的wiki链接来捕获和连接内容","ja":"mermaid-diagramsは、ゼッテルカステンスタイルのWikiリンクを使用してコンテンツをキャプチャして接続する個人用ナレッジベースです","ko":"mermaid-diagrams는 제텔카ステン 스타일의 위키 링크를 사용하여 콘텐츠를 캡처하고 연결하는 개인 지식베이스입니다","es":"Mermaid-diagrams es una herramienta de inteligencia artificial para crear una base de conocimiento personal con enlaces de wiki estilo Zettelkasten","fr":"Mermaid-diagrams est un outil d''intelligence artificielle pour créer une base de connaissances personnelles avec des liens de wiki de style Zettelkasten","de":"Mermaid-Diagramme ist ein KI-Tool für die Erstellung einer persönlichen Wissensbasis mit Wiki-Links im Zettelkasten-Stil","pt":"mermaid-diagrams é uma ferramenta de AI para criar uma base de conhecimento pessoal com links de wiki no estilo Zettelkasten","ru":"mermaid-diagrams - это инструмент ИИ для создания личной базы знаний с использованием Zettelkasten-style wiki-links","ar":"مرmaid-diagrams هي أداة ذكاء اصطناعي لإنشاء قاعدة معرفة شخصية مع روابط ويكي بالنمط الزتلكاستن","en":"Personal knowledge base for capturing and connecting content using Zettelkasten-style wiki-links"},"definition":{"en":"Personal knowledge base for capturing and connecting content using Zettelkasten-style wiki-links"},"features":{"zh":["使用Zettelkasten风格的wiki链接来连接内容","支持个人知识库的构建","提供简单易用的界面","支持多种内容格式","可以与其他AI工具集成"],"ja":["ゼッテルカステンスタイルのWikiリンクを使用してコンテンツを接続","個人用ナレッジベースの構築をサポート","シンプルで使いやすいインターフェースを提供","多種多様なコンテンツ形式をサポート","他のAIエージェントとの統合をサポート"],"ko":["제텔카ステン 스타일의 위키 링크를 사용하여 콘텐츠를 연결","개인 지식베이스의 구축을 지원","단순하고 사용하기 쉬운 인터페이스를 제공","다양한 콘텐츠 형식을 지원","他の AI 에이전트와의 통합을 지원"],"es":["Creación de una base de conocimiento personal","Enlaces de wiki estilo Zettelkasten","Conexión y captura de contenido","Herramienta de inteligencia artificial para desarrolladores","Mejora de la productividad y la organización"],"fr":["Création d''une base de connaissances personnelles","Liens de wiki de style Zettelkasten","Connexion et capture de contenu","Outil d''intelligence artificielle pour les développeurs","Amélioration de la productivité et de l''organisation"],"de":["Erstellung einer persönlichen Wissensbasis","Wiki-Links im Zettelkasten-Stil","Verbindung und Erfassung von Inhalten","KI-Tool für Entwickler","Verbesserung der Produktivität und Organisation"],"pt":["Criação de base de conhecimento pessoal","Uso de links de wiki no estilo Zettelkasten","Conexão de conteúdo de forma eficiente","Ferramenta de AI para desenvolvedores","Integração com tecnologias de desenvolvimento"],"ru":["Создание личной базы знаний","Использование Zettelkasten-style wiki-links","Связь контента эффективно","Инструмент ИИ для разработчиков","Интеграция с технологиями разработки"],"ar":["إنشاء قاعدة معرفة شخصية","استخدام روابط ويكي بالنمط الزتلكاستن","ربط المحتوى بفعالية","أداة ذكاء اصطناعي للمطورين","التكامل مع تقنيات التطوير"]},"keywords":{"zh":["如何使用mermaid-diagrams","什么是Zettelkasten","mermaid-diagrams替代品","mermaid-diagrams安装","mermaid-diagrams设置指南","个人知识库构建","AI智能工具","wiki链接","内容管理"],"ja":["mermaid-diagramsの使い方","ゼッテルカステンとは","mermaid-diagramsの代替","mermaid-diagramsのインストール","mermaid-diagramsの設定ガイド","個人用ナレッジベースの構築","AIエージェント","Wikiリンク","コンテンツ管理"],"ko":["mermaid-diagrams 사용법","제텔카ステ是什么","mermaid-diagrams 대체품","mermaid-diagrams 설치","mermaid-diagrams 설정 가이드","개인 지식베이스 구축","AI 에이전트","위키 링크","콘텐츠 관리"],"es":["herramientas de inteligencia artificial","mermaid-diagrams","base de conocimiento personal","enlaces de wiki","Zettelkasten","desarrolladores","productividad","organización","cómo usar mermaid-diagrams","alternativas a mermaid-diagrams"],"fr":["outils d''intelligence artificielle","mermaid-diagrams","base de connaissances personnelles","liens de wiki","Zettelkasten","développeurs","productivité","organisation","comment utiliser mermaid-diagrams","alternatives à mermaid-diagrams"],"de":["KI-Tools","Mermaid-Diagramme","persönliche Wissensbasis","Wiki-Links","Zettelkasten","Entwickler","Produktivität","Organisation","wie man Mermaid-Diagramme verwendet","Alternativen zu Mermaid-Diagrammen"],"pt":["como usar mermaid-diagrams","o que é mermaid-diagrams","mermaid-diagrams alternativa","mermaid-diagrams vs graphviz","instalar mermaid-diagrams","guia de configuração do mermaid-diagrams"],"ru":["как использовать mermaid-diagrams","что такое mermaid-diagrams","мерmaid-diagrams альтернатива","мерmaid-diagrams vs graphviz","установить mermaid-diagrams","руководство по настройке mermaid-diagrams"],"ar":["كيفية استخدام مرmaid-diagrams","ما هي مرmaid-diagrams","مرmaid-diagrams بديل","مرmaid-diagrams مقابل graphviz","تثبيت مرmaid-diagrams","دليل إعداد مرmaid-diagrams"]}},"owner":"alexanderop","repo":"second-brain-nuxt","repoPath":"alexanderop/second-brain-nuxt","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.695Z","topics":[],"category":"community","skillMd":{"name":"mermaid-diagrams","description":"Generate Mermaid diagrams (flowcharts, sequence, class, state, ER, C4, mindmaps, gitgraph). Use when asked to create diagrams, visualize processes, document architecture, or explain systems visually. Triggers include diagram, flowchart, sequence diagram, class diagram, state diagram, ER diagram, C4, mindmap, gitgraph, visualize, draw.","bodyPreview":"# Mermaid Diagrams\n\nGenerate diagrams using Mermaid syntax. All diagrams render in markdown code blocks with `mermaid` language identifier.\n\n## Decision Guide\n\n| Use Case | Diagram Type |\n|----------|--------------|\n| Process flow, decision trees | Flowchart |\n| API calls, system interactions over time | Sequence |\n| OOP structure, domain models | Class |\n| State machines, workflows | State |\n| Database schemas, data relationships | ER |\n| Software architecture (C4 model) | C4 |\n| Brainstorming,","body":"# Mermaid Diagrams\n\nGenerate diagrams using Mermaid syntax. All diagrams render in markdown code blocks with `mermaid` language identifier.\n\n## Decision Guide\n\n| Use Case | Diagram Type |\n|----------|--------------|\n| Process flow, decision trees | Flowchart |\n| API calls, system interactions over time | Sequence |\n| OOP structure, domain models | Class |\n| State machines, workflows | State |\n| Database schemas, data relationships | ER |\n| Software architecture (C4 model) | C4 |\n| Brainstorming, hierarchical organization | Mindmap |\n| Git branching, commit history | GitGraph |\n\n---\n\n## Quick Reference\n\n### Flowchart\n```mermaid\nflowchart TD\n    A[Start] --> B{Decision}\n    B -->|Yes| C[Action 1]\n    B -->|No| D[Action 2]\n    C --> E[End]\n    D --> E\n```\n\n### Sequence\n```mermaid\nsequenceDiagram\n    participant U as User\n    participant S as Server\n    U->>S: Request\n    S-->>U: Response\n```\n\n### Class\n```mermaid\nclassDiagram\n    Animal <|-- Dog\n    Animal : +String name\n    Animal : +makeSound()\n    Dog : +fetch()\n```\n\n### State\n```mermaid\nstateDiagram-v2\n    [*] --> Idle\n    Idle --> Processing: start\n    Processing --> Done: complete\n    Done --> [*]\n```\n\n### ER\n```mermaid\nerDiagram\n    CUSTOMER ||--o{ ORDER : places\n    ORDER ||--|{ LINE-ITEM : contains\n```\n\n### C4 Context\n```mermaid\nC4Context\n    Person(user, \"User\", \"End user\")\n    System(app, \"Application\", \"Main system\")\n    Rel(user, app, \"Uses\")\n```\n\n### Mindmap\n```mermaid\nmindmap\n  root((Topic))\n    Branch A\n      Leaf 1\n      Leaf 2\n    Branch B\n```\n\n### GitGraph\n```mermaid\ngitgraph\n    commit\n    branch feature\n    commit\n    checkout main\n    merge feature\n```\n\n---\n\n## Flowchart Reference\n\n**Directions:** `TD` (top-down), `LR` (left-right), `BT` (bottom-top), `RL` (right-left)\n\n### Node Shapes\n\n| Shape | Syntax | Example |\n|-------|--------|---------|\n| Rectangle | `[text]` | `A[Process]` |\n| Rounded | `(text)` | `A(Start)` |\n| Stadium | `([text])` | `A([Terminal])` |\n| Diamond | `{text}` | `A{Decision}` |\n| Circle | `((text))` | `A((Event))` |\n| Hexagon | `{{text}}` | `A{{Prepare}}` |\n| Cylinder | `[(text)]` | `A[(Database)]` |\n| Subroutine | `[[text]]` | `A[[Subprocess]]` |\n| Parallelogram | `[/text/]` | `A[/Input/]` |\n| Trapezoid | `[\\text\\]` | `A[\\Manual Op\\]` |\n\n### Link Types\n\n| Type | Syntax | Description |\n|------|--------|-------------|\n| Arrow | `-->` | Solid with arrowhead |\n| Open | `---` | Solid, no arrowhead |\n| Dotted arrow | `-.->` | Dotted with arrowhead |\n| Thick arrow | `==>` | Thick with arrowhead |\n| With text | `--\\|text\\|>` | Label on link |\n| Multi-length | `---->` | Longer link (more ranks) |\n\n### Subgraphs\n```mermaid\nflowchart TD\n    subgraph Backend[\"Backend Services\"]\n        direction LR\n        API --> DB[(Database)]\n    end\n    Client --> API\n```\n\n### Styling\n```mermaid\nflowchart TD\n    A[Node]:::highlight\n    classDef highlight fill:#ff9,stroke:#333\n    style A stroke-width:2px\n```\n\n---\n\n## Sequence Diagram Reference\n\n### Arrow Types\n\n| Syntax | Style |\n|--------|-------|\n| `->>` | Solid with arrowhead |\n| `-->>` | Dotted with arrowhead |\n| `-x` | Solid with cross |\n| `-)` | Async (open arrow) |\n| `<<->>` | Bidirectional |\n\n### Participants\n```mermaid\nsequenceDiagram\n    actor User\n    participant API as API Server\n    participant DB as Database\n```\n\n### Activations\n```mermaid\nsequenceDiagram\n    User->>+API: Request\n    API->>+DB: Query\n    DB-->>-API: Result\n    API-->>-User: Response\n```\n\n### Control Flow\n```mermaid\nsequenceDiagram\n    alt Success\n        A->>B: OK\n    else Failure\n        A->>B: Error\n    end\n\n    loop Every 5s\n        A->>B: Ping\n    end\n\n    opt Optional\n        A->>B: Maybe\n    end\n```\n\n### Notes\n```mermaid\nsequenceDiagram\n    Note right of A: Single note\n    Note over A,B: Spanning note\n```\n\n### Grouping with Boxes\n```mermaid\nsequenceDiagram\n    box Blue Frontend\n        participant U as User\n        participant W as Web\n    end\n    box Green Backend\n        participant A as API\n    end\n```\n\n---\n\n## Class Diagram Reference\n\n### Visibility Modifiers\n\n| Symbol | Meaning |\n|--------|---------|\n| `+` | Public |\n| `-` | Private |\n| `#` | Protected |\n| `~` | Package |\n\n### Relationships\n\n| Type | Syntax | Meaning |\n|------|--------|---------|\n| Inheritance | `<\\|--` | Extends |\n| Composition | `*--` | Strong owns |\n| Aggregation | `o--` | Weak owns |\n| Association | `-->` | Uses |\n| Dependency | `..>` | Depends on |\n| Realization | `..\\|>` | Implements |\n\n### Full Example\n```mermaid\nclassDiagram\n    class Animal {\n        <<abstract>>\n        +String name\n        +int age\n        +makeSound()* void\n    }\n    class Dog {\n        +String breed\n        +fetch() void\n    }\n    Animal <|-- Dog\n    Dog \"1\" --> \"*\" Toy : plays with\n```\n\n### Generics\n```mermaid\nclassDiagram\n    class List~T~ {\n        +add(T item)\n        +T get(int index)\n    }\n```\n\n### Annotations\n- `<<interface>>` - Interface\n- `<<abstract>>` - Abstract class\n- `<<service>>` - Service class\n- `<<enumeration>>` - Enum\n\n---\n\n## State Diagram Reference\n\n### Basic Syntax\n```mermaid\nstateDiagram-v2\n    [*] --> State1\n    State1 --> State2: trigger\n    State2 --> [*]\n```\n\n### Composite States\n```mermaid\nstateDiagram-v2\n    state Active {\n        [*] --> Running\n        Running --> Paused: pause\n        Paused --> Running: resume\n    }\n    [*] --> Active\n    Active --> [*]: stop\n```\n\n### Fork and Join\n```mermaid\nstateDiagram-v2\n    state fork <<fork>>\n    state join <<join>>\n    [*] --> fork\n    fork --> Task1\n    fork --> Task2\n    Task1 --> join\n    Task2 --> join\n    join --> [*]\n```\n\n### Choice\n```mermaid\nstateDiagram-v2\n    state check <<choice>>\n    [*] --> check\n    check --> Success: valid\n    check --> Error: invalid\n```\n\n### Notes\n```mermaid\nstateDiagram-v2\n    State1\n    note right of State1\n        Description here\n    end note\n```\n\n---\n\n## ER Diagram Reference\n\n### Cardinality\n\n| Left | Right | Meaning |\n|------|-------|---------|\n| `\\|o` | `o\\|` | Zero or one |\n| `\\|\\|` | `\\|\\|` | Exactly one |\n| `}o` | `o{` | Zero or more |\n| `}\\|` | `\\|{` | One or more |\n\n### Relationship Types\n- `--` Identifying (solid line, child depends on parent)\n- `..` Non-identifying (dashed line, independent entities)\n\n### Attributes\n```mermaid\nerDiagram\n    USER {\n        int id PK\n        string email UK\n        string name\n        datetime created_at\n    }\n    POST {\n        int id PK\n        int user_id FK\n        string title\n        text content\n    }\n    USER ||--o{ POST : writes\n```\n\n---\n\n## C4 Diagram Reference\n\nC4 provides 4 levels of abstraction for architecture documentation.\n\n### Diagram Types\n- `C4Context` - System context (level 1)\n- `C4Container` - Container diagram (level 2)\n- `C4Component` - Component diagram (level 3)\n- `C4Dynamic` - Interaction sequences\n- `C4Deployment` - Infrastructure layout\n\n### Elements\n\n| Element | Syntax | Use |\n|---------|--------|-----|\n| Person | `Person(alias, label, desc)` | Users |\n| Person_Ext | `Person_Ext(...)` | External users |\n| System | `System(alias, label, desc)` | Software systems |\n| System_Ext | `System_Ext(...)` | External systems |\n| SystemDb | `SystemDb(...)` | Database systems |\n| Container | `Container(alias, label, tech, desc)` | Applications |\n| ContainerDb | `ContainerDb(...)` | Container databases |\n| Component | `Component(alias, label, tech, desc)` | Internal parts |\n\n### Boundaries\n```mermaid\nC4Container\n    System_Boundary(app, \"Application\") {\n        Container(web, \"Web App\", \"React\")\n        Container(api, \"API\", \"Node.js\")\n        ContainerDb(db, \"Database\", \"PostgreSQL\")\n    }\n    Rel(web, api, \"HTTP/JSON\")\n    Rel(api, db, \"SQL\")\n```\n\n### Relationships\n- `Rel(from, to, label)` - Standard relationship\n- `Rel_U/D/L/R(...)` - Directional hints\n- `BiRel(from, to, label)` - Bidirectional\n\n### Complete C4 Context Example\n```mermaid\nC4Context\n    Person(user, \"Customer\", \"Uses the system\")\n    System(app, \"E-Commerce\", \"Online store\")\n    System_Ext(payment, \"Payment Gateway\", \"Processes payments\")\n    System_Ext(shipping, \"Shipping API\", \"Handles delivery\")\n\n    Rel(user, app, \"Browses, orders\")\n    Rel(app, payment, \"Processes payments\")\n    Rel(app, shipping, \"Ships orders\")\n```\n\n---\n\n## Mindmap Reference\n\nUses indentation for hierarchy. Root node required.\n\n### Node Shapes\n```mermaid\nmindmap\n    root((Central Topic))\n        [Square]\n        (Rounded)\n        ))Cloud((\n        {{Hexagon}}\n```\n\n### With Icons\n```mermaid\nmindmap\n    root((Project))\n        Tasks ::icon(fa fa-tasks)\n        Team ::icon(fa fa-users)\n```\n\n### Styling\n```mermaid\nmindmap\n    root\n        Important:::urgent\n        Normal\n```\n\n---\n\n## GitGraph Reference\n\n### Basic Operations\n```mermaid\ngitgraph\n    commit id: \"initial\"\n    commit id: \"feature\"\n    branch develop\n    commit\n    checkout main\n    merge develop tag: \"v1.0\"\n```\n\n### Commit Types\n- `type: NORMAL` - Default\n- `type: HIGHLIGHT` - Emphasized\n- `type: REVERSE` - Reverted\n\n### Full Example\n```mermaid\ngitgraph\n    commit id: \"init\"\n    branch feature\n    commit id: \"add-login\"\n    commit id: \"add-logout\" type: HIGHLIGHT\n    checkout main\n    commit id: \"hotfix\" type: REVERSE\n    merge feature tag: \"v1.0\"\n```\n\n---\n\n## Best Practices\n\n### DO\n- Keep diagrams focused (one concept per diagram)\n- Use clear, descriptive labels\n- Add direction hints (`TD`, `LR`) explicitly\n- Use subgraphs/boundaries for grouping\n- Include legends for complex diagrams\n\n### DON''T\n- Overcrowd with too many nodes (>15-20)\n- Use cryptic single-letter IDs without labels\n- Mix multiple concerns in one diagram\n- Rely on auto-layout for complex diagrams\n\n### Layout Tips\n- **Flowchart**: `LR` for processes, `TD` for hierarchies\n- **Sequence**: Order participants by interaction frequency\n- **Class**: Group related classes with namespaces\n- **C4**: Start with Context, drill down to Container/Component\n- **ER**: Place central entities in the middle\n\n### Common Fixes\n| Problem | Solution |\n|---------|----------|\n| Nodes overlap | Reduce node count, use subgraphs |\n| Links cross confusingly | Reorder nodes, change direction |\n| Text truncated | Use aliases: `A[Long Name] as short` |\n| Diagram too wide | Switch `LR` to `TD` |\n"},"lastSynced":"2026-03-04T13:36:14.774Z","agentAnalysis":{"suitability":{"en":"Perfect for Documentation Agents needing advanced diagramming capabilities with Mermaid syntax","zh":"非常适合需要高级图表功能的文档代理，支持 Mermaid 语法","ja":"Mermaid 構文を使用した高度な図表作成機能を必要とするドキュメント エージェントに最適","ko":"Mermaid 구문으로 고급 도표 기능이 필요한 문서 에이전트에게 적합","es":"Perfecto para Agentes de Documentación que necesitan capacidades de diagramación avanzadas con sintaxis Mermaid","fr":"Parfait pour les Agents de documentation nécessitant des capacités de diagramme avancées avec la syntaxe Mermaid","de":"Perfekt für Dokumentationsagenten, die erweiterte Diagrammfunktionen mit Mermaid-Syntax benötigen","pt":"Perfeito para Agentes de Documentação que precisam de recursos avançados de diagramação com sintaxe Mermaid","ru":"Идеально подходит для агентов документации, которым требуются расширенные возможности диаграммирования с синтаксисом Mermaid","ar":"مثالي لعميل الوثائق الذين يحتاجون إلى功能 متقدمة للرسم البياني مع بناء الجملة Mermaid"},"recommendation":{"en":"Empowers agents to generate flowcharts, sequence diagrams, and class diagrams using Markdown code blocks with the `mermaid` language identifier, supporting various diagram types such as ER, C4, and state diagrams","zh":"使代理能够使用 Markdown 代码块和 `mermaid` 语言标识符生成流程图、序列图和类图，支持各种图表类型，例如 ER、C4 和状态图","ja":"`mermaid` 言語識別子を使用した Markdown コード ブロックで、フローチャート、シーケンス ダイアグラム、クラス ダイアグラムを生成できるようにエージェントをEmpowerする。サポートされているダイアグラムの種類は、ER、C4、状態ダイアグラムなど","ko":"에이전트가 Markdown 코드 블록과 `mermaid` 언어 식별자를 사용하여 흐름도, 시퀀스 다이어그램, 클래스 다이어그램을 생성할 수 있도록 하며, ER, C4, 상태 다이어그램 등을 포함한 다양한 다이어그램 유형을 지원","es":"Habilita a los agentes a generar diagramas de flujo, diagramas de secuencia y diagramas de clase utilizando bloques de código Markdown con el identificador de lenguaje `mermaid`, que admite varios tipos de diagramas como ER, C4 y diagramas de estado","fr":"Permet aux agents de générer des diagrammes de flux, des diagrammes de séquence et des diagrammes de classe en utilisant des blocs de code Markdown avec l''identifiant de langage `mermaid`, prenant en charge différents types de diagrammes tels que ER, C4 et diagrammes d''état","de":"Ermöglicht es Agenten, Flussdiagramme, Sequenzdiagramme und Klassendiagramme zu erstellen, indem sie Markdown-Codeblöcke mit dem Sprachidentifikator `mermaid` verwenden, der verschiedene Diagrammtypen wie ER, C4 und Zustandsdiagramme unterstützt","pt":"Habilita os agentes a gerar fluxogramas, diagramas de sequência e diagramas de classe usando blocos de código Markdown com o identificador de linguagem `mermaid`, suportando vários tipos de diagramas, como ER, C4 e diagramas de estado","ru":"Наделяет агентов возможностью генерировать блок-схемы, диаграммы последовательности и диаграммы классов, используя блоки кода Markdown с идентификатором языка `mermaid`, поддерживая различные типы диаграмм, такие как ER, C4 и диаграммы состояний","ar":"يمنح الوكلاء القدرة على توليد مخططات انسيابية ورسوم متتالية ورسوم فئات باستخدام كتلة من رمز التحرير مع معرّف لغة `mermaid` ، ودعم أنواع مختلفة من المخططات مثل ER و C4 ومخططات الحالة"},"useCases":{"en":["Generating process flow diagrams for decision guides","Creating sequence diagrams for API call visualizations","Designing class diagrams for OOP structure representations"],"zh":["为决策指南生成流程图","创建序列图以可视化 API 调用","设计类图以表示 OOP 结构"],"ja":["意思決定ガイド用のプロセス フローの生成","API コールの可視化用のシーケンス ダイアグラムの作成","OOP 構造の表現用のクラス ダイアグラムの設計"],"ko":["의사 결정 가이드를 위한 프로세스 흐름도 생성","API 호출 시각화를 위한 시퀀스 다이어그램 생성","OOP 구조 표현을 위한 클래스 다이어그램 설계"],"es":["Generar diagramas de flujo de procesos para guías de decisión","Crear diagramas de secuencia para visualizaciones de llamadas a la API","Diseñar diagramas de clase para representaciones de estructuras de OOP"],"fr":["Générer des diagrammes de flux de processus pour les guides de décision","Créer des diagrammes de séquence pour les visualisations d''appels d''API","Concevoir des diagrammes de classe pour les représentations de structures OOP"],"de":["Erstellen von Prozessflussdiagrammen für Entscheidungsleitfäden","Erstellen von Sequenzdiagrammen für API-Aufrufvisualisierungen","Entwerfen von Klassendiagrammen für OOP-Struktur-Darstellungen"],"pt":["Gerar diagramas de fluxo de processo para guias de decisão","Criar diagramas de sequência para visualizações de chamadas de API","Projetar diagramas de classe para representações de estrutura de OOP"],"ru":["Генерировать диаграммы потока процесса для руководств по принятию решений","Создавать диаграммы последовательности для визуализации вызовов API","Проектировать диаграммы классов для представления структуры OOP"],"ar":["توليد مخططات انسيابية للمعالجة لمرشديات القرار","إنشاء رسوم متتالية لترميزات API","تصميم رسوم الفئات لتجسيد هيكل لغة البرمجة الكائنية"]},"limitations":{"en":["Requires Mermaid syntax knowledge","Limited to supported diagram types (Flowchart, Sequence, Class, State, ER, C4)"],"zh":["需要 Mermaid 语法知识","仅限支持的图表类型（流程图、序列图、类图、状态图、ER、C4）"],"ja":["Mermaid 構文の知識が必要","サポートされているダイアグラムの種類（フローチャート、シーケンス ダイアグラム、クラス ダイアグラム、状態ダイアグラム、ER、C4）に限定"],"ko":["Mermaid 구문의 지식이 필요","지원되는 다이어그램 유형(흐름도, 시퀀스 다이어그램, 클래스 다이어그램, 상태 다이어그램, ER, C4)으로 제한"],"es":["Requiere conocimiento de la sintaxis Mermaid","Limitado a los tipos de diagramas admitidos (Diagrama de flujo, Secuencia, Clase, Estado, ER, C4)"],"fr":[