INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ruan-cat/monorepo/openspec-continue-change', 'openspec-continue-change', 'ruan-cat', 'monorepo', 'community', 'openspec-continue-change ruan-cat monorepo community openspec-continue-change是一个npm @ruan-cat/* 依赖包，用于存储和维护阮喵喵自用的包 openspec-continue-changeはnpm @ruan-cat/* 依存パッケージであり、阮喵喵の自作パッケージを保管および管理するために使用 openspec-continue-change는 npm @ruan-cat/* 의존성 패키지로,阮喵喵의 自作 패키지를 저장하고 관리하는 데 사용 openspec-continue-change es un paquete de npm que almacena y mantiene dependencias de @ruan-cat. Es una herramienta de agente de inteligencia artificial para desarrolladores openspec-continue-change est un paquet npm qui stocke et maintient les dépendances de @ruan-cat. C''est un outil d''agent d''intelligence artificielle pour les développeurs openspec-continue-change ist ein npm-Paket, das Abhängigkeiten von @ruan-cat speichert und verwaltet. Es ist ein KI-Agent-Tool für Entwickler O openspec-continue-change é um repositório de pacotes npm para desenvolvedores, incluindo dependências para projetos de Node.js. ИИ Агенты: openspec-continue-change - это репозиторий пакетов npm для разработчиков, включающий зависимости для проектов Node.js. openspec-continue-change هو مستودع للحزم npm لمنشئي التطبيقات، يشمل الإعتماديات لمشاريع Node.js. npm @ruan-cat/* 依赖包所在的单仓。存储并维护阮喵喵自用的包。 openspec-continue-change npm @ruan-cat/* 阮喵喵自用包 Node.js 如何使用openspec-continue-change openspec-continue-change安装 openspec-continue-change设置指南 npm @ruan-cat/* 依赖包所在的单仓。存储并维护阮喵喵自用的包。');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kbaseincubator/BERIL-research-observatory/berdl_start', 'community', 'kbaseincubator', 'BERIL-research-observatory', 'kbaseincubator/BERIL-research-observatory', 'berdl_start', 0, 0, 45, '2026-03-04T13:07:01.695Z', '2026-03-04T13:36:20.125Z', '62a467621d9b12bec8402fb7b243cde86a7cf3c58d8e9a3a461b3e5492683137', '{"id":"kbaseincubator/BERIL-research-observatory/berdl_start","name":"berdl_start","description":{"zh":"BERIL 研究观测站 AIエージェント是一个使用 KBase Data Lakehouse 探索微生物生态的工具","ja":"BERIL 研究観測所 AIエージェントは、KBase Data Lakehouse を使用して微生物生態学を探索するためのツールです","ko":"BERIL 연구 관측소 AI 에이전트는 KBase Data Lakehouse를 사용하여 미생물 생태학을 탐구하는 도구입니다","es":"El Observatorio de Investigación BERIL utiliza berdl_start para explorar la ecología microbiana con el Data Lakehouse de KBase","fr":"L''Observatoire de Recherche BERIL utilise berdl_start pour explorer l''écologie microbienne avec le Data Lakehouse de KBase","de":"Das BERIL-Forschungsobservatorium verwendet berdl_start, um die mikrobielle Ökologie mit dem KBase-Data-Lakehouse zu erforschen","pt":"A ferramenta berdl_start é uma solução inovadora para explorar a ecologia microbiana com o KBase Data Lakehouse","ru":"Инструмент berdl_start - это инновационное решение для исследования микробной экологии с помощью KBase Data Lakehouse","ar":"أداة berdl_start هي حل مبتكر لاستكشاف علم البيئة الميكروبية باستخدام KBase Data Lakehouse","en":"BERIL Research Observatory - Exploring microbial ecology with the KBase Data Lakehouse"},"seo":{"title":{"zh":"BERIL 研究观测站 AIエージェント - 探索微生物生态","ja":"BERIL 研究観測所 AIエージェント - 微生物生態学の探索","ko":"BERIL 연구 관측소 AI 에이전트 - 미생물 생태학 탐구","es":"Herramientas de IA: berdl_start - Exploración de ecología...","fr":"Outils d''IA : berdl_start - Exploration de l''écologie mic...","de":"KI-Tools: berdl_start - Erforschung der mikrobiellen Ökol...","pt":"Ferramentas de IA: berdl_start - Explorando Ecologia Micr...","ru":"ИИ Агенты: berdl_start - Исследование Микробной Экологии","ar":"أدوات الذكاء الاصطناعي: berdl_start - استكشاف علم البيئة ...","en":"berdl_start"},"description":{"zh":"BERIL 研究观测站 AIエージェント是一个使用 KBase Data Lakehouse 探索微生物生态的工具","ja":"BERIL 研究観測所 AIエージェントは、KBase Data Lakehouse を使用して微生物生態学を探索するためのツールです","ko":"BERIL 연구 관측소 AI 에이전트는 KBase Data Lakehouse를 사용하여 미생물 생태학을 탐구하는 도구입니다","es":"El Observatorio de Investigación BERIL utiliza berdl_start para explorar la ecología microbiana con el Data Lakehouse de KBase","fr":"L''Observatoire de Recherche BERIL utilise berdl_start pour explorer l''écologie microbienne avec le Data Lakehouse de KBase","de":"Das BERIL-Forschungsobservatorium verwendet berdl_start, um die mikrobielle Ökologie mit dem KBase-Data-Lakehouse zu erforschen","pt":"A ferramenta berdl_start é uma solução inovadora para explorar a ecologia microbiana com o KBase Data Lakehouse","ru":"Инструмент berdl_start - это инновационное решение для исследования микробной экологии с помощью KBase Data Lakehouse","ar":"أداة berdl_start هي حل مبتكر لاستكشاف علم البيئة الميكروبية باستخدام KBase Data Lakehouse","en":"BERIL Research Observatory - Exploring microbial ecology with the KBase Data Lakehouse"},"definition":{"en":"BERIL Research Observatory - Exploring microbial ecology with the KBase Data Lakehouse"},"features":{"zh":["使用 KBase Data Lakehouse 探索微生物生态","支持多种数据格式和来源","提供数据可视化和分析工具","支持协作研究和数据共享","提供安全可靠的数据存储和管理"],"ja":["KBase Data Lakehouse を使用して微生物生態学を探索","複数のデータ形式とソースをサポート","データ可視化と分析ツールを提供","コラボレーション研究とデータ共有をサポート","安全で信頼性の高いデータストレージと管理を提供"],"ko":["KBase Data Lakehouse를 사용하여 미생물 생태학을 탐구","다양한 데이터 형식과 출처를 지원","데이터 시각화와 분석 도구를 제공","협력 연구와 데이터 공유를 지원","안전하고 신뢰할 수 있는 데이터 저장소와 관리를 제공"],"es":["Exploración de la ecología microbiana","Integración con el Data Lakehouse de KBase","Análisis de datos avanzados","Visualización de resultados","Colaboración en investigación"],"fr":["Exploration de l''écologie microbienne","Intégration avec le Data Lakehouse de KBase","Analyse de données avancée","Visualisation des résultats","Collaboration dans la recherche"],"de":["Erforschung der mikrobiellen Ökologie","Integration mit dem KBase-Data-Lakehouse","Erweiterte Datenanalyse","Visualisierung der Ergebnisse","Forschungskollaboration"],"pt":["Exploração da ecologia microbiana","Integração com o KBase Data Lakehouse","Análise de dados microbianos","Visualização de resultados","Suporte à pesquisa científica"],"ru":["Исследование микробной экологии","Интеграция с KBase Data Lakehouse","Анализ микробных данных","Визуализация результатов","Поддержка научных исследований"],"ar":["استكشاف علم البيئة الميكروبية","التكامل مع KBase Data Lakehouse","تحليل البيانات الميكروبية","تجسير النتائج","دعم البحث العلمي"]},"keywords":{"zh":["BERIL 研究观测站","KBase Data Lakehouse","微生物生态","AIエージェント","数据可视化","协作研究","数据共享","安全数据存储"],"ja":["BERIL 研究観測所","KBase Data Lakehouse","微生物生態学","AIエージェント","データ可視化","コラボレーション研究","データ共有","安全データストレージ"],"ko":["BERIL 연구 관측소","KBase Data Lakehouse","미생물 생태학","AI 에이전트","데이터 시각화","협력 연구","데이터 공유","안전 데이터 저장소"],"es":["herramientas de IA para ecología microbiana","cómo usar berdl_start","qué es el Data Lakehouse de KBase","berdl_start alternativa","berdl_start vs herramientas de ecología microbiana","instalación de berdl_start","guía de configuración de berdl_start"],"fr":["outils d''IA pour l''écologie microbienne","comment utiliser berdl_start","quoi est le Data Lakehouse de KBase","alternative à berdl_start","berdl_start vs outils d''écologie microbienne","installation de berdl_start","guide de configuration de berdl_start"],"de":["KI-Tools für mikrobielle Ökologie","wie man berdl_start verwendet","was ist das KBase-Data-Lakehouse","Alternative zu berdl_start","berdl_start vs KI-Tools für mikrobielle Ökologie","Installation von berdl_start","Einrichtungsanleitung für berdl_start"],"pt":["ferramentas de ia","ecologia microbiana","kbase data lakehouse","análise de dados microbianos","berdl_start alternative","como usar berdl_start","o que é berdl_start","instalar berdl_start","guias de configuração do berdl_start"],"ru":["ии агенты","микробная экология","kbase data lakehouse","анализ микробных данных","berdl_start альтернатива","как использовать berdl_start","что такое berdl_start","установить berdl_start","руководство по настройке berdl_start"],"ar":["أدوات الذكاء الاصطناعي","علم البيئة الميكروبية","kbase data lakehouse","تحليل البيانات الميكروبية","بديل berdl_start","كيفية استخدام berdl_start","ما هي أداة berdl_start","تثبيت berdl_start","دليل إعداد berdl_start"]}},"owner":"kbaseincubator","repo":"BERIL-research-observatory","repoPath":"kbaseincubator/BERIL-research-observatory","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.695Z","topics":[],"category":"community","skillMd":{"name":"berdl_start","description":"Get started with the BERIL Research Observatory. Use when a user is new, wants orientation, or asks what they can do.","bodyPreview":"# BERIL Research Observatory - Onboarding\n\nWelcome the user and orient them to the system, then route them to the right context based on their goal.\n\n## Phase 1: System Overview\n\nPresent this information directly (no file reads needed):\n\n### What is BERDL?\n\nThe **KBase BER Data Lakehouse (BERDL)** is an on-prem Delta Lakehouse (Spark SQL) hosting **35 databases across 9 tenants**. Key collections:\n\n| Collection | Scale | What it contains |\n|------------|-------|------------------|\n| `kbase_ke_pa","body":"# BERIL Research Observatory - Onboarding\n\nWelcome the user and orient them to the system, then route them to the right context based on their goal.\n\n## Phase 1: System Overview\n\nPresent this information directly (no file reads needed):\n\n### What is BERDL?\n\nThe **KBase BER Data Lakehouse (BERDL)** is an on-prem Delta Lakehouse (Spark SQL) hosting **35 databases across 9 tenants**. Key collections:\n\n| Collection | Scale | What it contains |\n|------------|-------|------------------|\n| `kbase_ke_pangenome` | 293K genomes, 1B genes, 27K species | Species-level pangenomes from GTDB r214: gene clusters, ANI, functional annotations (eggNOG), pathway predictions (GapMind), environmental embeddings (AlphaEarth) |\n| `kbase_genomes` | 293K genomes, 253M proteins | Structural genomics (contigs, features, protein sequences) in CDM format |\n| `kbase_msd_biochemistry` | 56K reactions, 46K molecules | ModelSEED biochemical reactions and compounds for metabolic modeling |\n| `kescience_fitnessbrowser` | 48 organisms, 27M fitness scores | Genome-wide mutant fitness from RB-TnSeq experiments |\n| `enigma_coral` | 3K taxa, 7K genomes | ENIGMA SFA environmental microbiology |\n| `nmdc_arkin` | 48 studies, 3M+ metabolomics | NMDC multi-omics (annotations, embeddings, metabolomics, proteomics) |\n| PhageFoundry (5 DBs) | Various | Species-specific genome browsers for phage-host research |\n| `planetmicrobe_planetmicrobe` | 2K samples, 6K experiments | Marine microbial ecology |\n\n### Repo Structure\n\n```\nprojects/           # Science projects (each has README.md + notebooks/ + data/)\ndocs/               # Shared knowledge base\n  collections.md    # Full database inventory\n  schemas/          # Per-collection schema docs\n  pitfalls.md       # SQL gotchas, data sparsity, common errors\n  performance.md    # Query strategies for large tables\n  research_ideas.md # Future research directions\n  overview.md       # Scientific context and data generation workflow\n  discoveries.md    # Running log of insights\n.claude/skills/     # Agent skills\ndata/               # Shared data extracts reusable across projects\n```\n\n### Available Skills\n\n| Skill | What it does |\n|-------|-------------|\n| `/berdl` | Query BERDL databases via REST API or Spark SQL |\n| `/berdl-query` | Run SQL queries locally with remote Spark compute (CLI tools + notebook support) |\n| `/berdl-minio` | Transfer files between BERDL MinIO and local machine |\n| `/berdl-discover` | Explore and document a new BERDL database |\n| `/literature-review` | Search PubMed, bioRxiv, arXiv, Semantic Scholar, and Google Scholar for relevant biological literature |\n| `/synthesize` | Read analysis outputs, compare against literature, and draft findings |\n| `/submit` | Submit a project for automated review |\n| `/cts` | Run batch compute jobs on the CTS cluster |\n\n> **Note**: Hypothesis generation, research planning, and notebook creation are handled automatically as part of the research workflow (Path 1 below). You don''t need to invoke them separately.\n\n### Existing Projects\n\nDiscover projects dynamically — run `ls projects/` to list them. Read the first line of each `projects/*/README.md` to get titles. Present the list to the user so they can see what''s been done.\n\n### How Projects Work\n\nEach project lives in `projects/<name>/` with a three-file structure plus supporting directories:\n\n```\nprojects/<name>/\n├── README.md            — Project overview, reproduction, authors\n├── RESEARCH_PLAN.md     — Hypothesis, approach, query strategy, revision history\n├── REPORT.md            — Findings, interpretation, supporting evidence\n├── REVIEW.md            — Automated review (generated by /submit)\n├── notebooks/           — Analysis notebooks with saved outputs\n├── data/                — Agent-derived data from queries and analysis\n├── user_data/           — User-provided input data (gene lists, phenotypes, etc.)\n├── figures/             — Key visualizations\n└── requirements.txt     — Python dependencies\n```\n\n**Reproducibility is required**: notebooks must be committed with outputs, figures must be saved to `figures/`, and README must include a `## Reproduction` section. See PROJECT.md for full standards.\n\n---\n\n## Phase 1.5: Environment Detection\n\nBefore routing the user, run environment detection to ensure prerequisites are met:\n\n**Run the detection script:**\n```bash\npython scripts/detect_berdl_environment.py\n```\n\nThis script automatically:\n1. **Detects location**: Tests connectivity to `spark.berdl.kbase.us:443` to determine if you''re on-cluster (BERDL JupyterHub) or off-cluster (local machine)\n2. **On-cluster path**:\n   - Automatically retrieves `KBASE_AUTH_TOKEN` from the environment and saves it to `.env`\n   - Confirms direct access works (no proxy needed)\n   - Reports ready status\n3. **Off-cluster path**:\n   - Checks `.env` for `KBASE_AUTH_TOKEN`\n   - Checks `.venv-berdl` exists\n   - Checks SSH tunnels on ports 1337 and 1338\n   - Checks pproxy on port 8123\n   - Provides specific next steps for anything missing\n\n**Present the output to the user** and help them resolve any issues before proceeding to Phase 2.\n\n**Common resolutions:**\n- **Missing .venv-berdl**: `bash scripts/bootstrap_client.sh`\n- **Missing KBASE_AUTH_TOKEN**: Get token from https://narrative.kbase.us/#auth2/account and add to `.env`\n- **Off-cluster without proxy**: User must start SSH tunnels (requires credentials). See `.claude/skills/berdl-query/references/proxy-setup.md` for full guide. Claude can start pproxy once tunnels are up.\n\n---\n\n## Phase 1.7: Session Naming Reminder\n\nIf the session does not already have a name, remind the user:\n\n> **Tip**: Name this session for easy identification — especially useful for long-running or remote sessions where the connection may drop. A good convention is to match the project name and git branch (e.g., `essential_metabolome`).\n\nThis is a non-blocking reminder. Move on to Phase 2 regardless.\n\n---\n\n## Phase 2: Interactive Routing\n\nAsk the user which of these they want to do:\n\n1. **Start a new research project**\n2. **Explore BERDL data**\n3. **Review published literature**\n4. **Continue an existing project**\n5. **Understand the system**\n\nThen follow the appropriate path below.\n\n---\n\n### Path 1: Start a New Research Project (Orchestrated Workflow)\n\nWhen the user wants to start a new research project, the agent drives the entire process — from ideation through review — checking in with the user at natural decision points rather than requiring manual skill invocations.\n\n#### Phase A: Orientation & Ideation\n\n**Required reading before anything else:**\n1. Read `PROJECT.md` — understand dual goals (science + knowledge capture), project structure requirements, reproducibility standards, JupyterHub workflow, Spark notebook patterns\n2. Read `docs/overview.md` — understand the data architecture, key tables, data generation workflow, known limitations\n3. Read `docs/collections.md` — full database inventory (35 databases, 9 tenants), what data is actually available\n4. Read `docs/pitfalls.md` and `docs/performance.md` — **critical: read these before designing any queries or analysis**\n5. Read `docs/research_ideas.md` — check for existing ideas, avoid duplicating work\n\n**Additional setup (Phase 1.5 should have already checked KBASE_AUTH_TOKEN and proxy):**\n6. Check `gh auth status` — needed for creating branches, PRs, and pushing code. If not authenticated, prompt the user to run `gh auth login`\n7. Note the user''s ORCID and affiliation for the Authors section — ask once, remember for future projects\n\n**Then engage with the user:**\n9. Chat with the user about their research interest\n10. Explore BERDL data (use `/berdl` queries) to check data availability, row counts, column types\n11. Check existing projects (`ls projects/`) — read READMEs of related projects to understand what''s been done\n12. Develop 2-3 testable hypotheses with H0/H1\n13. Search literature (use `/literature-review` internally) for context\n\n#### Phase B: Research Plan\n\n14. Write `RESEARCH_PLAN.md` with: Research Question, Hypothesis, Literature Context, Approach, Data Sources, Query Strategy, Analysis Plan, Expected Outcomes, Revision History (v1)\n15. Write slim `README.md` with: Title, Research Question, Status (In Progress), Overview, Quick Links, Reproduction placeholder, Authors\n16. Create project directory structure: `notebooks/`, `data/`, `user_data/`, `figures/`\n17. Suggest naming this session to match the project: \"Consider naming this session `{project_id}` to match the branch.\"\n18. Create branch `projects/{project_id}`, switch to it, and commit README + RESEARCH_PLAN. Working on a dedicated branch from the start avoids accumulating changes on main during long-running projects. Tell the user what you''re doing — if they prefer to stay on main, skip branch creation.\n19. **Optional: Research plan review** — Offer to run a quick review of the research plan before starting analysis. If the user accepts, invoke the plan reviewer subagent:\n\n    ```bash\n    CLAUDECODE= claude -p \\\n      --system-prompt \"$(cat .claude/reviewer/PLAN_REVIEW_PROMPT.md)\" \\\n      --allowedTools \"Read\" \\\n      --dangerously-skip-permissions \\\n      \"Review the research plan at projects/{project_id}/. Read RESEARCH_PLAN.md and README.md. Also read docs/pitfalls.md, docs/performance.md, docs/collections.md, and PROJECT.md. Check docs/schemas/ for any tables referenced in the plan. List existing projects with ls projects/ and read their README.md files to check for overlap. Return a concise list of suggestions.\"\n    ```\n\n    Present the suggestions to the user. They can address them, note them for later, or skip — this is advisory, not blocking.\n\n#### Phase C: Analysis (Notebooks)\n\n20. Write numbered notebooks (`01_data_exploration.ipynb`, `02_analysis.ipynb`, etc.) following the analysis plan\n21. Notebooks are the primary audit trail — do as much work as possible in notebooks so humans can inspect intermediate results\n22. When parallel execution or complex pipelines are needed, write scripts in `src/` but call them from notebooks\n23. **Run notebooks** — execute cells, inspect outputs, iterate\n24. As new information emerges, update `RESEARCH_PLAN.md` with a revision tag: `- **v2** ({date}): {what changed and why}`\n25. **Check in code frequently** — commit after each major milestone (plan written, notebooks created, data extracted, analysis complete)\n26. Re-read `docs/pitfalls.md` when something doesn''t work as expected\n\n#### Checkpoint: Results Review\n\nAfter notebooks are executed and committed, **pause and present the key results to the user** before moving to synthesis. This is a natural decision point — the user may want to inspect figures, question a result, or request additional analysis before the interpretation gets written.\n\n27. Summarize the key results: main statistics, notable patterns, anything unexpected\n28. Ask: \"Would you like to look at the notebooks/figures before I proceed with the writeup, or should I go ahead with `/synthesize`?\"\n29. If the user wants to explore first, wait. If they want changes, iterate on the notebooks before proceeding.\n\n#### Phase D: Synthesis & Writeup\n\n30. Run `/synthesize` to create `REPORT.md` with findings, interpretation, supporting evidence\n31. Commit the report\n32. Chat with user about the report — revise if needed\n\n#### Phase E: Review & Submission\n\n33. Run `/submit` to validate documentation and generate `REVIEW.md`\n34. Fix any issues flagged by the review\n35. Commit fixes\n36. Upload project to the lakehouse: `python tools/lakehouse_upload.py {project_id}` (prompted by `/submit` after clean review)\n37. Chat with user about next steps\n\n#### Throughout the Entire Workflow:\n- **Check in code often** — don''t let work accumulate uncommitted\n- **Update `docs/discoveries.md`** when you find something interesting (tag with `[project_id]`)\n- **Update `docs/pitfalls.md`** when you hit a gotcha (follow pitfall-capture protocol from `.claude/skills/pitfall-capture/SKILL.md`)\n- **Update `docs/performance.md`** when you learn a query optimization\n- **Re-read `docs/pitfalls.md`** when debugging failures — the answer may already be documented\n- **Re-read `docs/performance.md`** when queries are slow — check for existing optimization patterns\n- **Follow `PROJECT.md` standards** — notebooks with saved outputs, figures as standalone PNGs, requirements.txt, Reproduction section in README\n\n### Path 2: Explore BERDL Data\n\nRead these files:\n- `docs/collections.md` — full database inventory\n- `docs/pitfalls.md` — critical gotchas before querying\n\nThen:\n- Summarize what databases are available and their scale\n- Highlight cross-collection relationships (pangenome <-> genomes <-> biochemistry <-> fitness)\n- Suggest using `/berdl` to start querying\n- Suggest using `/berdl-discover` if they want to explore a database not yet documented in `docs/schemas/`\n- Warn about the key pitfalls (see Critical Pitfalls below)\n\n### Path 3: Review Published Literature\n\nSuggest using `/literature-review` to search biological databases. This is useful for:\n- Checking what''s already known about an organism or pathway before querying BERDL\n- Finding published pangenome analyses to compare against BERDL data\n- Supporting a hypothesis with existing citations\n- Discovering methods and approaches used in similar studies\n\n**MCP setup check**: The `paper-search-mcp` ([openags/paper-search-mcp](https://github.com/openags/paper-search-mcp)) is configured in `.mcp.json`. It runs via `uvx paper-search-mcp`. If it''s not working:\n1. Ensure Python 3.10+ and [uv](https://docs.astral.sh/uv/) are installed\n2. Test: `uvx --from paper-search-mcp python -m paper_search_mcp.server`\n3. Optionally set `SEMANTIC_SCHOLAR_API_KEY` in your environment for enhanced Semantic Scholar features\n4. The skill falls back to WebSearch if the MCP server is unavailable\n\n### Path 4: Continue an Existing Project\n\nSteps:\n1. Run `ls projects/` and list all projects for the user to choose from\n2. Read the chosen project''s `README.md`\n3. Check if a `REVIEW.md` exists in that project directory (read it if so)\n4. Summarize where the project stands: what''s done, what''s next\n5. Suggest using `/submit` when the project is ready for review\n\n### Path 5: Understand the System\n\nRead these files:\n- `PROJECT.md` — high-level goals and structure\n- `docs/collections.md` — database inventory\n- `docs/overview.md` — scientific context and data workflow\n\nThen:\n- Walk through the dual goals (science + knowledge capture)\n- Explain the documentation workflow (tag discoveries, update pitfalls)\n- Mention the UI can be browsed at the BERDL JupyterHub\n- List the available skills and what each does\n- Point to `docs/research_ideas.md` for future directions\n\n---\n\n## Key Principles (for the agent)\n\n1. **Read the docs first** — `PROJECT.md`, `docs/overview.md`, `docs/collections.md`, `docs/pitfalls.md`, and `docs/performance.md` before designing anything. Check existing `projects/` to avoid duplicating work.\n2. **Notebooks are the audit trail** — numbered sequentially (01, 02, 03...), each self-contained with a clear purpose. Commit with saved outputs per `PROJECT.md` reproducibility standards.\n3. **Commit early and often** — after plan, after notebooks, after data extraction, after analysis, after synthesis.\n4. **Branch by default** — create a `projects/{project_id}` branch when starting a new project. Extended work on main causes merge difficulties and risks conflicting with other contributors. Tell the user what branch you''re creating; if they explicitly prefer main, respect that.\n5. **Update the plan** — when the analysis reveals something that changes the approach, update RESEARCH_PLAN.md with a dated revision tag explaining what changed and why.\n6. **Don''t stop and wait** — drive the process forward, checking in with the user at decision points rather than stopping after each step.\n7. **Document as you go** — discoveries go in `docs/discoveries.md`, pitfalls in `docs/pitfalls.md`, performance tips in `docs/performance.md` — captured in real-time, tagged with `[project_id]`.\n8. **Use Spark patterns from PROJECT.md** — `get_spark_session()`, PySpark-first, `.toPandas()` only for final small results.\n\n---\n\n## Critical Pitfalls (always mention)\n\nRegardless of path chosen, surface these early:\n\n1. **Species IDs contain `--`** — This is fine inside quoted strings in SQL. Use exact equality (`WHERE id = ''s__Escherichia_coli--RS_GCF_000005845.2''`), not LIKE patterns.\n2. **Large tables need filters** — Never full-scan `gene` (1B rows) or `genome_ani` (420M rows). Always filter by species or genome ID.\n3. **AlphaEarth embeddings cover only 28%** of genomes (83K/293K) — check coverage before relying on them.\n4. **Match Spark import to environment** — On JupyterHub notebooks: `spark = get_spark_session()` (no import). On JupyterHub CLI/scripts: `from berdl_notebook_utils.setup_spark_session import get_spark_session`. Locally: `from get_spark_session import get_spark_session` (requires `.venv-berdl` + proxy chain). See `docs/pitfalls.md` for details.\n5. **Auth token** — stored in `.env` as `KBASE_AUTH_TOKEN` (not `KB_AUTH_TOKEN`).\n6. **String-typed numeric columns** — Many databases store numbers as strings. Always CAST before comparisons.\n7. **Gene clusters are species-specific** — Cannot compare cluster IDs across species. Use COG/KEGG/PFAM for cross-species comparisons.\n8. **Avoid unnecessary `.toPandas()`** — `.toPandas()` pulls all data to the driver node and can be very slow or cause OOM errors. Use PySpark DataFrame operations for filtering, joins, and aggregations. Only convert to pandas for final small results (plotting, CSV export).\n\n---\n\n## Templates\n\n### RESEARCH_PLAN.md\n\n```markdown\n# Research Plan: {Title}\n\n## Research Question\n{Refined question after literature review}\n\n## Hypothesis\n- **H0**: {Null hypothesis}\n- **H1**: {Alternative hypothesis}\n\n## Literature Context\n{Summary of what''s known, key references, identified gaps}\n\n## Query Strategy\n\n### Tables Required\n| Table | Purpose | Estimated Rows | Filter Strategy |\n|---|---|---|---|\n| {table} | {why needed} | {count} | {how to filter} |\n\n### Key Queries\n1. **{Description}**:\n\\```sql\n{query}\n\\```\n\n### Performance Plan\n- **Tier**: {REST API / JupyterHub}\n- **Estimated complexity**: {simple / moderate / complex}\n- **Known pitfalls**: {list from pitfalls.md}\n\n## Analysis Plan\n\n### Notebook 1: Data Exploration\n- **Goal**: {what to verify/explore}\n- **Expected output**: {CSV/figures}\n\n### Notebook 2: Main Analysis\n- **Goal**: {core analysis}\n- **Expected output**: {CSV/figures}\n\n### Notebook 3: Visualization (if needed)\n- **Goal**: {figures for findings}\n\n## Expected Outcomes\n- **If H1 supported**: {interpretation}\n- **If H0 not rejected**: {interpretation}\n- **Potential confounders**: {list}\n\n## Revision History\n- **v1** ({date}): Initial plan\n\n## Authors\n{ORCID, affiliation}\n```\n\n### README.md\n\n```markdown\n# {Title}\n\n## Research Question\n{Refined question}\n\n## Status\nIn Progress — research plan created, awaiting analysis.\n\n## Overview\n{One-paragraph summary of the hypothesis and approach}\n\n## Quick Links\n- [Research Plan](RESEARCH_PLAN.md) — hypothesis, approach, query strategy\n- [Report](REPORT.md) — findings, interpretation, supporting evidence\n\n## Reproduction\n*TBD — add prerequisites and step-by-step instructions after analysis is complete.*\n\n## Authors\n{Authors}\n```\n"},"lastSynced":"2026-03-04T13:36:20.125Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Science Agents needing advanced microbial ecology analysis with KBase Data Lakehouse integration.","zh":"非常适合需要高级微生物生态学分析的数据科学代理，并且可以与 KBase Data Lakehouse 集成。","ja":"高度な微生物生態学分析が必要なデータサイエンスエージェントに最適であり、KBase Data Lakehouse と統合できます。","ko":"고급 미생물 생태학 분석이 필요한 데이터 과학 에이전트에게 적합하며 KBase Data Lakehouse와 통합할 수 있습니다.","es":"Perfecto para Agentes de Ciencia de Datos que necesitan un análisis de ecología microbiana avanzado con integración de KBase Data Lakehouse.","fr":"Parfait pour les agents de science des données ayant besoin d''une analyse d''écologie microbienne avancée avec une intégration de KBase Data Lakehouse.","de":"Perfekt für Data Science-Agents, die eine erweiterte mikrobielle Ökologie-Analyse mit KBase Data Lakehouse-Integration benötigen.","pt":"Perfeito para Agentes de Ciência de Dados que necessitam de análise avançada de ecologia microbiana com integração do KBase Data Lakehouse.","ru":"Идеально подходит для агентов Data Science, которым требуется продвинутый анализ микробной экологии с интеграцией KBase Data Lakehouse.","ar":"مثالي للوكلاء علم البيانات الذين يحتاجون إلى تحليل متقدم في علم البيئة الميكروبية مع دمج KBase Data Lakehouse."},"recommendation":{"en":"Empowers agents to explore microbial ecology through the KBase BER Data Lakehouse, providing access to 35 databases across 9 tenants and leveraging Spark SQL for comprehensive data analysis, including key collections like `kbase_ke_pa`.","zh":"赋予代理探索微生物生态学的能力，通过 KBase BER Data Lakehouse 提供访问 35 个数据库的权限，跨越 9 个租户，并利用 Spark SQL 进行全面数据分析，包括关键集合如 `kbase_ke_pa`。","ja":"エージェントに微生物生態学を探索する能力を与え、KBase BER Data Lakehouse を通じて 9 つのテナントにわたる 35 のデータベースへのアクセスを提供し、Spark SQL を使用して包括的なデータ分析を行い、`kbase_ke_pa` などの重要なコレクションを含みます。","ko":"에이전트가 미생물 생태학을 탐색할 수 있도록 하며, KBase BER Data Lakehouse를 통해 9개의 테넌트에 걸친 35개의 데이터베이스에 대한 액세스를 제공하고, Spark SQL을 사용하여 포괄적인 데이터 분석을 수행하며, `kbase_ke_pa`와 같은 주요 컬렉션을 포함합니다.","es":"Habilita a los agentes a explorar la ecología microbiana a través de la KBase BER Data Lakehouse, proporcionando acceso a 35 bases de datos en 9 inquilinos y aprovechando Spark SQL para un análisis de datos integral, incluyendo colecciones clave como `kbase_ke_pa`.","fr":"Permet aux agents d''explorer l''écologie microbienne via la KBase BER Data Lakehouse, en fournissant un accès à 35 bases de données sur 9 locataires et en exploitant Spark SQL pour une analyse de données globale, notamment des collections clés comme `kbase_ke_pa`.","de":"Ermächtigt die Agenten, die mikrobielle Ökologie über die KBase BER Data Lakehouse zu erkunden, indem Zugriff auf 35 Datenbanken über 9 Mieter gewährt wird und Spark SQL für eine umfassende Datenanalyse genutzt wird, einschließlich wichtiger Sammlungen wie `kbase_ke_pa`.","pt":"Habilita os agentes a explorar a ecologia microbiana por meio do KBase BER Data Lakehouse, fornecendo acesso a 35 bancos de dados em 9 locatários e aproveitando o Spark SQL para análise de dados abrangente, incluindo coleções-chave como `kbase_ke_pa`.","ru":"Предоставляет агентам возможность изучать микробную экологию через KBase BER Data Lakehouse, обеспечивая доступ к 35 базам данных в 9 арендаторах и использует Spark SQL для всестороннего анализа данных, включая ключевые коллекции, такие как `kbase_ke_pa`.","ar":"تمكّن الوكلاء من استكشاف علم البيئة الميكروبية من خلال KBase BER Data Lakehouse، ويتوفّر الوصول إلى 35 قاعدة بيانات عبر 9 مستأجرين، ويعتمد على Spark SQL لتحليل بيانات شامل، بما في ذلك مجموعات رئيسية مثل `kbase_ke_pa`."},"useCases":{"en":["Onboarding users to the BERIL Research Observatory","Routing users to the right context based on their goal","Presenting system overviews of the KBase BER Data Lakehouse"],"zh":["将用户引导至 BERIL 研究观测台","根据用户的目标将用户路由至正确的上下文","展示 KBase BER Data Lakehouse 的系统概述"],"ja":["BERIL 研究観測台へのユーザー紹介","ユーザーの目標に基づいてユーザーを正しいコンテキストにルーティングする","KBase BER Data Lakehouse のシステム概要の提示"],"ko":["사용자를 BERIL 연구 관측소에 온보딩하는 것","사용자의 목표에 따라 사용자를 올바른 컨텍스트로 라우팅하는 것","KBase BER Data Lakehouse의 시스템 개요를 제시하는 것"],"es":["Incorporación de usuarios al Observatorio de Investigación BERIL","Enrutamiento de usuarios al contexto correcto según su objetivo","Presentación de vistas generales del sistema de la KBase BER Data Lakehouse"],"fr":["Intégration des utilisateurs à l''Observatoire de Recherche BERIL","Acheminement des utilisateurs vers le contexte approprié en fonction de leur objectif","Présentation des vues d''ensemble du système de la KBase BER Data Lakehouse"],"de":["Onboarding von Benutzern in das BERIL-Forschungsobservatorium","Weiterleitung von Benutzern in den richtigen Kontext basierend auf ihrem Ziel","Präsentation von Systemübersichten der KBase BER Data Lakehouse"],"p