INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nevir/agentfill/skill', 'skill', 'nevir', 'agentfill', 'community', 'skill nevir agentfill community AI智能代理工具是一个polyfill，标准化和集中AGENTS.md配置和Agent Skills支持 AIエージェントツールはpolyfillで、AGENTS.md設定とAgent Skillsサポートを標準化および集中管理します AI 에이전트 도구는 polyfill로 AGENTS.md 구성과 에이전트 기술 지원을 표준화하고集中 관리합니다 Un polyfill que estandariza y centraliza la configuración de AGENTS.md y soporte de habilidades de agentes en su repositorio Un polyfill qui standardise et centralise la configuration de AGENTS.md et le support des compétences des agents dans votre référentiel Ein Polyfill, der die Konfiguration von AGENTS.md und die Unterstützung von Agentenfähigkeiten in Ihrem Repository standardisiert und zentralisiert O polyfill para AGENTS.md é uma solução que padroniza e centraliza a configuração de habilidades de agentes em seu repositório, tornando mais fácil a gestão de agentes de inteligência artificial Polyfill для AGENTS.md — это решение, которое стандартизирует и централизует настройку навыков агентов в вашем репозитории, делая более простым управление агентами ИИ بوليفيل AGENTS.md هو حل يوحّد وتكامل إعدادات مهارات الوكيل في مستودعك، مما يسهل إدارة وكلاء الذكاء الاصطناعي A "polyfill" that standardizes and centralizes AGENTS.md configuration and Agent Skills support within your repository. AI智能代理工具 AGENTS.md配置 Agent Skills支持 开发效率 配置和技能支持 如何使用AI智能代理工具 AI智能代理工具安装 AI智能代理工具设置指南 A "polyfill" that standardizes and centralizes AGENTS.md configuration and Agent Skills support within your repository.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Aias/red-cliff-record/rcr-backend', 'community', 'Aias', 'red-cliff-record', 'Aias/red-cliff-record', 'rcr-backend', 0, 0, 45, '2026-03-04T13:07:01.707Z', '2026-03-04T13:42:09.248Z', '641d679890673282006d147c38d38baf556c9c4f970ccf6a64436a1628ec88a9', '{"id":"Aias/red-cliff-record/rcr-backend","name":"rcr-backend","description":{"zh":"rcr-backend是一个本地优先、自主数据管理的个人知识管理工具，继承了barnsworthburning的精髓","ja":"rcr-backendは、ローカルファースト、データ所有の個人知識管理ツールであり、barnsworthburningの精神的後継者","ko":"rcr-backend는 로컬 우선, 데이터 소유의 개인 지식 관리 도구로, barnsworthburning의 정수를 이어받은 기술","es":"rcr-backend es una herramienta de gestión de conocimiento personal de código abierto que permite a los usuarios gestionar sus datos de forma local","fr":"rcr-backend est un outil de gestion des connaissances personnelles open source qui permet aux utilisateurs de gérer leurs données de manière locale","de":"rcr-backend ist ein Open-Source-Tool für persönliches Wissensmanagement, das es Benutzern ermöglicht, ihre Daten lokal zu verwalten","pt":"O rcr-backend é uma abordagem local-first para gerenciamento de conhecimento pessoal, permitindo que você mantenha o controle sobre seus dados.","ru":"rcr-backend - это местный подход к управлению личными знаниями, позволяющий вам владеть своими данными.","ar":"rcr-backend هو نهج محلي أول للتعامل مع المعرفة الشخصية، يتيح لك الحفاظ على سيطرتك على بياناتك.","en":"A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. "},"seo":{"title":{"zh":"个人知识管理AI工具 - rcr-backend","ja":"AIエージェント - rcr-backend","ko":"개인 지식 관리 AI 에이전트 - rcr-backend","es":"Herramientas de inteligencia artificial para gestión de c...","fr":"Outils d''agents IA pour la gestion des connaissances pers...","de":"KI-Tools für persönliches Wissensmanagement - rcr-backend","pt":"Ferramentas de IA: rcr-backend para Gerenciamento de Conh...","ru":"ИИ Агенты: rcr-backend для управления личными знаниями","ar":"أدوات الذكاء الاصطناعي: rcr-backend لإدارة المعرفة الشخصية","en":"rcr-backend"},"description":{"zh":"rcr-backend是一个本地优先、自主数据管理的个人知识管理工具，继承了barnsworthburning的精髓","ja":"rcr-backendは、ローカルファースト、データ所有の個人知識管理ツールであり、barnsworthburningの精神的後継者","ko":"rcr-backend는 로컬 우선, 데이터 소유의 개인 지식 관리 도구로, barnsworthburning의 정수를 이어받은 기술","es":"rcr-backend es una herramienta de gestión de conocimiento personal de código abierto que permite a los usuarios gestionar sus datos de forma local","fr":"rcr-backend est un outil de gestion des connaissances personnelles open source qui permet aux utilisateurs de gérer leurs données de manière locale","de":"rcr-backend ist ein Open-Source-Tool für persönliches Wissensmanagement, das es Benutzern ermöglicht, ihre Daten lokal zu verwalten","pt":"O rcr-backend é uma abordagem local-first para gerenciamento de conhecimento pessoal, permitindo que você mantenha o controle sobre seus dados.","ru":"rcr-backend - это местный подход к управлению личными знаниями, позволяющий вам владеть своими данными.","ar":"rcr-backend هو نهج محلي أول للتعامل مع المعرفة الشخصية، يتيح لك الحفاظ على سيطرتك على بياناتك.","en":"A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. "},"definition":{"en":"A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. "},"features":{"zh":["本地优先数据管理","自主数据所有权","个人知识管理","继承barnsworthburning的精髓","支持多种开发语言"],"ja":["ローカルファーストデータ管理","データ所有権の自主性","個人知識管理","barnsworthburningの精神的後継","多種開発言語のサポート"],"ko":["로컬 우선 데이터 관리","데이터 소유권의 자율성","개인 지식 관리","barnsworthburning의 정수를 이어받은 기술","다양한 개발 언어 지원"],"es":["Gestión de conocimiento personal con enfoque en datos locales","Código abierto y personalizable","Integración con herramientas de desarrollo","Seguridad y privacidad de los datos","Facilidad de uso y configuración"],"fr":["Gestion des connaissances personnelles avec une approche de données locales","Code open source et personnalisable","Intégration avec des outils de développement","Sécurité et confidentialité des données","Facilité d''utilisation et de configuration"],"de":["Persönliches Wissensmanagement mit Fokus auf lokale Daten","Open-Source-Code und anpassbar","Integration mit Entwicklungstools","Sicherheit und Datenschutz","Einfachheit bei der Verwendung und Konfiguration"],"pt":["Abordagem local-first para gerenciamento de conhecimento","Controle total sobre seus dados","Sucessor espiritual do barnsworthburning","Ferramenta de IA para gerenciamento de conhecimento pessoal","Privacidade e segurança de dados"],"ru":["Местный подход к управлению личными знаниями","Полный контроль над своими данными","Духовный преемник barnsworthburning","Инструмент ИИ для управления личными знаниями","Конфиденциальность и безопасность данных"],"ar":["نهج محلي أول للتعامل مع المعرفة الشخصية","سيطرة كاملة على بياناتك","الخليفة الروحي لبarnsworthburning","أداة الذكاء الاصطناعي لإدارة المعرفة الشخصية","الخصوصية وأمان البيانات"]},"keywords":{"zh":["个人知识管理工具","AI工具","本地优先数据管理","自主数据所有权","rcr-backend安装","rcr-backend教程","rcr-backend替代品"],"ja":["個人知識管理ツール","AIエージェント","ローカルファーストデータ管理","データ所有権の自主性","rcr-backendのインストール","rcr-backendのチュートリアル","rcr-backendの代替"],"ko":["개인 지식 관리 도구","AI 에이전트","로컬 우선 데이터 관리","데이터 소유권의 자율성","rcr-backend 설치","rcr-backend 가이드","rcr-backend 대체"],"es":["herramientas de inteligencia artificial","gestión de conocimiento personal","datos locales","código abierto","desarrollo de software","seguridad de datos","privacidad de datos","rcr-backend alternativa","rcr-backend vs barnsworthburning"],"fr":["outils d''agents IA","gestion des connaissances personnelles","données locales","code open source","développement de logiciels","sécurité des données","confidentialité des données","rcr-backend alternative","rcr-backend vs barnsworthburning"],"de":["KI-Tools","persönliches Wissensmanagement","lokale Daten","Open-Source-Code","Software-Entwicklung","Daten-Sicherheit","Datenschutz","rcr-backend Alternative","rcr-backend vs barnsworthburning"],"pt":["como usar rcr-backend","o que é rcr-backend","ferramentas de ia para gerenciamento de conhecimento","rcr-backend vs barnsworthburning","instalar rcr-backend","guia de configuração do rcr-backend","alternativas ao rcr-backend"],"ru":["как использовать rcr-backend","что такое rcr-backend","инструменты ИИ для управления знаниями","rcr-backend vs barnsworthburning","установить rcr-backend","руководство по настройке rcr-backend","альтернативы rcr-backend"],"ar":["كيفية استخدام rcr-backend","ما هو rcr-backend","أدوات الذكاء الاصطناعي لإدارة المعرفة","rcr-backend مقابل barnsworthburning","تثبيت rcr-backend","دليل إعداد رcr-backend","بديلات rcr-backend"]}},"owner":"Aias","repo":"red-cliff-record","repoPath":"Aias/red-cliff-record","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.707Z","topics":[],"category":"community","skillMd":{"name":"rcr-backend","description":"Database, API, and integration conventions for Red Cliff Record. Use when working with Drizzle ORM, tRPC routers, database migrations, integration syncs, or media alt-text workflows in this project. Triggers on database queries, API routes, Drizzle v2, tRPC, Zod validation, integration work, or `rcr media` commands.","bodyPreview":"# RCR Backend\n\nSupplements global `typescript-guidelines` skill.\n\n## Drizzle ORM\n\n- **Always use Drizzle v2 query syntax** for reads: `db.query.<table>.findMany/findFirst` (not `db.select().from()`)\n  - Provides object-style `where`, built-in `with` for relations, and `columns` selection\n- Avoid raw SQL — use query builder APIs instead of `sql` template literals\n- Mutations: `db.insert()`, `db.update()`, `db.delete()`\n- Always upsert with `.onConflictDoUpdate()` on insertions\n- External-source P","body":"# RCR Backend\n\nSupplements global `typescript-guidelines` skill.\n\n## Drizzle ORM\n\n- **Always use Drizzle v2 query syntax** for reads: `db.query.<table>.findMany/findFirst` (not `db.select().from()`)\n  - Provides object-style `where`, built-in `with` for relations, and `columns` selection\n- Avoid raw SQL — use query builder APIs instead of `sql` template literals\n- Mutations: `db.insert()`, `db.update()`, `db.delete()`\n- Always upsert with `.onConflictDoUpdate()` on insertions\n- External-source PKs: `integer(''id'').primaryKey()` (not `serial`)\n- Never edit Drizzle meta files (`snapshot.json`, `_journal.json`) — they''re generated by `drizzle-kit`\n\n## tRPC\n\n- Routers live in `src/server/api/routers/`\n- Zod v4 for input validation\n- Client hooks from `src/app/trpc.ts`\n- Invalidate queries after mutations\n\n## Integrations\n\nCanonical guide: `INTEGRATIONS.md`.\n\n- Sync logic wrapped by `runIntegration`; exposed via `rcr sync <name>`\n- File convention: `types.ts` (Zod schemas), `client.ts` (API client), `sync.ts` (orchestration)\n- Respect rate limits; batch where needed; upsert for idempotency\n\n## Database Management\n\nCanonical operations: `README.md` and `src/server/db/db-manager.sh`.\n\n- `bun run db:generate` to generate migration files (safe for agent)\n- `bun run db:studio` for database inspection\n- Never run migrations (`bun run db:migrate`, `bunx drizzle-kit migrate`) — always provide the command for the user to run\n- Never run destructive operations without explicit user permission\n- Backups are named by environment (`prod-{timestamp}.dump`, `dev-{timestamp}.dump`), not database name\n\n## Agent Workflow: Media Alt Text\n\nThe `rcr media` commands support CLI-based alt text updates. Workflow for looped agents:\n\n1. **List** images needing alt text:\n   ```bash\n   rcr media list --type=image --alt-text=false --limit=100 --order=recordCreatedAt\n   ```\n2. **Get** item with parent record context:\n   ```bash\n   rcr media get <id> --with-record\n   ```\n   Returns media item plus `record: { id, title, type, mediaCaption, url }`.\n3. **Update**:\n   ```bash\n   rcr media update <id> ''{\"altText\": \"Description of the image\"}''\n   ```\n\n**Parallel processing**: pre-assign media IDs per agent to avoid overlap. Parent fetches a batch, splits into chunks, each subagent processes its assigned IDs.\n\nSchema: `media` table has `altText` (nullable), `url`, `type`, `width`, `height`, `recordId` (FK). ~4,090 images total.\n"},"lastSynced":"2026-03-04T13:42:09.248Z","agentAnalysis":{"suitability":{"en":"Perfect for TypeScript-based AI Agents needing advanced local-first data management capabilities with Drizzle ORM.","zh":"非常适合需要高级本地优先数据管理功能的基于TypeScript的AI代理，使用Drizzle ORM。","ja":"TypeScriptベースのAIエージェントに高級なローカルファーストのデータ管理機能を必要とする場合に最適です。Drizzle ORMを使用します。","ko":"고급 로컬 우선 데이터 관리 기능이 필요한 TypeScript 기반 AI 에이전트에게 적합합니다. Drizzle ORM을 사용합니다.","es":"Perfecto para Agentes de IA basados en TypeScript que necesitan capacidades de gestión de datos de primera localización avanzadas con Drizzle ORM.","fr":"Parfait pour les agents d''IA basés sur TypeScript nécessitant des capacités de gestion de données locales avancées avec Drizzle ORM.","de":"Perfekt für auf TypeScript basierende KI-Agents, die erweiterte lokale Datenverwaltungsfunktionen mit Drizzle ORM benötigen.","pt":"Perfeito para Agentes de IA baseados em TypeScript que necessitam de capacidades de gerenciamento de dados locais avançadas com Drizzle ORM.","ru":"Идеально подходит для агентов ИИ на основе TypeScript, которым необходимы продвинутые возможности управления локальными данными с помощью Drizzle ORM.","ar":"مثالي للوكلاء الذكيين المستندة إلى TypeScript التي تحتاج إلى إمكانيات إدارة البيانات المحلية المتقدمة مع Drizzle ORM."},"recommendation":{"en":"Empowers agents to manage personal knowledge with a local-first approach, utilizing Drizzle v2 query syntax for efficient reads and mutations, and providing object-style where clauses, built-in with relations, and columns selection through APIs like db.query and db.insert.","zh":"赋予代理以本地优先的方式管理个人知识的能力，利用Drizzle v2查询语法进行高效的读取和变异，并提供带有关系和列选择的对象样式where子句，通过API如db.query和db.insert进行构建。","ja":"エージェントがローカルファーストのアプローチで個人の知識を管理する能力を提供します。Drizzle v2クエリ構文を使用して効率的な読み取りとミューテーションを行い、関係や列選択を含むオブジェクトスタイルのWHERE句を提供し、db.queryやdb.insertなどのAPIを使用して構築します。","ko":"에이전트가 로컬 우선 접근 방식으로 개인 지식을 관리할 수 있는 능력을 제공합니다. Drizzle v2 쿼리 구문을 사용하여 효율적인 읽기 및 변경을 수행하고 관계 및 열 선택을 포함하는 객체 스타일 WHERE 절을 제공하며 db.query 및 db.insert와 같은 API를 사용하여 구축합니다.","es":"Habilita a los agentes a gestionar conocimientos personales con un enfoque de primera localización, utilizando la sintaxis de consulta de Drizzle v2 para lecturas y mutaciones eficientes, y proporcionando cláusulas de estilo de objeto, relaciones integradas y selección de columnas a través de API como db.query y db.insert.","fr":"Permet aux agents de gérer les connaissances personnelles avec une approche locale première, en utilisant la syntaxe de requête Drizzle v2 pour des lectures et des mutations efficaces, et en fournissant des clauses de style d''objet, des relations intégrées et une sélection de colonnes via des API comme db.query et db.insert.","de":"Ermöglicht es Agenten, persönliche Kenntnisse mit einem lokalen Ansatz zu verwalten, indem sie die Drizzle v2-Abfragesyntax für effiziente Lese- und Schreibvorgänge verwenden und Objekt-Style-Where-Klauseln, integrierte Beziehungen und Spaltenauswahl durch APIs wie db.query und db.insert bereitstellen.","pt":"Habilita os agentes a gerenciar o conhecimento pessoal com uma abordagem local-primeiro, utilizando a sintaxe de consulta Drizzle v2 para leituras e mutações eficientes, e fornecendo cláusulas where de estilo de objeto, relações incorporadas e seleção de colunas por meio de APIs como db.query e db.insert.","ru":"Наделяет агентов возможностью управлять личными знаниями с локально-ориентированным подходом, использую синтаксис запросов Drizzle v2 для эффективного чтения и изменений, и предоставляя объектные где-условия, встроенные отношения и выбор столбцов через API, такие как db.query и db.insert.","ar":"تمكّن الوكلاء من إدارة المعرفة الشخصية بالمقاربة المحلية أولاً، باستخدام بناء جملة استعلام Drizzle v2 من أجل عمليات قراءة وتبديل فعالة، وتوفير شرط حيث بنية كائنية، وعلاقات مدمجة، واختيار أعمدة من خلال واجهات برمجة التطبيقات مثل db.query و db.insert."},"useCases":{"en":["Automating data upserts with onConflictDoUpdate","Generating efficient database queries using Drizzle v2 syntax","Building local-first personal knowledge management systems"],"zh":["使用onConflictDoUpdate自动执行数据upsert","使用Drizzle v2语法生成高效的数据库查询","使用Drizzle构建本地优先的个人知识管理系统"],"ja":["onConflictDoUpdateを使用してデータのupsertを自動化する","Drizzle v2構文を使用して効率的なデータベースクエリを生成する","Drizzleを使用してローカルファーストの個人知識管理システムを構築する"],"ko":["onConflictDoUpdate를 사용하여 데이터 업서트를 자동화하는こと","Drizzle v2 구문을 사용하여 효율적인 데이터베이스 쿼리를 생성하는 것","Drizzle를 사용하여 로컬 우선 개인 지식 관리 시스템을 구축하는 것"],"es":["Automatizar actualizaciones de datos con onConflictDoUpdate","Generar consultas de base de datos eficientes mediante la sintaxis de Drizzle v2","Crear sistemas de gestión de conocimientos personales de primera localización"],"fr":["Automatiser les mises à jour de données avec onConflictDoUpdate","Générer des requêtes de base de données efficaces à l''aide de la syntaxe Drizzle v2","Créer des systèmes de gestion des connaissances personnelles de première localisation"],"de":["Automatisieren von Datenaktualisierungen mit onConflictDoUpdate","Erstellen effizienter Datenbankabfragen mit der Drizzle v2-Syntax","Erstellen lokaler persönlicher Wissensmanagementsysteme"],"pt":["Automatizar upserts de dados com onConflictDoUpdate","Gerar consultas de banco de dados eficientes usando a sintaxe Drizzle v2","Construir sistemas de gerenciamento de conhecimento pessoal local-primeiro"],"ru":["Автоматизировать обновления данных с onConflictDoUpdate","Генерировать эффективные запросы к базе данных, используя синтаксис Drizzle v2","Строить локально-ориентированные системы управления личными знаниями"],"ar":["توتير تحديثات البيانات باستخدام onConflictDoUpdate","توليد استفسارات قاعدة البيانات الفعالة باستخدام بناء الجملة Drizzle v2","بناء نظم إدارة المعرفة الشخصية المحلية أولاً"]},"limitations":{"en":["Requires TypeScript environment","Dependent on Drizzle ORM v2","Avoids raw SQL in favor of query builder APIs"],"zh":["需要TypeScript环境","依赖Drizzle ORM v2","避免使用原始SQL，推荐使用查询构建器API"],"ja":["TypeScript環境が必要","Drizzle ORM v2に依存","生SQLを避け、クエリビルダAPIを使用する"],"ko":["TypeScript 환경이 필요함","Drizzle ORM v2에 의존함","원시 SQL을 피하고 쿼리 빌더 API를 사용하는 것"],"es":["Requiere entorno de TypeScript","Dependiente de Drizzle ORM v2","Evita SQL sin procesar a favor de APIs de generadores de consultas"],"fr":["Nécessite un environnement TypeScript","Dépendant de Drizzle ORM v2","Évite le SQL brut au profit des API de générateurs de requêtes"],"de":["Benötigt eine TypeScript-Umgebung","Abhängig von Drizzle ORM v2","Vermeidet rohes SQL zugunsten von Abfrage-Generator-APIs"],"pt":["Exige ambiente TypeScript","Dependente do Drizzle ORM v2","Evita SQL bruto em favor de APIs de construtor de consultas"],"ru":["Требует среды TypeScript","Зависит от Drizzle ORM v2","Избегает сырого SQL в пользу API-интерфейсов запросов"],"ar":["يتطلب بيئة TypeScript","يعتمد على Drizzle ORM v2","يتجنب SQL الخام لصالح واجهات برمجة التطبيقات لمصنع الاستعلامات"]},"version":3},"contentHash":"641d679890673282006d147c38d38baf556c9c4f970ccf6a64436a1628ec88a9","qualityScore":45}');
