INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Aias/red-cliff-record/rcr-backend', 'rcr-backend', 'Aias', 'red-cliff-record', 'community', 'rcr-backend Aias red-cliff-record community rcr-backend是一个本地优先、自主数据管理的个人知识管理工具，继承了barnsworthburning的精髓 rcr-backendは、ローカルファースト、データ所有の個人知識管理ツールであり、barnsworthburningの精神的後継者 rcr-backend는 로컬 우선, 데이터 소유의 개인 지식 관리 도구로, barnsworthburning의 정수를 이어받은 기술 rcr-backend es una herramienta de gestión de conocimiento personal de código abierto que permite a los usuarios gestionar sus datos de forma local rcr-backend est un outil de gestion des connaissances personnelles open source qui permet aux utilisateurs de gérer leurs données de manière locale rcr-backend ist ein Open-Source-Tool für persönliches Wissensmanagement, das es Benutzern ermöglicht, ihre Daten lokal zu verwalten O rcr-backend é uma abordagem local-first para gerenciamento de conhecimento pessoal, permitindo que você mantenha o controle sobre seus dados. rcr-backend - это местный подход к управлению личными знаниями, позволяющий вам владеть своими данными. rcr-backend هو نهج محلي أول للتعامل مع المعرفة الشخصية، يتيح لك الحفاظ على سيطرتك على بياناتك. A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. 个人知识管理工具 AI工具 本地优先数据管理 自主数据所有权 rcr-backend安装 rcr-backend教程 rcr-backend替代品 A local-first, own-your-data approach to personal knowledge management. The spiritual successor to barnsworthburning. ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('IsKenKenYa/Open1PanelApp/ui-visual-validator', 'community', 'IsKenKenYa', 'Open1PanelApp', 'IsKenKenYa/Open1PanelApp', 'ui-visual-validator', 0, 0, 45, '2026-03-04T13:07:01.707Z', '2026-03-04T13:42:18.476Z', '2bd7895f9ce5998accba090994bb47a51f37f0f65350e816ab80af4753a98907', '{"id":"IsKenKenYa/Open1PanelApp/ui-visual-validator","name":"ui-visual-validator","description":{"zh":"UI视觉验证器是一款基于1Panel Open API的移动应用，提供智能化的UI验证功能","ja":"UIビジュアルバリデーターは、1Panel Open APIを利用したモバイルアプリで、スマートなUI検証機能を提供する","ko":"UI 시각적 검증기는 1Panel Open API 기반의 모바일 애플리케이션으로, 지능형 UI 검증 기능을 제공합니다","es":"ui-visual-validator es una herramienta de AI para validar interfaces visuales en apps móviles basada en 1Panel Open API, ideal para desarrolladores","fr":"ui-visual-validator est un outil d''IA pour valider les interfaces visuelles dans les applications mobiles basé sur 1Panel Open API, idéal pour les développeurs","de":"ui-visual-validator ist ein AI-Tool zur Validierung von visuellen Schnittstellen in mobilen Apps basierend auf 1Panel Open API, ideal für Entwickler","pt":"O Validador Visual UI é uma ferramenta de AI Agente baseada na API 1Panel Open, projetada para desenvolvedores móveis","ru":"Визуальный Валидатор UI - это инструмент ИИ Агента на основе открытого API 1Panel, предназначенный для мобильных разработчиков","ar":"مُصادِق بِياني UI هو أداة وكلية إِصطناعي تعتمد على واجهة برمجة التطبيقات 1Panel المفتوحة، مصممة لمنشئي التطبيقات النقالة","en":"A mobile App based on the 1Panel Open API."},"seo":{"title":{"zh":"UI视觉验证器 - 基于1Panel Open API的AI工具","ja":"UIビジュアルバリデーター - 1Panel Open APIを利用したAIエージェント","ko":"UI 시각적 검증기 - 1Panel Open API 기반의 AI 에이전트","es":"Herramientas de AI: ui-visual-validator para apps móviles","fr":"Outils d''IA: ui-visual-validator pour applications mobiles","de":"AI-Tools: ui-visual-validator für mobile Apps","pt":"Valid