INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('IsKenKenYa/Open1PanelApp/ui-visual-validator', 'ui-visual-validator', 'IsKenKenYa', 'Open1PanelApp', 'community', 'ui-visual-validator IsKenKenYa Open1PanelApp community UI视觉验证器是一款基于1Panel Open API的移动应用，提供智能化的UI验证功能 UIビジュアルバリデーターは、1Panel Open APIを利用したモバイルアプリで、スマートなUI検証機能を提供する UI 시각적 검증기는 1Panel Open API 기반의 모바일 애플리케이션으로, 지능형 UI 검증 기능을 제공합니다 ui-visual-validator es una herramienta de AI para validar interfaces visuales en apps móviles basada en 1Panel Open API, ideal para desarrolladores ui-visual-validator est un outil d''IA pour valider les interfaces visuelles dans les applications mobiles basé sur 1Panel Open API, idéal pour les développeurs ui-visual-validator ist ein AI-Tool zur Validierung von visuellen Schnittstellen in mobilen Apps basierend auf 1Panel Open API, ideal für Entwickler O Validador Visual UI é uma ferramenta de AI Agente baseada na API 1Panel Open, projetada para desenvolvedores móveis Визуальный Валидатор UI - это инструмент ИИ Агента на основе открытого API 1Panel, предназначенный для мобильных разработчиков مُصادِق بِياني UI هو أداة وكلية إِصطناعي تعتمد على واجهة برمجة التطبيقات 1Panel المفتوحة، مصممة لمنشئي التطبيقات النقالة A mobile App based on the 1Panel Open API. UI视觉验证器 1Panel Open API AI工具 移动应用开发 UI设计 如何使用UI视觉验证器 UI视觉验证器安装 UI视觉验证器设置指南 A mobile App based on the 1Panel Open API.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('olavocarvalho/engrain/biome', 'community', 'olavocarvalho', 'engrain', 'olavocarvalho/engrain', 'biome', 0, 0, 45, '2026-03-04T13:07:01.714Z', '2026-03-04T13:46:31.948Z', '9c1ebccf003c106d060a43d19ac819a0cece9badc9b7e5cb8354dc6e47b7f59f', '{"id":"olavocarvalho/engrain/biome","name":"biome","description":{"zh":"biome是AI智能代理的一项技能，允许将文档索引嵌入AGENTS.md文件中，实现实时文档查找","ja":"biomeはAIエージェントのスキルであり、AGENTS.mdにドキュメントインデックスを埋め込むことで、常にオンのエージェントコンテキストを実現します","ko":"biome는 AI 에이전트의 기능으로 AGENTS.md에 문서 인덱스를 삽입하여 항상 켜진 에이전트 문맥을 제공합니다","es":"Biome es una herramienta que ayuda a los desarrolladores a crear documentación para agentes de inteligencia artificial","fr":"Biome est un outil qui aide les développeurs à créer des documentations pour les agents de l''intelligence artificielle","de":"Biome ist ein Tool, das den Entwicklern hilft, Dokumentationen für KI-Agents zu erstellen","pt":"Biome é uma ferramenta de IA que permite embeder índices de documentação em AGENTS.md para contexto de agente sempre ativado","ru":"Biome - это инструмент ИИ, который позволяет внедрить индексы документации в AGENTS.md для всегда включенного контекста агента","ar":"بيوم هو أداة ذكاء اصطناعي تمكن من دمج فهارس توثيق في AGENTS.md لسياق وكلاء دائم","en":"Embed documentation indexes into AGENTS.md for always-on agent context"},"seo":{"title":{"zh":"AI智能代理biome：实时文档索引","ja":"AIエージェントbiome：常にオンのエージェントコンテキスト","ko":"AI 에이전트 biome: 항상 켜진 에이전트 문맥","es":"Biome: Herramienta de documentación para agentes de intel...","fr":"Biome: Outil de documentation pour les agents de l''intell...","de":"Biome: Dokumentations-Tool für KI-Agents","pt":"Ferramentas de IA: Biome para Documentação de Agentes","ru":"ИИ Агенты: Biome для Embed Индексов Документации","ar":"أدوات الذكاء الاصطناعي: بيوم لتوثيق العوامل","en":"biome"},"description":{"zh":"biome是AI智能代理的一项技能，允许将文档索引嵌入AGENTS.md文件中，实现实时文档查找","ja":"biomeはAIエージェントのスキルであり、AGENTS.mdにドキュメントインデックスを埋め込むことで、常にオンのエージェントコンテキストを実現します","ko":"biome는 AI 에이전트의 기능으로 AGENTS.md에 문서 인덱스를 삽입하여 항상 켜진 에이전트 문맥을 제공합니다","es":"Biome es una herramienta que ayuda a los desarrolladores a crear documentación para agentes de inteligencia artificial","fr":"Biome est un outil qui aide les développeurs à créer des documentations pour les agents de l''intelligence artificielle","de":"Biome ist ein Tool, das den Entwicklern hilft, Dokumentationen für KI-Agents zu erstellen","pt":"Biome é uma ferramenta de IA que permite embeder índices de documentação em AGENTS.md para contexto de agente sempre ativado","ru":"Biome - это инструмент ИИ, который позволяет внедрить индексы документации в AGENTS.md для всегда включенного контекста агента","ar":"بيوم هو أداة ذكاء اصطناعي تمكن من دمج فهارس توثيق في AGENTS.md لسياق وكلاء دائم","en":"Embed documentation indexes into AGENTS.md for always-on agent context"},"definition":{"en":"Embed documentation indexes into AGENTS.md for always-on agent context"},"features":{"zh":["实时文档索引","AGENTS.md文件嵌入","AI智能代理技能","提高开发效率","简化文档查找"],"ja":["常にオンのドキュメントインデックス","AGENTS.mdへのインデックス埋め込み","AIエージェントのスキル","開発効率の向上","ドキュメント検索の簡素化"],"ko":["항상 켜진 문서 인덱스","AGENTS.md에 인덱스 삽입","AI 에이전트의 기능","개발 효율성 향상","문서 검색의 간소화"],"es":["Documentación para agentes de inteligencia artificial","Integración con AGENTS.md","Contexto de documentación para agentes","Documentación siempre disponible"],"fr":["Documentation pour les agents de l''intelligence artificielle","Intégration avec AGENTS.md","Contexte de documentation pour les agents","Documentation toujours disponible"],"de":["Dokumentation für KI-Agents","Integrationsmöglichkeit mit AGENTS.md","Dokumentationskontext für KI-Agents","Dokumentation immer verfügbar"],"pt":["Integração de índices de documentação em AGENTS.md","Contexto de agente sempre ativado","Suporte a documentação de agentes","Fácil implementação com React, Python e Node.js","Compatibilidade com CLI"],"ru":["Внедрение индексов документации в AGENTS.md","Всегда включенный контекст агента","Поддержка документации агентов","Легкая реализация с помощью React, Python и Node.js","Совместимость с CLI"],"ar":["دمج فهارس توثيق في AGENTS.md","سياق وكلاء دائم","دعم توثيق الوكلاء","تنفيذ سهل مع React و Python و Node.js","التوافق مع CLI"]},"keywords":{"zh":["AI智能代理","biome","实时文档索引","AGENTS.md","如何使用biome","biome安装指南","AI智能代理工具"],"ja":["AIエージェント","biome","常にオンのドキュメントインデックス","AGENTS.md","biomeの使い方","biomeのインストールガイド","AIエージェントツール"],"ko":["AI 에이전트","biome","항상 켜진 문서 인덱스","AGENTS.md","biome 사용 방법","biome 설치 가이드","AI 에이전트 도구"],"es":["herramientas de documentación para agentes de inteligencia artificial","documentación para agentes de inteligencia artificial","biome vs otros herramientas de documentación","cómo instalar biome","cómo usar biome para documentación de agentes"],"fr":["outils de documentation pour les agents de l''intelligence artificielle","documentation pour les agents de l''intelligence artificielle","biome vs autres outils de documentation","comment installer biome","comment utiliser biome pour la documentation de l''agent"],"de":["Tools für die Dokumentation von KI-Agents","Dokumentation für KI-Agents","biome vs andere Tools für die Dokumentation","wie installiere ich biome","wie benutze ich biome für die Dokumentation von KI-Agents"],"pt":["como usar Biome","o que é Biome","ferramentas de IA para documentação","alternativas para Biome","Biome vs outras ferramentas","instalar Biome","guia de configuração do Biome"],"ru":["как использовать Biome","что такое Biome","инструменты ИИ для документации","альтернативы Biome","Biome vs другие инструменты","установить Biome","руководство по настройке Biome"],"ar":["كيفية استخدام بيوم","ما هو بيوم","أدوات الذكاء الاصطناعي للتوثيق","بديلات بيوم","بيوم مقابل أدوات أخرى","تثبيت بيوم","دليل إعداد بيوم"]}},"owner":"olavocarvalho","repo":"engrain","repoPath":"olavocarvalho/engrain","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.714Z","topics":[],"category":"community","skillMd":{"name":"biome","description":"Biome - Fast all-in-one toolchain for web projects (linter + formatter in Rust, 100x faster than ESLint)","version":"1.0.0","tags":"","bodyPreview":"# Biome - Fast All-in-One Toolchain\n\n## Overview\n\nBiome is a fast, all-in-one toolchain for web projects written in Rust. It replaces both ESLint and Prettier with a single tool that''s 100x faster and provides zero-config defaults.\n\n**Key Features**:\n- Single tool for linting and formatting\n- 100x faster than ESLint\n- Zero configuration by default\n- Built-in import sorting\n- TypeScript-first design\n- Partial Prettier compatibility\n- Native monorepo support\n- VS Code integration\n\n**Installation**","body":"# Biome - Fast All-in-One Toolchain\n\n## Overview\n\nBiome is a fast, all-in-one toolchain for web projects written in Rust. It replaces both ESLint and Prettier with a single tool that''s 100x faster and provides zero-config defaults.\n\n**Key Features**:\n- Single tool for linting and formatting\n- 100x faster than ESLint\n- Zero configuration by default\n- Built-in import sorting\n- TypeScript-first design\n- Partial Prettier compatibility\n- Native monorepo support\n- VS Code integration\n\n**Installation**:\n```bash\nnpm install --save-dev @biomejs/biome\n```\n\n## Quick Start\n\n### 1. Initialize Biome\n\n```bash\n# Create biome.json configuration\nnpx @biomejs/biome init\n\n# Check your project\nnpx @biomejs/biome check .\n\n# Fix issues automatically\nnpx @biomejs/biome check --write .\n\n# Format only\nnpx @biomejs/biome format --write .\n\n# Lint only\nnpx @biomejs/biome lint .\n```\n\n### 2. Package.json Scripts\n\n```json\n{\n  \"scripts\": {\n    \"check\": \"biome check .\",\n    \"check:write\": \"biome check --write .\",\n    \"format\": \"biome format --write .\",\n    \"lint\": \"biome lint .\",\n    \"lint:fix\": \"biome lint --write .\"\n  }\n}\n```\n\n### 3. Basic Configuration\n\n```json\n{\n  \"$schema\": \"https://biomejs.dev/schemas/1.9.4/schema.json\",\n  \"vcs\": {\n    \"enabled\": true,\n    \"clientKind\": \"git\",\n    \"useIgnoreFile\": true\n  },\n  \"files\": {\n    \"ignoreUnknown\": false,\n    \"ignore\": [\"node_modules\", \"dist\", \"build\", \".next\"]\n  },\n  \"formatter\": {\n    \"enabled\": true,\n    \"indentStyle\": \"space\",\n    \"indentWidth\": 2,\n    \"lineWidth\": 100\n  },\n  \"linter\": {\n    \"enabled\": true,\n    \"rules\": {\n      \"recommended\": true\n    }\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"quoteStyle\": \"single\",\n      \"semicolons\": \"asNeeded\",\n      \"trailingCommas\": \"all\"\n    }\n  }\n}\n```\n\n## Core Commands\n\n### Check Command (Recommended)\n\nThe `check` command runs both linting and formatting:\n\n```bash\n# Check all files\nbiome check .\n\n# Fix issues automatically\nbiome check --write .\n\n# Unsafe fixes (may change behavior)\nbiome check --write --unsafe .\n\n# Apply suggested fixes\nbiome check --write --unsafe --apply-suggested\n\n# Check specific files\nbiome check src/**/*.ts\n\n# CI mode (exit with error on issues)\nbiome ci .\n```\n\n### Format Command\n\nFormat code without linting:\n\n```bash\n# Format all files\nbiome format --write .\n\n# Check formatting without changing files\nbiome format .\n\n# Format specific files\nbiome format --write src/**/*.{ts,tsx,js,jsx}\n\n# Format stdin\necho \"const x={a:1}\" | biome format --stdin-file-path=file.js\n```\n\n### Lint Command\n\nLint code without formatting:\n\n```bash\n# Lint all files\nbiome lint .\n\n# Fix linting issues\nbiome lint --write .\n\n# Show rule names\nbiome lint --verbose .\n\n# Apply unsafe fixes\nbiome lint --write --unsafe .\n```\n\n## Configuration Deep Dive\n\n### Formatter Configuration\n\n```json\n{\n  \"formatter\": {\n    \"enabled\": true,\n    \"formatWithErrors\": false,\n    \"indentStyle\": \"space\",\n    \"indentWidth\": 2,\n    \"lineEnding\": \"lf\",\n    \"lineWidth\": 80,\n    \"attributePosition\": \"auto\"\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"quoteStyle\": \"single\",\n      \"jsxQuoteStyle\": \"double\",\n      \"quoteProperties\": \"asNeeded\",\n      \"trailingCommas\": \"all\",\n      \"semicolons\": \"asNeeded\",\n      \"arrowParentheses\": \"always\",\n      \"bracketSpacing\": true,\n      \"bracketSameLine\": false\n    }\n  },\n  \"json\": {\n    \"formatter\": {\n      \"trailingCommas\": \"none\"\n    }\n  }\n}\n```\n\n### Linter Configuration\n\n```json\n{\n  \"linter\": {\n    \"enabled\": true,\n    \"rules\": {\n      \"recommended\": true,\n      \"a11y\": {\n        \"recommended\": true,\n        \"noAutofocus\": \"error\",\n        \"useKeyWithClickEvents\": \"warn\"\n      },\n      \"complexity\": {\n        \"recommended\": true,\n        \"noForEach\": \"off\",\n        \"useLiteralKeys\": \"error\"\n      },\n      \"correctness\": {\n        \"recommended\": true,\n        \"noUnusedVariables\": \"error\",\n        \"useExhaustiveDependencies\": \"warn\"\n      },\n      \"performance\": {\n        \"recommended\": true,\n        \"noAccumulatingSpread\": \"warn\"\n      },\n      \"security\": {\n        \"recommended\": true,\n        \"noDangerouslySetInnerHtml\": \"error\"\n      },\n      \"style\": {\n        \"recommended\": true,\n        \"noNonNullAssertion\": \"warn\",\n        \"useConst\": \"error\",\n        \"useTemplate\": \"warn\"\n      },\n      \"suspicious\": {\n        \"recommended\": true,\n        \"noExplicitAny\": \"warn\",\n        \"noArrayIndexKey\": \"error\"\n      }\n    }\n  }\n}\n```\n\n### File Ignore Patterns\n\n```json\n{\n  \"files\": {\n    \"ignore\": [\n      \"node_modules\",\n      \"dist\",\n      \"build\",\n      \".next\",\n      \"coverage\",\n      \"*.min.js\",\n      \"public/assets/**\"\n    ],\n    \"ignoreUnknown\": false,\n    \"include\": [\"src/**/*.ts\", \"src/**/*.tsx\"]\n  }\n}\n```\n\n### Override Configuration for Specific Files\n\n```json\n{\n  \"overrides\": [\n    {\n      \"include\": [\"**/*.test.ts\", \"**/*.spec.ts\"],\n      \"linter\": {\n        \"rules\": {\n          \"suspicious\": {\n            \"noExplicitAny\": \"off\"\n          }\n        }\n      }\n    },\n    {\n      \"include\": [\"scripts/**/*.js\"],\n      \"formatter\": {\n        \"lineWidth\": 120\n      }\n    }\n  ]\n}\n```\n\n## VS Code Integration\n\n### 1. Install Biome Extension\n\n```bash\n# Install from VS Code marketplace\ncode --install-extension biomejs.biome\n```\n\n### 2. VS Code Settings (`.vscode/settings.json`)\n\n```json\n{\n  \"[javascript]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true,\n    \"editor.codeActionsOnSave\": {\n      \"quickfix.biome\": \"explicit\",\n      \"source.organizeImports.biome\": \"explicit\"\n    }\n  },\n  \"[typescript]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true,\n    \"editor.codeActionsOnSave\": {\n      \"quickfix.biome\": \"explicit\",\n      \"source.organizeImports.biome\": \"explicit\"\n    }\n  },\n  \"[typescriptreact]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true\n  },\n  \"[json]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true\n  },\n  \"biome.lspBin\": \"./node_modules/@biomejs/biome/bin/biome\"\n}\n```\n\n### 3. Workspace Settings\n\n```json\n{\n  \"editor.formatOnSave\": true,\n  \"editor.formatOnPaste\": true,\n  \"editor.defaultFormatter\": \"biomejs.biome\",\n  \"biome.rename\": true,\n  \"files.autoSave\": \"onFocusChange\"\n}\n```\n\n## Migration from ESLint and Prettier\n\n### 1. Remove Old Tools\n\n```bash\n# Remove ESLint and Prettier\nnpm uninstall eslint prettier eslint-config-prettier \\\n  eslint-plugin-react eslint-plugin-import \\\n  @typescript-eslint/parser @typescript-eslint/eslint-plugin\n\n# Remove configuration files\nrm .eslintrc.js .eslintrc.json .prettierrc .prettierignore\n```\n\n### 2. Migrate Configuration\n\nUse Biome''s migration tool:\n\n```bash\n# Migrate from Prettier config\nbiome migrate prettier --write\n\n# Migrate from ESLint config\nbiome migrate eslint --write\n```\n\n### 3. Manual Migration\n\n**Prettier → Biome Formatter**:\n\n```json\n// .prettierrc (old)\n{\n  \"semi\": false,\n  \"singleQuote\": true,\n  \"trailingComma\": \"all\",\n  \"printWidth\": 100\n}\n\n// biome.json (new)\n{\n  \"formatter\": {\n    \"lineWidth\": 100\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"semicolons\": \"asNeeded\",\n      \"quoteStyle\": \"single\",\n      \"trailingCommas\": \"all\"\n    }\n  }\n}\n```\n\n**ESLint → Biome Linter**:\n\n```json\n// .eslintrc.json (old)\n{\n  \"rules\": {\n    \"no-unused-vars\": \"error\",\n    \"prefer-const\": \"warn\"\n  }\n}\n\n// biome.json (new)\n{\n  \"linter\": {\n    \"rules\": {\n      \"correctness\": {\n        \"noUnusedVariables\": \"error\"\n      },\n      \"style\": {\n        \"useConst\": \"warn\"\n      }\n    }\n  }\n}\n```\n\n### 4. Update Scripts\n\n```json\n{\n  \"scripts\": {\n    \"lint\": \"biome lint .\",\n    \"lint:fix\": \"biome lint --write .\",\n    \"format\": \"biome format --write .\",\n    \"check\": \"biome check --write .\"\n  }\n}\n```\n\n## Git Hooks Integration\n\n### Using Husky + lint-staged\n\n```bash\n# Install dependencies\nnpm install --save-dev husky lint-staged\nnpx husky init\n```\n\n**`.husky/pre-commit`**:\n```bash\n#!/usr/bin/env sh\n. \"$(dirname -- \"$0\")/_/husky.sh\"\n\nnpx lint-staged\n```\n\n**`package.json`**:\n```json\n{\n  \"lint-staged\": {\n    \"*.{js,ts,jsx,tsx,json}\": [\n      \"biome check --write --no-errors-on-unmatched\"\n    ]\n  }\n}\n```\n\n### Using Lefthook\n\n**`lefthook.yml`**:\n```yaml\npre-commit:\n  commands:\n    lint:\n      glob: \"*.{js,ts,jsx,tsx,json}\"\n      run: biome check --write --no-errors-on-unmatched {staged_files}\n```\n\n### Simple Git Hook (no dependencies)\n\n**`.git/hooks/pre-commit`**:\n```bash\n#!/bin/bash\n\n# Get staged files\nSTAGED_FILES=$(git diff --cached --name-only --diff-filter=ACM | grep -E ''\\.(js|ts|jsx|tsx|json)$'')\n\nif [ -n \"$STAGED_FILES\" ]; then\n  echo \"Running Biome on staged files...\"\n  npx @biomejs/biome check --write --no-errors-on-unmatched $STAGED_FILES\n\n  # Add formatted files back to staging\n  git add $STAGED_FILES\nfi\n```\n\n## CI/CD Integration\n\n### GitHub Actions\n\n```yaml\nname: Biome CI\n\non:\n  push:\n    branches: [main, develop]\n  pull_request:\n    branches: [main]\n\njobs:\n  biome:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Setup Node.js\n        uses: actions/setup-node@v4\n        with:\n          node-version: ''20''\n          cache: ''npm''\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Run Biome CI\n        run: npx @biomejs/biome ci .\n\n      - name: Check formatting\n        run: npx @biomejs/biome format .\n\n      - name: Lint\n        run: npx @biomejs/biome lint .\n```\n\n### GitLab CI\n\n```yaml\nbiome:\n  image: node:20-alpine\n  stage: test\n  script:\n    - npm ci\n    - npx @biomejs/biome ci .\n  cache:\n    paths:\n      - node_modules/\n  only:\n    - merge_requests\n    - main\n```\n\n### CircleCI\n\n```yaml\nversion: 2.1\n\njobs:\n  biome:\n    docker:\n      - image: cimg/node:20.11\n    steps:\n      - checkout\n      - restore_cache:\n          keys:\n            - deps-{{ checksum \"package-lock.json\" }}\n      - run: npm ci\n      - save_cache:\n          paths:\n            - node_modules\n          key: deps-{{ checksum \"package-lock.json\" }}\n      - run: npx @biomejs/biome ci .\n\nworkflows:\n  test:\n    jobs:\n      - biome\n```\n\n## Import Sorting\n\nBiome includes built-in import sorting:\n\n```bash\n# Organize imports\nbiome check --write --organize-imports-enabled=true .\n```\n\n**Configuration**:\n```json\n{\n  \"organizeImports\": {\n    \"enabled\": true\n  }\n}\n```\n\n**Example**:\n```typescript\n// Before\nimport { useState } from ''react'';\nimport axios from ''axios'';\nimport { Button } from ''./components/Button'';\nimport type { User } from ''./types'';\nimport ''./styles.css'';\n\n// After (sorted)\nimport type { User } from ''./types'';\n\nimport axios from ''axios'';\nimport { useState } from ''react'';\n\nimport { Button } from ''./components/Button'';\n\nimport ''./styles.css'';\n```\n\n## TypeScript Support\n\nBiome has first-class TypeScript support:\n\n```json\n{\n  \"linter\": {\n    \"rules\": {\n      \"suspicious\": {\n        \"noExplicitAny\": \"warn\",\n        \"noUnsafeDeclarationMerging\": \"error\"\n      },\n      \"correctness\": {\n        \"noUnusedVariables\": \"error\"\n      },\n      \"style\": {\n        \"useImportType\": \"error\",\n        \"useExportType\": \"error\"\n      }\n    }\n  }\n}\n```\n\n**Type-aware linting**:\n```typescript\n// Biome detects unused variables\nconst unused = 123; // ❌ Error\n\n// Enforces type imports\nimport { User } from ''./types''; // ❌ Error\nimport type { User } from ''./types''; // ✅ Correct\n\n// Detects unsafe type assertions\nconst num = \"123\" as any as number; // ⚠️ Warning\n```\n\n## Monorepo Support\n\nBiome works great in monorepos:\n\n### Project Structure\n```\nmy-monorepo/\n├── biome.json (root config)\n├── packages/\n│   ├── web/\n│   │   └── biome.json (extends root)\n│   ├── api/\n│   │   └── biome.json\n│   └── shared/\n│       └── biome.json\n```\n\n### Root Configuration\n```json\n{\n  \"$schema\": \"https://biomejs.dev/schemas/1.9.4/schema.json\",\n  \"extends\": [],\n  \"formatter\": {\n    \"enabled\": true,\n    \"indentStyle\": \"space\",\n    \"indentWidth\": 2\n  },\n  \"linter\": {\n    \"enabled\": true,\n    \"rules\": {\n      \"recommended\": true\n    }\n  }\n}\n```\n\n### Package Override\n```json\n{\n  \"extends\": [\"../../biome.json\"],\n  \"formatter\": {\n    \"lineWidth\": 100\n  },\n  \"linter\": {\n    \"rules\": {\n      \"style\": {\n        \"noNonNullAssertion\": \"off\"\n      }\n    }\n  }\n}\n```\n\n### Monorepo Scripts\n```json\n{\n  \"scripts\": {\n    \"check\": \"biome check .\",\n    \"check:packages\": \"biome check packages/*\",\n    \"format\": \"biome format --write .\",\n    \"lint\": \"biome lint packages/*\"\n  }\n}\n```\n\n## Performance Benefits\n\n### Speed Comparison\n\n| Tool | Time (10,000 files) |\n|------|---------------------|\n| ESLint + Prettier | ~60s |\n| Biome | ~0.6s |\n\n**100x faster** on average workloads.\n\n### Caching\n\nBiome includes intelligent caching:\n\n```bash\n# First run (no cache)\nbiome check .  # 1.2s\n\n# Second run (with cache)\nbiome check .  # 0.1s\n\n# Clear cache\nrm -rf node_modules/.cache/biome\n```\n\n### Parallel Processing\n\nBiome uses all CPU cores by default:\n\n```bash\n# Limit CPU cores\nbiome check --max-diagnostics=50 .\n\n# Verbose output\nbiome check --verbose .\n```\n\n## Common Patterns\n\n### React Projects\n\n```json\n{\n  \"linter\": {\n    \"rules\": {\n      \"a11y\": {\n        \"recommended\": true,\n        \"useButtonType\": \"error\",\n        \"useKeyWithClickEvents\": \"error\"\n      },\n      \"correctness\": {\n        \"useExhaustiveDependencies\": \"warn\",\n        \"useHookAtTopLevel\": \"error\"\n      },\n      \"suspicious\": {\n        \"noArrayIndexKey\": \"error\"\n      }\n    }\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"jsxQuoteStyle\": \"double\"\n    }\n  }\n}\n```\n\n### Next.js Projects\n\n```json\n{\n  \"files\": {\n    \"ignore\": [\".next\", \"out\", \"node_modules\"]\n  },\n  \"overrides\": [\n    {\n      \"include\": [\"app/**/*.tsx\", \"pages/**/*.tsx\"],\n      \"linter\": {\n        \"rules\": {\n          \"a11y\": {\n            \"recommended\": true\n          }\n        }\n      }\n    }\n  ]\n}\n```\n\n### Node.js Backend\n\n```json\n{\n  \"linter\": {\n    \"rules\": {\n      \"security\": {\n        \"recommended\": true,\n        \"noGlobalEval\": \"error\"\n      },\n      \"correctness\": {\n        \"noUnusedVariables\": \"error\"\n      }\n    }\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"semicolons\": \"always\"\n    }\n  }\n}\n```\n\n## Best Practices\n\n1. **Use `biome check`** instead of separate format/lint commands\n2. **Enable `--write`** flag for automatic fixes\n3. **Configure VS Code** for format-on-save\n4. **Add git hooks** to enforce quality before commits\n5. **Use CI mode** (`biome ci`) in continuous integration\n6. **Start with recommended rules** then customize\n7. **Leverage import sorting** to organize imports automatically\n8. **Use overrides** for different file types or directories\n9. **Enable VCS integration** to respect .gitignore\n10. **Keep configuration minimal** - Biome has smart defaults\n\n## Troubleshooting\n\n### Biome Not Formatting\n\n```bash\n# Check if formatter is enabled\nbiome rage\n\n# Verify file is not ignored\nbiome check --verbose src/file.ts\n\n# Check VS Code extension logs\n# View → Output → Biome\n```\n\n### Conflicts with Prettier\n\n```bash\n# Disable Prettier in VS Code settings\n\"[javascript]\": {\n  \"editor.defaultFormatter\": \"biomejs.biome\"\n}\n\n# Remove Prettier dependencies\nnpm uninstall prettier\n```\n\n### Performance Issues\n\n```bash\n# Check cache location\nbiome rage\n\n# Clear cache\nrm -rf node_modules/.cache/biome\n\n# Reduce max diagnostics\nbiome check --max-diagnostics=20 .\n```\n\n### Rule Configuration Not Working\n\n```json\n// Ensure correct category\n{\n  \"linter\": {\n    \"rules\": {\n      \"correctness\": {  // Category name matters\n        \"noUnusedVariables\": \"error\"\n      }\n    }\n  }\n}\n```\n\n## Local Biome Configs (Your Repos)\n\nPatterns from active projects:\n\n- `ai-code-review/biome.json`: `files.includes` targets `src/**/*.ts` and excludes tests, `lineWidth: 100`, single quotes, semicolons always, and `noExplicitAny: warn`.\n- `itinerizer-ts/biome.json`: `files.ignore` includes `node_modules`, `dist`, `.claude`, and data directories; `organizeImports.enabled = true`.\n- `matsuoka-com` and `diogenes` use similar formatting defaults (2-space indent, lineWidth 100).\n\nCommon scripts:\n\n```json\n{\n  \"lint\": \"biome check src/ --diagnostic-level=error\",\n  \"lint:fix\": \"biome check src/ --write\",\n  \"format\": \"biome format src/ --write\"\n}\n```\n\n## Resources\n\n- **Official Docs**: https://biomejs.dev\n- **VS Code Extension**: https://marketplace.visualstudio.com/items?itemName=biomejs.biome\n- **GitHub**: https://github.com/biomejs/biome\n- **Rules Reference**: https://biomejs.dev/linter/rules/\n- **Migration Guide**: https://biomejs.dev/guides/migrate-eslint-prettier/\n\n## Summary\n\n- **Biome** is a fast all-in-one linter and formatter\n- **100x faster** than ESLint + Prettier\n- **Zero config** by default with smart defaults\n- **Built in Rust** for maximum performance\n- **TypeScript-first** with excellent type support\n- **Import sorting** included out of the box\n- **VS Code integration** with official extension\n- **Perfect for** modern web projects, monorepos, CI/CD\n- **Easy migration** from ESLint and Prettier\n"},"lastSynced":"2026-03-04T13:46:31.948Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing rapid linting and formatting for web projects written in Rust.","zh":"适合需要快速linting和格式化的Rust web项目代码分析Agent","ja":"Rustで書かれたwebプロジェクトのコード分析エージェントに適しています","ko":"Rust로 작성된 웹 프로젝트의 코드 분석 에이전트에 적합합니다","es":"Perfecto para agentes de análisis de código que necesitan una revisión y formato rápidos para proyectos web escritos en Rust.","fr":"Parfait pour les agents d''analyse de code nécessitant une analyse et un formatage rapides pour les projets web écrits en Rust.","de":"Perfekt für Code-Analyse-Agenten, die ein schnelles Linting und Formatieren für Webprojekte in Rust benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de linting e formatação rápidos para projetos web escritos em Rust.","ru":"Идеально подходит для Агентов Анализа Кодов, которым требуется быстрое выравнивание и форматирование для веб-проектов, написанных на Rust.","ar":" مثالي لعمليات تحليل الشفرة التي تحتاج إلى تنسيق سريع وتنسيق للمشاريع الإلكترونية المكتوبة بلغة Rust."},"recommendation":{"en":"Empowers agents to unify linting and formatting with zero-config defaults, leveraging native monorepo support and partial Prettier compatibility, while integrating seamlessly with VS Code for enhanced development workflows.","zh":"赋予代理统一linting和格式化，具有零配置默认值，利用本地monorepo支持和部分Prettier兼容性，同时与VS Code无缝集成以增强开发工作流","ja":"エージェントに linting とフォーマットを統一し、ゼロコンフィグ デフォルト値、ネイティブ monorepo サポート、部分 Prettier 互換性を活用し、VS Code と無縫に統合して開発ワークフローを強化します","ko":"에이전트에게 linting과 형식을統一하고, 기본값을 설정하지 않고, monorepo를 지원하고, 부분 Prettier와 호환되며, VS Code와 통합하여 개발 워크를 강화합니다","es":"Habilita a los agentes a unificar la revisión y el formato con valores predeterminados de configuración cero, aprovechando el soporte nativo de monorepo y la compatibilidad parcial con Prettier, mientras se integra de forma transparente con VS Code para flujos de trabajo de desarrollo mejorados.","fr":"Permet aux agents d''unifier la vérification et le formatage avec des valeurs par défaut de configuration zéro, en exploitant le support natif de monorepo et la compatibilité partielle avec Prettier, tout en s''intégrant de manière transparente avec VS Code pour des flux de travail de développement améliorés.","de":"Ermächtigt Agenten, Linting und Formatierung mit null-Konfigurationsstandardwerten zu vereinen, native Monorepo-Unterstützung und teilweise Prettier-Kompatibilität zu nutzen und sich nahtlos in VS Code für verbesserte Entwicklungsworkflows zu integrieren.","pt":"Habilita os agentes a unificar o linting e a formatação com configurações padrão zero, aproveitando o suporte nativo de monorepo e a compatibilidade parcial com o Prettier, enquanto se integra perfeitamente com o VS Code para fluxos de trabalho de desenvolvimento aprimorados.","ru":"Наделяет агентов возможностью объединить выравнивание и форматирование с настройками по умолчанию zero, используя родную поддержку monorepo и частичную совместимость с Prettier, а также бесшовно интегрируется с VS Code для улучшения рабочих процессов разработки.","ar":"تمكين الوكلاء من توحيد التنسيق والتنسيق مع إعدادات افتراضية صفر، مستفيدة من الدعم الأصلي ل monorepo والتوافق الجزئي مع Prettier، في حين يتم دمجها بشكل مثالي مع VS Code لتحسين سير عمل التطوير."},"useCases":{"en":["Streamlining ESLint and Prettier workflows","Automating import sorting for TypeScript projects","Optimizing code formatting for Rust-based web applications"],"zh":["简化ESLint和Prettier工作流","为TypeScript项目自动排序导入","优化Rust-based web应用的代码格式化"],"ja":["ESLintとPrettierのワークフローを簡化する","TypeScriptプロジェクトのインポートを自動的に並べ替える","RustベースのWebアプリケーションのコードフォーマットを最適化する"],"ko":["ESLint와 Prettier의 워크를簡化합니다","TypeScript 프로젝트의导入를 자동으로 정렬합니다","Rust 기반의 웹 애플리케이션의 코드 형식을 최적화합니다"],"es":["Optimizar los flujos de trabajo de ESLint y Prettier","Automatizar la clasificación de importaciones para proyectos de TypeScript","Optimizar el formato de código para aplicaciones web basadas en Rust"],"fr":["Optimiser les flux de travail ESLint et Prettier","Automatiser le tri des importations pour les projets TypeScript","Optimiser le formatage de code pour les applications web basées sur Rust"],"de":["ESLint- und Prettier-Workflows zu optimieren","Automatisieren von Importsortierung für TypeScript-Projekte","Optimieren des Code-Formatierens für Rust-basierte Webanwendungen"],"pt":["Otimizando fluxos de trabalho do ESLint e Prettier","Automatizando a ordenação de importações para projetos TypeScript","Otimizando a formatação de código para aplicações web baseadas em Rust"],"ru":["Оптимизация рабочих процессов ESLint и Prettier","Автоматизация сортировки импортов для проектов TypeScript","Оптимизация форматирования кода для веб-приложений на основе Rust"],"ar":["تحسين سير عمل ESLint و Prettier","تأتمتة ترتيب الاستيراد لمشاريع TypeScript","تحسين تنسيق الشفرة لتطبيقات الويب المبنية على Rust"]},"limitations":{"en":["Requires Rust installation","Limited to web projects","Partial compatibility with Prettier"],"zh":["需要Rust安装","仅限于web项目","部分兼容性Prettier"],"ja":["Rustのインストールが必要です","Webプロジェクトのみに制限されます","部分 Prettier 互換性"],"ko":["Rust 설치가 필요합니다","웹 프로젝트에만 제한됩니다","부분 Prettier 호환성"],"es":["Requiere instalación de Rust","Limitado a proyectos web","Compatibilidad parcial con Prettier"],"fr":["Nécessite l''installation de Rust","Limité aux projets web","Compatibilité partielle avec Prettier"],"de":["Benötigt Rust-Installation","Begrenzt auf Webprojekte","Teilweise Kompatibilität mit Prettier"],"pt":["Requer instalação do Rust","Limitado a projetos web","Compatibilidade parcial com o Prettier"],"ru":["Требуется установка Rust","Ограничен для веб-проектов","Частичная совместимость с Prettier"],"ar":["يتطلب تثبيت Rust","محدود لمشاريع الويب","التوافق الجزئي مع Prettier"]},"version":3},"contentHash":"9c1ebccf003c106d060a43d19ac819a0cece9badc9b7e5cb8354dc6e47b7f59f","qualityScore":45}');
