INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('larrykoo711/new-macos-starter/macos-setup', 'macos-setup', 'larrykoo711', 'new-macos-starter', 'community', 'macos-setup larrykoo711 new-macos-starter community macOS开发环境搭建指南，涵盖Homebrew、Zsh、Node.js、Python、Go、Docker、Kubernetes等工具 macOS開発環境のセットアップガイド。Homebrew、Zsh、Node.js、Python、Go、Docker、Kubernetesなどを含む macOS 개발 환경 설정 가이드. Homebrew, Zsh, Node.js, Python, Go, Docker, Kubernetes 등을 포함 Configuración de entorno de desarrollo macOS para ingenieros con Homebrew, Zsh, Node.js, Python, Go, Docker y Kubernetes. Configuration de l''environnement de développement macOS pour les ingénieurs avec Homebrew, Zsh, Node.js, Python, Go, Docker et Kubernetes. Einrichtung der macOS-Entwicklungsumgebung für Ingenieure mit Homebrew, Zsh, Node.js, Python, Go, Docker und Kubernetes. Guia de configuração de ambiente de desenvolvimento macOS para engenheiros, com ferramentas como Homebrew, Zsh e Node.js. Руководство по настройке среды разработки macOS для инженеров, с инструментами seperti Homebrew, Zsh и Node.js. دليل إعداد بيئة تطوير macOS للمهندسين، مع أدوات مثل Homebrew و Zsh و Node.js. From Zero to Hero — An opinionated macOS development environment setup guide for engineers. Homebrew, Zsh, Node.js, Python, Go, Docker, Kubernetes, and more. macOS开发环境搭建 AI智能工具 Homebrew安装 Zsh shell配置 Node.js安装 Python开发环境 Go语言开发 Docker容器化 Kubernetes集群管理 From Zero to Hero — An opinionated macOS development environment setup guide for engineers. Homebrew, Zsh, Node.js, Python, Go, Docker, Kubernetes, and more.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('reubenjohn/reeve-bot/plan-with-subagents', 'community', 'reubenjohn', 'reeve-bot', 'reubenjohn/reeve-bot', 'plan-with-subagents', 0, 0, 45, '2026-03-04T13:07:01.731Z', '2026-03-04T13:59:52.529Z', 'd46f85de4c82f3c6f3bdfe4a95f80ec259343b2967642ddd27ac0cbade8adf96', '{"id":"reubenjohn/reeve-bot/plan-with-subagents","name":"plan-with-subagents","description":{"zh":"Proactive AI Chief of Staff是一种推动式AI助理，预测需求，过滤噪音，管理数字生活","ja":"Proactive AI Chief of Staffは、ニーズを予測し、ノイズを除去し、デジタルライフを管理するプッシュ型AIエージェントです","ko":"Proactive AI Chief of Staff는 요구 사항을 예측하고 노이즈를 필터링하여 디지털 생활을 관리하는 푸시 패러다임 AI 에이전트입니다","es":"Plan-with-subagents es un asistente proactivo que anticipa necesidades y gestiona tu vida digital con automatización inteligente","fr":"Plan-with-subagents est un assistant proactif qui anticipe les besoins et gère votre vie numérique avec une automatisation intelligente","de":"Plan-with-subagents ist ein proaktiver Assistent, der Bedürfnisse antizipiert und Ihr digitales Leben mit intelligenter Automatisierung managt","pt":"O plano com subagentes é uma assistente proativa que antecipa necessidades e gerencia a vida digital através de pulses agendados e automação inteligente","ru":"План с субагентами - это проактивный помощник, который предвидит потребности и управляет цифровой жизнью через запланированные импульсы и интеллектуальную автоматизацию","ar":"تخطيط مع وكلاء فرعيين هو مساعد تنفيذي ذكي يتصرف مسبقًا ويعمل على إدارة الحياة الرقمية من خلال النبضات المجدولة والتحكم الآلي الذكي","en":"Proactive AI Chief of Staff: A push-paradigm assistant that anticipates needs, filters noise, and manages your digital life through scheduled pulses and intelligent automation"},"seo":{"title":{"zh":"AI智能助理计划：推动式AI工具","ja":"AIエージェントを活用した計画：プッシュ型AIツール","ko":"AI 에이전트 계획: 푸시 패러다임 AI 도구","es":"Herramientas de Agentes de IA: plan-with-subagents","fr":"Outils d''Agents d''IA: plan-with-subagents","de":"KI-Agenten-Tools: plan-with-subagents","pt":"Ferramentas de IA: Planeje com Subagentes","ru":"ИИ Агенты: План с субагентами","ar":"أدوات الذكاء الاصطناعي: تخطيط مع وكلاء فرعيين","en":"plan-with-subagents"},"description":{"zh":"Proactive AI Chief of Staff是一种推动式AI助理，预测需求，过滤噪音，管理数字生活","ja":"Proactive AI Chief of Staffは、ニーズを予測し、ノイズを除去し、デジタルライフを管理するプッシュ型AIエージェントです","ko":"Proactive AI Chief of Staff는 요구 사항을 예측하고 노이즈를 필터링하여 디지털 생활을 관리하는 푸시 패러다임 AI 에이전트입니다","es":"Plan-with-subagents es un asistente proactivo que anticipa necesidades y gestiona tu vida digital con automatización inteligente","fr":"Plan-with-subagents est un assistant proactif qui anticipe les besoins et gère votre vie numérique avec une automatisation intelligente","de":"Plan-with-subagents ist ein proaktiver Assistent, der Bedürfnisse antizipiert und Ihr digitales Leben mit intelligenter Automatisierung managt","pt":"O plano com subagentes é uma assistente proativa que antecipa necessidades e gerencia a vida digital através de pulses agendados e automação inteligente","ru":"План с субагентами - это проактивный помощник, который предвидит потребности и управляет цифровой жизнью через запланированные импульсы и интеллектуальную ав...","ar":"تخطيط مع وكلاء فرعيين هو مساعد تنفيذي ذكي يتصرف مسبقًا ويعمل على إدارة الحياة الرقمية من خلال النبضات المجدولة والتحكم الآلي الذكي","en":"Proactive AI Chief of Staff: A push-paradigm assistant that anticipates needs, filters noise, and manages your digital life through scheduled pulses and inte..."},"definition":{"en":"Proactive AI Chief of Staff: A push-paradigm assistant that anticipates needs, filters noise, and manages your digital life through scheduled pulses and intelligent automation"},"features":{"zh":["预测需求","过滤噪音","管理数字生活","scheduled pulses","智能自动化"],"ja":["ニーズを予測","ノイズを除去","デジタルライフを管理","scheduled pulses","智能自動化"],"ko":["요구 사항 예측","노이즈 필터링","디지털 생활 관리","scheduled pulses","智能 자동화"],"es":["Automatización inteligente","Gestión de la vida digital","Asistente proactivo","Integración con herramientas de productividad","Programación de tareas"],"fr":["Automatisation intelligente","Gestion de la vie numérique","Assistant proactif","Intégration avec des outils de productivité","Planification de tâches"],"de":["Intelligente Automatisierung","Management des digitalen Lebens","Proaktiver Assistent","Integration mit Produktivitätstools","Aufgabenplanung"],"pt":["Automação inteligente","Gestão de vida digital","Pulses agendados","Filtração de ruído","Antecipação de necessidades"],"ru":["Интеллектуальная автоматизация","Управление цифровой жизнью","Запланированные импульсы","Фильтрация шума","Предвидение потребностей"],"ar":["التحكم الآلي الذكي","إدارة الحياة الرقمية","النبضات المجدولة","ترشيح الضوضاء","التصرف المسبق"]},"keywords":{"zh":["AI智能助理","推动式AI工具","预测需求","过滤噪音","管理数字生活","如何使用AI智能助理","AI智能助理安装"],"ja":["AIエージェント","プッシュ型AIツール","ニーズを予測","ノイズを除去","デジタルライフを管理","AIエージェントの使い方","AIエージェントのインストール"],"ko":["AI 에이전트","푸시 패러다임 AI 도구","요구 사항 예측","노이즈 필터링","디지털 생활 관리","AI 에이전트 사용 방법","AI 에이전트 설치 가이드"],"es":["cómo usar agentes de IA","herramientas de productividad para desarrolladores","plan-with-subagents alternativa","plan-with-subagents vs asistentes virtuales","instalación de plan-with-subagents","guía de configuración de plan-with-subagents","desarrollo de agentes de IA con Python","integración de agentes de IA con Node.js"],"fr":["comment utiliser les agents d''IA","outils de productivité pour les développeurs","plan-with-subagents alternative","plan-with-subagents vs assistants virtuels","installation de plan-with-subagents","guide de configuration de plan-with-subagents","développement d''agents d''IA avec Python","intégration d''agents d''IA avec Node.js"],"de":["wie man KI-Agenten verwendet","Produktivitätstools für Entwickler","plan-with-subagents Alternative","plan-with-subagents vs virtuelle Assistenten","Installation von plan-with-subagents","Einrichtungsanleitung für plan-with-subagents","Entwicklung von KI-Agenten mit Python","Integration von KI-Agenten mit Node.js"],"pt":["como usar ferramentas de IA","o que é plano com subagentes","ferramentas de IA para produtividade","plano com subagentes vs outros","instalação de ferramentas de IA","guia de configuração de plano com subagentes"],"ru":["как использовать ИИ Агенты","что такое план с субагентами","инструменты ИИ для производительности","план с субагентами vs другие","установка инструментов ИИ","руководство по настройке плана с субагентами"],"ar":["كيفية استخدام أدوات الذكاء الاصطناعي","ما هو تخطيط مع وكلاء فرعيين","أدوات الذكاء الاصطناعي للتحكم في الوقت","تخطيط مع وكلاء فرعيين مقابل الأخرى","تثبيت أدوات الذكاء الاصطناعي","دليل إعداد تخطيط مع وكلاء فرعيين"]}},"owner":"reubenjohn","repo":"reeve-bot","repoPath":"reubenjohn/reeve-bot","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.731Z","topics":[],"category":"community","skillMd":{"name":"plan-with-subagents","description":"Plan multi-step implementation tasks to minimize context usage and maximize parallelism. Automatically applies whenever plan mode is active.","bodyPreview":"# Plan with Sub-Agents Skill\n\n**These guidelines apply automatically whenever plan mode is active.** Plan mode implies complexity, so always design for parallelism and minimal context.\n\n## Core Principle: Use Sub-Agents Generously\n\nSub-agents are cheap and effective. When in doubt, spawn an agent. Benefits:\n- **Parallel execution** - Multiple agents work simultaneously\n- **Reduced context** - Each agent only sees what it needs\n- **Fault isolation** - One agent''s failure doesn''t block others\n- **","body":"# Plan with Sub-Agents Skill\n\n**These guidelines apply automatically whenever plan mode is active.** Plan mode implies complexity, so always design for parallelism and minimal context.\n\n## Core Principle: Use Sub-Agents Generously\n\nSub-agents are cheap and effective. When in doubt, spawn an agent. Benefits:\n- **Parallel execution** - Multiple agents work simultaneously\n- **Reduced context** - Each agent only sees what it needs\n- **Fault isolation** - One agent''s failure doesn''t block others\n- **Cleaner commits** - Each agent commits its own work\n\n**Default to spawning agents** for:\n- Any exploration or research (use `Explore` agent)\n- Designing approaches (use `Plan` agent)\n- Independent file modifications (use `general-purpose` agents in parallel)\n- Error-prone steps that involve noisy logs (e.g. running tests)\n- Shell operations (use `Bash` agent)\n\n## When Sub-Agents Apply\n\n- Any task in plan mode (plan mode = complexity assumed)\n- Tasks with 4+ distinct steps\n- Work that touches multiple unrelated files\n- Tasks where exploration and execution can be separated\n- Long-running operations that benefit from parallel execution\n\n## Phase Design Principles\n\n### 1. Break by File Independence\n\nGroup work by which files are touched. Phases that modify **different files** can run in parallel.\n\n```\nPhase A: modifies src/api/server.py, src/api/models.py\nPhase B: modifies tests/test_api.py, tests/conftest.py\nPhase C: modifies README.md, docs/API.md\n→ All three can run in parallel\n```\n\n### 2. Identify Sequential Dependencies\n\nSome phases MUST run in order:\n- Phase that creates a file → Phase that references it\n- Phase that changes API → Phase that updates tests for that API\n- Phase that installs deps → Phase that uses those deps\n\n### 3. Minimize Context per Agent\n\nEach sub-agent should receive ONLY the context it needs:\n- Specific file paths to modify\n- Exact changes to make\n- Commit message to use\n\nAvoid passing full project history or unrelated requirements.\n\n## Agent Type Selection\n\n| Task Type | Agent | Why |\n|-----------|-------|-----|\n| Run shell commands (git, gh, npm) | `Bash` | Direct command execution |\n| Find files/patterns in codebase | `Explore` | Optimized for search |\n| Design implementation approach | `Plan` | Architectural thinking |\n| Write/modify code | `general-purpose` | Full tool access |\n| Research questions | `general-purpose` | Web + file access |\n\n## Execution Prompt Template\n\nWhen spawning sub-agents, use this structure:\n\n```\n**Task:** [One sentence describing the goal]\n\n**Files to modify:**\n- path/to/file1.py - [what to change]\n- path/to/file2.py - [what to change]\n\n**Specific changes:**\n1. [Concrete change 1]\n2. [Concrete change 2]\n\n**Commit when done:**\n\"[type]: [description]\"\n```\n\n## Example Plan Structure\n\n```markdown\n## Phase 0: Setup (sequential)\n- Create directory structure\n→ COMMIT: \"chore: Add project scaffolding\"\n\n## Phase 1: Research (sequential)\n- Explore codebase to understand patterns\n- No commit (exploration only)\n\n## Phases 2, 3, 4 (PARALLEL)\nAgent A - Phase 2: Backend changes\n- Modify src/api/*.py\n→ COMMIT: \"feat: Add new endpoint\"\n\nAgent B - Phase 3: Frontend changes\n- Modify src/ui/*.tsx\n→ COMMIT: \"feat: Add UI component\"\n\nAgent C - Phase 4: Documentation\n- Modify docs/*.md\n→ COMMIT: \"docs: Document new feature\"\n\n## Phase 5: Integration (sequential, after 2-4)\n- Update tests that depend on all changes\n→ COMMIT: \"test: Add integration tests\"\n\n## Phase 6: Validation\n- Run tests, linting, type checks\n→ COMMIT only if fixes needed\n```\n\n## Parallelization Checklist\n\nBefore marking phases as parallel, verify:\n\n- [ ] No shared files between parallel phases\n- [ ] No phase reads output from another parallel phase\n- [ ] Each phase can commit independently\n- [ ] Merge conflicts are impossible\n\n## Anti-Patterns\n\n**Don''t:** Create one giant phase with all changes\n**Do:** Split by logical units that can be tested independently\n\n**Don''t:** Pass entire CLAUDE.md to every sub-agent\n**Do:** Extract only relevant sections for each task\n\n**Don''t:** Have parallel phases commit to the same file\n**Do:** Sequence phases that touch shared files\n\n## Commit Strategy\n\nEach phase should commit its own work immediately when done. This provides:\n- Clear git history\n- Easy rollback if one phase fails\n- Parallel agents don''t block each other\n\nUse conventional commit prefixes:\n- `feat:` - New feature\n- `fix:` - Bug fix\n- `chore:` - Maintenance\n- `docs:` - Documentation\n- `test:` - Tests\n- `refactor:` - Code restructuring\n"},"lastSynced":"2026-03-04T13:59:52.529Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced AI Agents like AutoGPT and LangChain needing parallel execution and minimal context for complex planning tasks.","zh":"适用于像 AutoGPT 和 LangChain 这样的高级 AI Agent，需要并行执行和最小化上下文以执行复杂的规划任务。","ja":"AutoGPTやLangChainのような高度なAIエージェントに最適で、複雑な計画タスクを実行するために並行実行と最小のコンテキストが必要です。","ko":"AutoGPT와 LangChain 같은 고급 AI 에이전트에 적합하며, 복잡한 계획 작업을 수행하기 위해 병렬 실행과 최소한의 컨텍스트가 필요합니다.","es":"Ideal para Agentes de IA Avanzados como AutoGPT y LangChain que necesitan ejecución paralela y contexto mínimo para tareas de planificación complejas.","fr":"Idéal pour les agents IA avancés comme AutoGPT et LangChain nécessitant une exécution parallèle et un contexte minimal pour des tâches de planification complexes.","de":"Ideal für fortschrittliche KI-Agents wie AutoGPT und LangChain, die parallele Ausführung und minimalen Kontext für komplexe Planungsaufgaben benötigen.","pt":"Ideal para Agentes de IA Avançados como AutoGPT e LangChain que necessitam de execução paralela e contexto mínimo para tarefas de planejamento complexas.","ru":"Идеально подходит для продвинутых агентов ИИ, таких как AutoGPT и LangChain, требующих параллельного выполнения и минимального контекста для сложных задач планирования.","ar":"مثالي للوكلاء الذكاء الاصطناعي المتقدم مثل AutoGPT و LangChain الذين يحتاجون إلى تنفيذ متوازي وسياق أقل لل مهام التخطيط المعقدة."},"recommendation":{"en":"Empowers agents to execute plans in parallel using sub-agents, reducing context and isolating faults through scheduled pulses and intelligent automation, leveraging benefits like parallel execution and fault isolation.","zh":"赋予代理使用子代理并行执行计划的能力，通过调度的脉冲和智能自动化减少上下文并隔离故障，利用并行执行和故障隔离等优势。","ja":"サブエージェントを使用してプランを並行して実行する能力をエージェントに与え、スケジュールされたパルスと智能自動化を使用してコンテキストを削減し、障害を分離することで、並行実行と障害分離などの利点を活用します。","ko":"서브 에이전트를 사용하여 계획을 병렬로 실행하는 기능을 에이전트에 제공하여, 스케줄된 펄스와智能 자동화를 사용하여 컨텍스트를 줄이고 장애를 분리함으로써, 병렬 실행과 장애 분리 등의 이점을 활용합니다.","es":"Habilita a los agentes a ejecutar planes en paralelo utilizando subagentes, reduciendo el contexto y aislamiento de fallos a través de pulsos programados y automatización inteligente, aprovechando beneficios como la ejecución paralela y el aislamiento de fallos.","fr":"Permet aux agents d''exécuter des plans en parallèle en utilisant des sous-agents, en réduisant le contexte et en isolant les défaillances grâce à des impulsions planifiées et à une automatisation intelligente, en exploitant des avantages tels que l''exécution parallèle et l''isolement des défaillances.","de":"Ermächtigt Agents, Pläne parallel mithilfe von Subagenten auszuführen, reduziert den Kontext und isoliert Fehler durch geplante Impulse und intelligente Automatisierung, nutzt Vorteile wie parallele Ausführung und Fehlertrennung.","pt":"Habilita os agentes a executar planos em paralelo usando sub-agentes, reduzindo o contexto e isolando falhas por meio de pulsos agendados e automação inteligente, aproveitando benefícios como execução paralela e isolamento de falhas.","ru":"Наделяет агентов возможностью выполнять планы параллельно с помощью субагентов, уменьшая контекст и изолируя неисправности посредством запланированных импульсов и интеллектуальной автоматизации, используя преимущества, такие как параллельное выполнение и изоляция неисправностей.","ar":"يمنح الوكلاء القدرة على تنفيذ الخطط بالتوازي باستخدام وكلاء فرعيين، وتقليل السياق و عزل الأعطال من خلال نبضات محجوزة وآليّة ذكاء اصطناعي، واستغلال الفوائد مثل التنفيذ المتوازي وعزل الأعطال."},"useCases":{"en":["Automating complex workflows with multiple sub-agents","Generating plans with reduced context for improved efficiency","Debugging plan failures through fault isolation"],"zh":["使用多个子代理自动执行复杂的工作流程","生成具有降低的上下文以提高效率的计划","通过故障隔离调试计划故障"],"ja":["複数のサブエージェントを使用して複雑なワークフローを自動化する","コンテキストを削減して効率を向上させるプランを生成する","障害分離を使用してプランの障害をデバッグする"],"ko":["여러개의 서브 에이전트를 사용하여 복잡한 워크플로우를 자동화하는 것","컨텍스트를 줄여 효율성을 개선하는 계획을 생성하는 것","장애 분리를 사용하여 계획의 장애를 디버깅하는 것"],"es":["Automatización de flujos de trabajo complejos con múltiples subagentes","Generación de planes con contexto reducido para mejorar la eficiencia","Depuración de fallos de planificación a través del aislamiento de fallos"],"fr":["Automatisation de flux de travail complexes avec plusieurs sous-agents","Génération de plans avec un contexte réduit pour améliorer l''efficacité","Débogage des défaillances de planification grâce à l''isolement des défaillances"],"de":["Automatisierung komplexer Workflows mit mehreren Subagenten","Erstellung von Plänen mit reduziertem Kontext für verbesserte Effizienz","Fehlerbehebung bei Planungsfehlern durch Fehlertrennung"],"pt":["Automatizar fluxos de trabalho complexos com vários sub-agentes","Gerar planos com contexto reduzido para melhoria da eficiência","Depurar falhas de plano por meio do isolamento de falhas"],"ru":["Автоматизация сложных рабочих процессов с несколькими субагентами","Генерация планов с уменьшенным контекстом для повышения эффективности","Отладка сбоев плана посредством изоляции неисправностей"],"ar":["أتمتة سلاسل العمل المعقدة مع العديد من الوكلاء الفرعيين","генерация خطط مع سياق مخفض لتحسين الكفاءة","تصحيح أخطاء الخطة من خلال عزل الأعطال"]},"limitations":{"en":["Requires design for parallelism","Plan mode must be active"],"zh":["需要为并行性设计","计划模式必须处于活动状态"],"ja":["並行性を設計する必要がある","プランモードがアクティブである必要がある"],"ko":["병렬성을 설계해야 하는 것","계획 모드가 활성화되어 있어야 하는 것"],"es":["Requiere diseño para paralelismo","El modo de planificación debe estar activo"],"fr":["Nécessite une conception pour le parallélisme","Le mode de planification doit être actif"],"de":["Erfordert Entwurf für Parallelismus","Der Planmodus muss aktiv sein"],"pt":["Requer design para paralelismo","Modo de plano deve estar ativo"],"ru":["Требуется проектирование для параллелизма","Режим плана должен быть активным"],"ar":["يتطلب تصميم للتوازي","يجب أن يكون وضع الخطة نشط"]},"version":3},"contentHash":"d46f85de4c82f3c6f3bdfe4a95f80ec259343b2967642ddd27ac0cbade8adf96","qualityScore":45}');
