INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('reubenjohn/reeve-bot/plan-with-subagents', 'plan-with-subagents', 'reubenjohn', 'reeve-bot', 'community', 'plan-with-subagents reubenjohn reeve-bot community Proactive AI Chief of Staff是一种推动式AI助理，预测需求，过滤噪音，管理数字生活 Proactive AI Chief of Staffは、ニーズを予測し、ノイズを除去し、デジタルライフを管理するプッシュ型AIエージェントです Proactive AI Chief of Staff는 요구 사항을 예측하고 노이즈를 필터링하여 디지털 생활을 관리하는 푸시 패러다임 AI 에이전트입니다 Plan-with-subagents es un asistente proactivo que anticipa necesidades y gestiona tu vida digital con automatización inteligente Plan-with-subagents est un assistant proactif qui anticipe les besoins et gère votre vie numérique avec une automatisation intelligente Plan-with-subagents ist ein proaktiver Assistent, der Bedürfnisse antizipiert und Ihr digitales Leben mit intelligenter Automatisierung managt O plano com subagentes é uma assistente proativa que antecipa necessidades e gerencia a vida digital através de pulses agendados e automação inteligente План с субагентами - это проактивный помощник, который предвидит потребности и управляет цифровой жизнью через запланированные импульсы и интеллектуальную автоматизацию تخطيط مع وكلاء فرعيين هو مساعد تنفيذي ذكي يتصرف مسبقًا ويعمل على إدارة الحياة الرقمية من خلال النبضات المجدولة والتحكم الآلي الذكي Proactive AI Chief of Staff: A push-paradigm assistant that anticipates needs, filters noise, and manages your digital life through scheduled pulses and intelligent automation AI智能助理 推动式AI工具 预测需求 过滤噪音 管理数字生活 如何使用AI智能助理 AI智能助理安装 Proactive AI Chief of Staff: A push-paradigm assistant that anticipates needs, filters noise, and manages your digital life through scheduled pulses and intelligent automation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yitongcodes/weibo_trends_analyzer_web/weibo-trends-analyzer', 'community', 'yitongcodes', 'weibo_trends_analyzer_web', 'yitongcodes/weibo_trends_analyzer_web', 'weibo-trends-analyzer', 0, 0, 45, '2026-03-04T13:07:01.732Z', '2026-03-04T14:01:51.860Z', '4f09e8e4fba13a21b859d1d9ac559a7db1112e7c9c44bbf62ca32760a840d40f', '{"id":"yitongcodes/weibo_trends_analyzer_web/weibo-trends-analyzer","name":"weibo-trends-analyzer","description":{"zh":"微博热点分析AI工具，每日更新微博热门话题，提供相关产品创意","ja":"ウェイボー流行トレンド分析AIエージェントは、毎日更新されたウェイボーのホットトピックと関連製品アイデアを提供","ko":"웨이보 트렌드 분석 AI 에이전트는 매일 업데이트되는 웨이보의 핫 토픽과 관련 제품 아이디어를 제공","es":"El Weibo-Trends-Analyzer es una herramienta de AI que analiza las tendencias de Weibo y proporciona ideas de productos relacionados.","fr":"L''Analyseur de tendances de Weibo est un outil de AI qui analyse les tendances de Weibo et fournit des idées de produits liés.","de":"Der Weibo-Trends-Analyser ist ein AI-Tool, das die Trends von Weibo analysiert und Ideen für Produkte, die damit verbunden sind, bereitstellt.","pt":"O Weibo Trends Analyzer é uma ferramenta de IA que fornece tendências quentes do Weibo e ideias de produtos relacionados","ru":"Анализатор трендов Вейбо - это инструмент ИИ, который предоставляет горячие тренды Вейбо и идеи продуктов","ar":"مُحَلِّل اتجاهات ويبو هو أداة ذكاء اصطناعي تقدم اتجاهات ويبو الساخنة وأفكار منتجات متعلقة","en":"This is a web web renewing daily weibo hot topics and provide you related product ideas based on these hot trends people discuss a lot."},"seo":{"title":{"zh":"微博热点分析AI工具","ja":"AIエージェント：ウェイボー流行トレンド分析","ko":"AI 에이전트: 웨이보 트렌드 분석","es":"Análisis de tendencias de Weibo - Herramienta de AI para ...","fr":"Analyseur de tendances de Weibo - Outil de AI pour agents","de":"Weibo-Trends-Analyser - AI-Tool für Agenten","pt":"Análise de Tendências do Weibo - Ferramentas de IA","ru":"Анализ Трендов Вейбо - ИИ Агенты","ar":"مُحَلِّل اتجاهات ويبو - أدوات الذكاء الاصطناعي","en":"weibo-trends-analyzer"},"description":{"zh":"微博热点分析AI工具，每日更新微博热门话题，提供相关产品创意","ja":"ウェイボー流行トレンド分析AIエージェントは、毎日更新されたウェイボーのホットトピックと関連製品アイデアを提供","ko":"웨이보 트렌드 분석 AI 에이전트는 매일 업데이트되는 웨이보의 핫 토픽과 관련 제품 아이디어를 제공","es":"El Weibo-Trends-Analyzer es una herramienta de AI que analiza las tendencias de Weibo y proporciona ideas de productos relacionados.","fr":"L''Analyseur de tendances de Weibo est un outil de AI qui analyse les tendances de Weibo et fournit des idées de produits liés.","de":"Der Weibo-Trends-Analyser ist ein AI-Tool, das die Trends von Weibo analysiert und Ideen für Produkte, die damit verbunden sind, bereitstellt.","pt":"O Weibo Trends Analyzer é uma ferramenta de IA que fornece tendências quentes do Weibo e ideias de produtos relacionados","ru":"Анализатор трендов Вейбо - это инструмент ИИ, который предоставляет горячие тренды Вейбо и идеи продуктов","ar":"مُحَلِّل اتجاهات ويبو هو أداة ذكاء اصطناعي تقدم اتجاهات ويبو الساخنة وأفكار منتجات متعلقة","en":"This is a web web renewing daily weibo hot topics and provide you related product ideas based on these hot trends people discuss a lot."},"definition":{"en":"This is a web web renewing daily weibo hot topics and provide you related product ideas based on these hot trends people discuss a lot."},"features":{"zh":["每日更新微博热门话题","提供相关产品创意","利用自然语言处理技术分析热门话题","支持多种数据导出格式","易于使用的界面"],"ja":["毎日更新されたウェイボーのホットトピック","関連製品アイデアの提供","自然言語処理技術を使用してホットトピックを分析","複数のデータエクスポート形式をサポート","使いやすいインターフェース"],"ko":["매일 업데이트되는 웨이보의 핫 토픽","관련 제품 아이디어 제공","자연어 처리 기술을 사용하여 핫 토픽 분석","여러 가지 데이터导出 형식 지원","사용하기 쉬운 인터페이스"],"es":["Análisis de tendencias de Weibo en tiempo real","Proporciona ideas de productos relacionados con las tendencias","Herramienta de AI para agentes y desarrolladores","Análisis de datos y visualización de resultados"],"fr":["Analyse de tendances de Weibo en temps réel","Fournit des idées de produits liés aux tendances","Outil de AI pour agents et développeurs","Analyse de données et visualisation de résultats"],"de":["Analyse von Weibo-Trends in Echtzeit","Bereitstellt Ideen für Produkte, die mit den Trends verbunden sind","AI-Tool für Agenten und Entwickler","Datenanalyse und Visualisierung von Ergebnissen"],"pt":["Análise de tendências do Weibo em tempo real","Ideias de produtos relacionados","Ferramenta de IA para análise de dados","Integração com plataformas de desenvolvimento","Suporte a múltiplos idiomas"],"ru":["Анализ трендов Вейбо в режиме реального времени","Идеи продуктов, связанных с трендовыми темами","Инструмент ИИ для анализа данных","Интеграция с платформами разработки","Поддержка нескольких языков"],"ar":["تحليل اتجاهات ويبو في الوقت الحقيقي","أفكار منتجات متعلقة بالاتجاهات","أداة ذكاء اصطناعي لتحليل البيانات","التكامل مع منصات التطوير","دعم اللغات المتعددة"]},"keywords":{"zh":["微博热点分析","AI工具","自然语言处理","热门话题分析","产品创意生成","微博营销","AI营销工具","微博分析软件"],"ja":["ウェイボー流行トレンド分析","AIエージェント","自然言語処理","ホットトピック分析","製品アイデア生成","ウェイボーマーケティング","AIマーケティングツール","ウェイボー分析ソフト"],"ko":["웨이보 트렌드 분석","AI 에이전트","자연어 처리","핫 토픽 분석","제품 아이디어 생성","웨이보 마케팅","AI 마케팅 도구","웨이보 분석 소프트웨어"],"es":["análisis de tendencias de Weibo","herramienta de AI para agentes","ideas de productos relacionados con tendencias","análisis de datos y visualización de resultados","desarrollo de productos con AI","agentes de AI para marketing y ventas"],"fr":["analyse de tendances de Weibo","outil de AI pour agents","idées de produits liés aux tendances","analyse de données et visualisation de résultats","développement de produits avec AI","agents de AI pour marketing et ventes"],"de":["Analyse von Weibo-Trends","AI-Tool für Agenten","Ideen für Produkte, die mit den Trends verbunden sind","Datenanalyse und Visualisierung von Ergebnissen","Entwicklung von Produkten mit AI","Agenten von AI für Marketing und Verkauf"],"pt":["ferramentas de IA","análise de tendências","Weibo Trends Analyzer","ideias de produtos","desenvolvimento de produtos","análise de dados","integração com plataformas","suporte a múltiplos idiomas","como usar Weibo Trends Analyzer"],"ru":["инструменты ИИ","анализ трендов","Анализатор трендов Вейбо","идеи продуктов","разработка продуктов","анализ данных","интеграция с платформами","поддержка нескольких языков","как использовать Анализатор трендов Вейбо"],"ar":["أدوات الذكاء الاصطناعي","تحليل الاتجاهات","مُحَلِّل اتجاهات ويبو","أفكار منتجات","تطوير المنتجات","تحليل البيانات","التكامل مع المنصات","دعم اللغات المتعددة","كيفية استخدام مُحَلِّل اتجاهات ويبو"]}},"owner":"yitongcodes","repo":"weibo_trends_analyzer_web","repoPath":"yitongcodes/weibo_trends_analyzer_web","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.732Z","topics":[],"category":"community","skillMd":{"name":"weibo-trends-analyzer","description":"Analyzes Weibo (微博) trending topics and generates creative product ideas based on hot search keywords. Fetches real-time trending data from Weibo API, researches background information and user insights, evaluates product development potential using a 100-point scoring system, and creates an interactive HTML dashboard. Use when analyzing Chinese social media trends, identifying product opportunities from trending topics, or generating market-driven creative product concepts.","bodyPreview":"# Weibo Trends Analyzer - 微博热搜创意产品分析\n\n## Overview\n\nThis skill helps you identify creative product opportunities from Weibo trending topics. It fetches real-time hot search data, researches comprehensive background information, evaluates product development potential, and presents findings in an interactive dashboard.\n\n**Keywords**: Weibo, 微博, trending topics, hot search, 热搜, product ideas, creative products, market analysis, social media trends, Chinese market\n\n## Workflow\n\n### 1. Fetch Weibo Tr","body":"# Weibo Trends Analyzer - 微博热搜创意产品分析\n\n## Overview\n\nThis skill helps you identify creative product opportunities from Weibo trending topics. It fetches real-time hot search data, researches comprehensive background information, evaluates product development potential, and presents findings in an interactive dashboard.\n\n**Keywords**: Weibo, 微博, trending topics, hot search, 热搜, product ideas, creative products, market analysis, social media trends, Chinese market\n\n## Workflow\n\n### 1. Fetch Weibo Trending Topics\n\n**Default API**: https://apis.tianapi.com/weibohot/index?key=4dfdf794141101d7bb8ece0294dbbc02\n\nWhen the user requests Weibo trending analysis, fetch the current hot search list:\n\n```bash\ncurl -s \"https://apis.tianapi.com/weibohot/index?key=4dfdf794141101d7bb8ece0294dbbc02\"\n```\n\n**API Response Processing**:\n\nThe API returns data in this format:\n```json\n{\n  \"code\": 200,\n  \"msg\": \"success\",\n  \"result\": {\n    \"list\": [\n      {\n        \"hotword\": \"trending keyword\",\n        \"hotwordnum\": \"1234567\",\n        \"hottag\": \"新/热/荐\"\n      }\n    ]\n  }\n}\n```\n\n**Field Mapping**:\n- `hotword` → Trending keyword (热搜关键词)\n- `hotwordnum` → Heat value (热度值), may contain category prefix like \"综艺 587870\"\n- `hottag` → Tag (标签): \"新\"(new), \"热\"(hot), \"荐\"(recommended), or empty\n- Ranking position → Inferred from array index (1-based)\n\n**Parsing Instructions**:\n1. Check if `code == 200` to confirm success\n2. Extract the `result.list` array\n3. For each item in the list:\n   - Rank = array index + 1\n   - Keyword = `hotword`\n   - Heat value = extract numeric value from `hotwordnum` (remove category prefix if present)\n   - Tag = `hottag`\n   - Category = extract from `hotwordnum` prefix if exists (e.g., \"综艺\", \"剧集\", \"盛典\", \"演出\")\n4. Limit analysis to top 10-15 items to manage processing time\n\n**Error Handling**:\n\nIf API fetch fails, follow this fallback strategy:\n\n1. **API Returns Error Code (code ≠ 200)**:\n   - Log the error message from API response\n   - Inform user: \"API returned error: {msg}. Would you like to use mock data instead?\"\n   - Suggest checking API key or quota limits\n   - If user agrees, use `.claude/skills/weibo-trends-analyzer/weibo-mock-data.json`\n\n2. **Network/Connection Failure**:\n   - Inform user: \"Unable to connect to API. Possible network issue.\"\n   - Offer to use mock data: `.claude/skills/weibo-trends-analyzer/weibo-mock-data.json`\n   - Suggest verifying internet connection\n\n3. **Invalid JSON Response**:\n   - Log the response received\n   - Inform user: \"API returned invalid data format\"\n   - Recommend checking if API endpoint has changed\n   - Fall back to mock data if available\n\n4. **Empty or Malformed Data**:\n   - If `result.list` is empty or missing\n   - Inform user: \"No trending topics found in API response\"\n   - Use mock data as fallback\n\n### 2. Deep Research Each Trending Topic\n\nFor EACH trending topic, perform **2 focused web searches** to gather essential background:\n\n**Search Strategy (2 searches per topic)**:\n\n**Search 1: Context & Background**\nCombine social media discussions and news background in one search:\n- Search query examples:\n  - \"{keyword} 微博 新闻背景\"\n  - \"{keyword} 热搜原因 讨论\"\n  - \"{keyword} latest news 用户看法\"\n\nGoal: Understand WHAT the trend is about and WHY it''s trending\n\n**Search 2: User Insights & Market Potential**\nFocus on consumer perspective and product opportunities:\n- Search query examples:\n  - \"{keyword} 用户需求 产品\"\n  - \"{keyword} 消费者痛点\"\n  - \"{keyword} 产品创意 市场\"\n\nGoal: Identify user needs, pain points, and product development opportunities\n\n**Information to Extract**:\nFrom the 2 searches, gather:\n- ✅ Social media sentiment and discussion volume (社交媒体讨论)\n- ✅ News background and event context (新闻背景)\n- ✅ Target demographics and audience size (目标人群)\n- ✅ User pain points and unmet needs (用户痛点)\n- ✅ Existing products or market gaps (市场机会)\n- ✅ Cultural/social significance (文化意义)\n\n**Error Handling for Web Searches**:\n\n1. **Search Returns No Results**:\n   - Log: \"No search results for: {keyword}\"\n   - Mark research as \"Limited data available\"\n   - Proceed with analysis using keyword itself and general market knowledge\n   - Note in dashboard: \"⚠️ 背景研究受限\"\n\n2. **Search Timeout or Failure**:\n   - Retry once with simplified query (just keyword without additional terms)\n   - If retry fails, mark as \"Search unavailable\"\n   - Continue analysis with available data\n   - Note limitation in product analysis\n\n3. **Irrelevant Search Results**:\n   - If results don''t match trending topic context:\n   - Try alternative search query with different keywords\n   - Use general industry knowledge for analysis\n   - Document: \"Based on general market analysis\"\n\n4. **Partial Search Success (1 of 2 succeeds)**:\n   - Proceed with available search data\n   - Note which aspect is missing (context vs. user insights)\n   - Make conservative estimates for missing information\n   - Mark in dashboard with: \"⚠️ 部分数据\"\n\n### 3. AI-Powered Product Ideation & Scoring\n\nFor each trending topic, analyze and generate creative product ideas using this scoring framework:\n\n**Scoring System (Total: 100 Points)**\n\n1. **Product Development Potential (可发展度)**: 40 points\n   - Market size and scalability (15 points)\n   - Technical feasibility (10 points)\n   - Trend longevity vs. fleeting fad (10 points)\n   - Competitive landscape (5 points)\n\n2. **Interest Level (有趣度)**: 20 points\n   - Creative uniqueness (10 points)\n   - Emotional appeal (5 points)\n   - Share-ability/viral potential (5 points)\n\n3. **Practical Life Utility (生活有用度)**: 20 points\n   - Daily life integration (10 points)\n   - Problem-solving capability (5 points)\n   - Target audience size (5 points)\n\n4. **Small-Scale Production Ease (小规模生产容易程度)**: 20 points\n   - Manufacturing complexity (10 points)\n   - Material accessibility (5 points)\n   - Cost efficiency for small batches (5 points)\n\n**Product Concept Requirements**:\n\nFor each trend, generate 1-3 creative product concepts including:\n\n- **Market Category (市场赛道)**: Which product category (e.g., home decor, fashion accessories, stationery, tech gadgets, lifestyle products, toys, etc.)\n- **Product Name (产品名称)**: Catchy, memorable name\n- **Target Audience (销售对象人群)**: Specific demographic (age, interests, income level, lifestyle)\n- **Manufacturing Characteristics (工厂批量生产特点)**:\n  - Production method (e.g., 3D printing, injection molding, screen printing, laser cutting)\n  - Material requirements\n  - Minimum order quantity (MOQ) feasibility\n  - Lead time estimates\n  - Cost structure (per unit at different volumes)\n- **Detailed Description (详细描述)**: How the product relates to the trending topic\n- **Total Score (总分)**: Sum of all four scoring dimensions\n- **Score Breakdown (评分分析)**: Brief justification for each score component\n\n**Scoring Guidelines**:\n- Be objective and realistic\n- Consider Chinese market context\n- Factor in current manufacturing capabilities\n- Account for trend cycle timing\n\n### 4. Generate Interactive HTML Dashboard\n\nCreate a comprehensive, visually appealing HTML dashboard with the following structure:\n\n**Dashboard Components**:\n\n**A. Header Section**\n```html\n- Title: \"微博热搜创意产品分析报告 - Weibo Trends Product Analysis\"\n- Generation timestamp\n- Total trends analyzed count\n- Summary statistics (average score, top categories, etc.)\n```\n\n**B. Highlight Section - Top Performers**\nDisplay products by score tiers:\n\n- **🏆 Outstanding (优秀) - Score ≥ 80**:\n  - Prominent display with gold/premium styling\n  - Enlarged cards with detailed breakdown\n  - Recommended action: \"优先开发推荐\"\n\n- **⭐ Good (良好) - Score 60-79**:\n  - Standard card layout with highlighted borders\n  - Recommended action: \"可考虑开发\"\n\n- **📋 Other Products - Score < 60**:\n  - Compact list view\n  - Recommended action: \"观望或需优化\"\n\n**C. Product Cards**\n\nEach product card should display:\n```html\n<div class=\"product-card score-tier-{excellent/good/other}\">\n  <div class=\"trend-info\">\n    <h3>{Trending Keyword}</h3>\n    <span class=\"rank\">热搜排名: #{rank}</span>\n    <span class=\"heat\">热度: {heat_value}</span>\n  </div>\n\n  <div class=\"product-concept\">\n    <h4>{Product Name}</h4>\n    <div class=\"total-score\">{Total Score}/100</div>\n    <div class=\"score-badge\">{优秀/良好/其他}</div>\n\n    <div class=\"details\">\n      <p><strong>市场赛道:</strong> {market_category}</p>\n      <p><strong>目标人群:</strong> {target_audience}</p>\n      <p><strong>产品描述:</strong> {description}</p>\n      <p><strong>生产特点:</strong> {manufacturing_details}</p>\n    </div>\n\n    <div class=\"score-breakdown\">\n      <h5>评分详情</h5>\n      <div class=\"score-bar\">\n        <span>可发展度</span>\n        <progress value=\"{score}\" max=\"40\"></progress>\n        <span>{score}/40</span>\n      </div>\n      <div class=\"score-bar\">\n        <span>有趣度</span>\n        <progress value=\"{score}\" max=\"20\"></progress>\n        <span>{score}/20</span>\n      </div>\n      <div class=\"score-bar\">\n        <span>生活有用度</span>\n        <progress value=\"{score}\" max=\"20\"></progress>\n        <span>{score}/20</span>\n      </div>\n      <div class=\"score-bar\">\n        <span>生产容易度</span>\n        <progress value=\"{score}\" max=\"20\"></progress>\n        <span>{score}/20</span>\n      </div>\n    </div>\n\n    <div class=\"analysis\">\n      <h5>分数分析</h5>\n      <p>{score_justification}</p>\n    </div>\n  </div>\n\n  <div class=\"research-summary\">\n    <h5>背景研究</h5>\n    <ul>\n      <li><strong>社交媒体:</strong> {social_media_insights}</li>\n      <li><strong>新闻背景:</strong> {news_background}</li>\n      <li><strong>用户洞察:</strong> {user_insights}</li>\n    </ul>\n  </div>\n</div>\n```\n\n**D. Dashboard Styling Requirements**\n\n```css\n/* Color Scheme */\n- Excellent products (≥80): Gold/amber theme (#FFD700, #FFA500)\n- Good products (60-79): Blue/cyan theme (#4A90E2, #50C8E8)\n- Other products (<60): Gray/neutral theme (#95A5A6, #BDC3C7)\n\n/* Design Guidelines */\n- Responsive layout (grid or flexbox)\n- Clean, modern aesthetics\n- Clear visual hierarchy\n- Easy-to-read typography (Chinese + English support)\n- Interactive hover effects\n- Sortable/filterable options\n- Progress bars for score visualization\n- Badge system for quick identification\n```\n\n**E. Interactive Features**\n\nInclude JavaScript for:\n- Sort by score (highest to lowest, lowest to highest)\n- Filter by score tier (优秀/良好/其他)\n- Filter by market category\n- Search functionality for keywords\n- Expandable/collapsible detailed sections\n- Export to PDF option (bonus)\n\n**F. Footer Section**\n```html\n- Disclaimer about trend volatility\n- Recommendation to conduct further market research\n- Generation metadata (API source, analysis timestamp)\n- Skill version information\n```\n\n### 5. File Output\n\nGenerate the following files:\n\n1. **`weibo-trends-analysis-{YYYY-MM-DD}.html`**: Complete interactive dashboard\n2. **`weibo-trends-data-{YYYY-MM-DD}.json`**: Raw structured data for further processing (optional)\n\n**Error Handling for File Generation**:\n\n1. **File Write Permission Denied**:\n   - Try alternative filename with timestamp: `weibo-trends-analysis-{YYYY-MM-DD-HHmmss}.html`\n   - If still fails, inform user: \"Unable to write files. Please check directory permissions.\"\n   - Suggest user-provided output path\n\n2. **HTML Generation Error**:\n   - If template rendering fails, create simplified HTML version with basic table layout\n   - Ensure at minimum: product names, scores, and basic descriptions are included\n   - Log error details for troubleshooting\n\n3. **Data Validation Before Output**:\n   - Verify at least 1 product concept was generated\n   - Check all scores are within valid ranges (0-40, 0-20, etc.)\n   - Ensure required fields are present (product name, score, description)\n   - If validation fails, inform user which topics had issues\n\n4. **Large File Handling**:\n   - If analyzing >20 topics, warn user about large file size\n   - Consider generating paginated HTML or summary + detailed sections\n   - Ensure browser compatibility for large datasets\n\n## Best Practices\n\n**Research Quality**:\n- Perform 2 focused web searches per trending topic (optimized for efficiency)\n- Synthesize information from multiple sources within each search\n- Verify factual accuracy\n- Note information freshness\n- Prioritize quality over quantity in search results\n\n**Product Ideation**:\n- Think beyond obvious connections\n- Consider cultural context and Chinese consumer behavior\n- Evaluate both short-term trend exploitation and long-term product viability\n- Be creative but realistic\n\n**Scoring Objectivity**:\n- Use consistent criteria across all products\n- Justify scores with specific evidence\n- Avoid bias toward certain product categories\n- Consider manufacturing realities in China\n\n**Dashboard Quality**:\n- Ensure all Chinese characters display correctly (UTF-8 encoding)\n- Test responsiveness on different screen sizes\n- Validate HTML/CSS/JS syntax\n- Include fallback fonts for Chinese text\n- Make data visualizations clear and intuitive\n\n## Example Usage Flow\n\n```\nUser: \"分析微博热搜\"\n或\nUser: \"分析今日微博热搜并生成产品创意\"\n\nClaude:\n1. Fetches trending data from default API (https://apis.tianapi.com/weibohot/index?key=...)\n   - If API fails, offers to use mock data\n2. Parses the result.list array and extracts top 10-15 trending topics\n3. For each topic:\n   - Performs 2 focused web searches for background research\n   - Handles search failures gracefully with fallback strategies\n   - Analyzes market potential and user needs\n   - Generates creative product concepts\n   - Calculates detailed scores\n4. Validates all generated data\n5. Compiles all data into structured format\n6. Generates interactive HTML dashboard with error indicators if needed\n7. Saves output files\n\nOutput:\n- weibo-trends-analysis-2026-01-11.html\n- weibo-trends-data-2026-01-11.json (optional)\n```\n\n## Limitations and Considerations\n\n**API Dependencies**:\n- Requires valid Weibo API endpoint provided by user\n- API rate limits may affect number of trends that can be analyzed\n- API response format may vary - adapt parsing as needed\n\n**Web Search Constraints**:\n- Search results quality depends on keyword specificity\n- Chinese language content may require specific search strategies\n- Information recency is critical for trend analysis\n\n**Scoring Subjectivity**:\n- Despite structured framework, some scoring involves judgment\n- Market conditions change rapidly\n- Manufacturing feasibility requires domain expertise validation\n\n**Dashboard Limitations**:\n- Static HTML file (not a live web application)\n- Requires modern browser for best experience\n- Large datasets (>50 products) may impact page performance\n\n## Technical Requirements\n\n**Tools Available**:\n- Bash: For API calls using curl\n- WebSearch: For researching trending topics (REQUIRED)\n- Write: For generating HTML and JSON output files\n\n**Dependencies**:\n- No external libraries required for basic functionality\n- Modern web browser for viewing dashboard\n- Internet connection for API and web searches\n\n## Quality Checklist\n\nBefore finalizing output, verify:\n- [ ] All trending topics have been researched (2 focused searches each)\n- [ ] Search failures handled gracefully with appropriate fallbacks\n- [ ] Every product concept includes all required fields\n- [ ] Scores are calculated correctly and sum to totals\n- [ ] Data limitations marked clearly (⚠️ indicators where applicable)\n- [ ] HTML renders correctly with proper UTF-8 encoding\n- [ ] Chinese characters display properly\n- [ ] Interactive features (sort, filter, search) work\n- [ ] Styling differentiates score tiers clearly\n- [ ] All links and references are functional\n- [ ] Dashboard is responsive on different screen sizes\n- [ ] Data accuracy has been verified\n\n## Advanced Features (Optional)\n\nIf time and context allow, consider adding:\n\n**Trend Tracking**:\n- Compare with previous analyses to identify rising/falling trends\n- Track keyword position changes over time\n- Identify recurring themes or patterns\n\n**Competitive Analysis**:\n- Check for existing similar products on Taobao/Tmall/JD\n- Analyze pricing strategies\n- Identify market gaps\n\n**Visual Enhancements**:\n- Charts and graphs for score distributions\n- Trend heat maps\n- Category breakdowns (pie charts)\n- Timeline visualizations\n\n**Export Options**:\n- CSV export for spreadsheet analysis\n- PDF generation for presentations\n- API-ready JSON for integration with other systems\n\n## Version History\n\n- v1.2 (2026-01-17): Error handling & performance optimization\n  - Comprehensive error handling for API, web searches, and file generation\n  - Optimized web searches from 3-5 to 2 focused searches per topic\n  - Improved reliability with graceful fallbacks\n  - 33-40% faster processing time\n- v1.1 (2026-01-11): API integration with TianAPI\n  - Built-in Weibo trending API\n  - Updated data parsing for real API format\n- v1.0 (2026-01-11): Initial skill creation\n  - Core workflow: API fetch → Research → Scoring → Dashboard\n  - 100-point scoring system\n  - Interactive HTML dashboard with tier-based highlighting\n\n## References and Resources\n\n**Weibo Trending Data**:\n- Official Weibo Hot Search: https://s.weibo.com/top/summary\n- Alternative APIs may provide different data structures\n\n**Product Development Resources**:\n- Alibaba 1688: For manufacturing partner research\n- Taobao/Tmall: For market research and competitive analysis\n- Pinduoduo: For trending product categories\n\n**Design Inspiration**:\n- Product Hunt: For creative product naming and positioning\n- Xiaohongshu (小红书): For lifestyle product trends\n- Douyin (抖音): For viral product concepts\n\n## Support and Troubleshooting\n\n**Common Issues**:\n\n1. **API Returns Empty Data**:\n   - Verify API endpoint is correct and accessible\n   - Check API authentication if required\n   - Try alternative Weibo trending API sources\n\n2. **Web Search Not Finding Relevant Information**:\n   - Refine search queries to be more specific\n   - Try different keyword combinations (Chinese + English)\n   - Use site-specific searches (site:weibo.com, site:baidu.com)\n\n3. **HTML Dashboard Not Displaying Correctly**:\n   - Ensure file uses UTF-8 encoding\n   - Check for JavaScript errors in browser console\n   - Verify all HTML tags are properly closed\n\n4. **Scores Seem Inconsistent**:\n   - Review scoring guidelines in Section 3\n   - Ensure all criteria are evaluated objectively\n   - Document reasoning for borderline scores\n\n**Getting Help**:\n- Review official Claude Code skills documentation\n- Check example skills for similar patterns\n- Validate JSON data structure before generating HTML\n\n---\n\n**License**: MIT License - Free to use and modify\n**Author**: Claude Code Skills Framework\n**Last Updated**: 2026-01-17\n**Version**: 1.2"},"lastSynced":"2026-03-04T14:01:51.860Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing advanced Weibo trending topic analysis capabilities.","zh":"非常适合需要高级微博热搜话题分析能力的数据分析代理。","ja":"高度なWeiboトレンドトピック分析機能を必要とするデータ分析エージェントに最適です。","ko":"고급 웨이보 핫搜 주제 분석 기능이 필요한 데이터 분석 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan capacidades avanzadas de análisis de temas de tendencia de Weibo.","fr":"Parfait pour les agents d''analyse de données ayant besoin de capacités avancées d''analyse de sujets tendance Weibo.","de":"Perfekt für Data Analysis Agents, die erweiterte Weibo-Trending-Topic-Analysefunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de capacidades avançadas de análise de tópicos de tendência do Weibo.","ru":"Идеально для агентов анализа данных, которым необходимы продвинутые возможности анализа тем трендов Weibo.","ar":"مثالي لعميل تحليل البيانات الذي يحتاج إلى إمكانيات متقدمة لتحليل موضوعات ويبو الشائعة."},"recommendation":{"en":"Empowers agents to generate real-time hot search data, research comprehensive background information, and evaluate product development potential using libraries like ''pandas'' and ''matplotlib''. It provides interactive dashboard findings in formats like ''.csv'' and ''.svg''.","zh":"赋予代理生成实时热搜数据、研究综合背景信息和使用像''pandas''和''matplotlib''的库来评估产品开发潜力的能力。它提供以''.csv''和''.svg''格式的交互式仪表板发现。","ja":"エージェントがリアルタイムのホット検索データを生成し、包括的なバックグラウンド情報を調査し、''pandas''や''matplotlib''などのライブラリを使用して製品開発の潜在性を評価する能力を付与します。''.csv''や''.svg''などの形式でインタラクティブなダッシュボードの発見を提供します。","ko":"에이전트가 실시간 핫 검색 데이터를 생성하고, 포괄적인 배경 정보를 연구하며, ''pandas'' 및 ''matplotlib''와 같은 라이브러리를 사용하여 제품 개발 잠재력을 평가하는 기능을 제공합니다. ''.csv'' 및 ''.svg'' 형식의 상호 작용 대시보드 결과를 제공합니다.","es":"Habilita a los agentes a generar datos de búsqueda en tiempo real, investigar información de fondo completa y evaluar el potencial de desarrollo de productos utilizando bibliotecas como ''pandas'' y ''matplotlib''. Proporciona resultados de panel de instrumentos interactivos en formatos como ''.csv'' y ''.svg''.","fr":"Permet aux agents de générer des données de recherche en temps réel, de rechercher des informations de fond complètes et d''évaluer le potentiel de développement de produits en utilisant des bibliothèques comme ''pandas'' et ''matplotlib''. Il fournit des résultats de tableau de bord interactif au format ''.csv'' et ''.svg''.","de":"Ermächtigt Agenten, Echtzeit-Suchdaten zu generieren, umfassende Hintergrundinformationen zu recherchieren und das Potenzial der Produktentwicklung unter Verwendung von Bibliotheken wie ''pandas'' und ''matplotlib'' zu bewerten. Es bietet interaktive Dashbordeergebnisse in Formaten wie ''.csv'' und ''.svg''.","pt":"Permite que os agentes gerem dados de pesquisa em tempo real, pesquisem informações de contexto abrangentes e avaliem o potencial de desenvolvimento de produtos usando bibliotecas como ''pandas'' e ''matplotlib''. Ele fornece resultados de painel interativo em formatos como ''.csv'' e ''.svg''.","ru":"Позволяет агентам генерировать данные горячего поиска в реальном времени, исследовать полную информацию о фоне и оценивать потенциал разработки продукта с помощью библиотек như ''pandas'' и ''matplotlib''. Он предоставляет результаты интерактивной панели в форматах как ''.csv'' и ''.svg''.","ar":"يمكن للعميل توليد بيانات للبحث الساخن في الوقت الفعلي، وإجراء بحث حول معلومات الخلفية الشاملة، وتقييم إمكانيات تطوير المنتج باستخدام المكتبات مثل ''pandas'' و ''matplotlib''. كما يقدم نتائج لوحة تحكم تفاعلية بالتنسيقات مثل ''.csv'' و ''.svg''."},"useCases":{"en":["Analyzing Weibo trending topics for market research","Generating product ideas based on hot search data","Evaluating product development potential using data visualization techniques"],"zh":["分析微博热搜话题以进行市场研究","根据热搜数据生成产品创意","使用数据可视化技术来评估产品开发潜力"],"ja":["市場調査のためにWeiboトレンドトピックを分析する","ホット検索データに基づいて製品アイデアを生成する","データ視覚化技術を使用して製品開発の潜在性を評価する"],"ko":["市場 조사를 위해 웨이보 핫搜 주제를 분석하는 것","핫 검색 데이터를 기반으로 제품 아이디어를 생성하는 것","데이터 시각화 기술을 사용하여 제품 개발 잠재력을 평가하는 것"],"es":["Análisis de temas de tendencia de Weibo para investigación de mercado","Generación de ideas de productos en función de los datos de búsqueda en caliente","Evaluación del potencial de desarrollo de productos mediante técnicas de visualización de datos"],"fr":["Analyse des sujets tendance Weibo pour la recherche de marché","Génération d''idées de produits basées sur les données de recherche en temps réel","Évaluation du potentiel de développement de produits en utilisant des techniques de visualisation de données"],"de":["Analyse von Weibo-Trending-Themen für Marktforschung","Generierung von Produktideen basierend auf Echtzeit-Suchdaten","Bewertung des Potenzials der Produktentwicklung unter Verwendung von Datenvisualisierungstechniken"],"pt":["Analisar tópicos de tendência do Weibo para pesquisa de mercado","Gerar ideias de produtos com base em dados de pesquisa quente","Avaliar o potencial de desenvolvimento de produtos usando técnicas de visualização de dados"],"ru":["Анализ тем трендов Weibo для маркетинговых исследований","Генерация идей продуктов на основе данных горячего поиска","Оценка потенциала разработки продукта с помощью методов визуализации данных"],"ar":["تحليل موضوعات ويبو الشائعة لأغراض البحث السوقي","توليد أفكار منتجات بناءً على بيانات البحث الساخن","تقييم إمكانيات تطوير المنتج باستخدام تقنيات تحليل البيانات"]},"limitations":{"en":["Requires active Weibo API connection","Weibo data only"],"zh":["需要活跃的微博API连接","仅限微博数据"],"ja":["アクティブなWeibo API接続が必要","Weiboデータのみ"],"ko":["활성 웨이보 API 연결이 필요","웨이보 데이터만"],"es":["Requiere conexión activa de API de Weibo","Solo datos de Weibo"],"fr":["Nécessite une connexion API Weibo active","Données Weibo uniquement"],"de":["Benötigt eine aktive Weibo-API-Verbindung","Nur Weibo-Daten"],"pt":["Requer conexão ativa com a API do Weibo","Dados do Weibo apenas"],"ru":["Требуется активное подключение к API Weibo","Данные только из Weibo"],"ar":["يتطلب اتصالًا نشطًا بويبو API","بيانات ويبو فقط"]},"version":3},"contentHash":"4f09e8e4fba13a21b859d1d9ac559a7db1112e7c9c44bbf62ca32760a840d40f","qualityScore":45}');
