INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marcusgoll/Spec-Flow/task-status-sync', 'task-status-sync', 'marcusgoll', 'Spec-Flow', 'community', 'task-status-sync marcusgoll Spec-Flow community Spec-Driven Development和Claude Code实现可重复的任务状态同步，带来高效的生产力 Spec-Driven DevelopmentとClaude Codeを使用してタスクステータスを同期し、開発の効率を向上します Spec-Driven Development와 Claude Code를 사용하여 태스크 상태를 동기화하고 개발 효율을 높입니다 La habilidad task-status-sync permite a los desarrolladores sincronizar el estado de tareas con Spec-Driven Development y Claude Code La compétence task-status-sync permet aux développeurs de synchroniser l''état des tâches avec Spec-Driven Development et Claude Code Die Fähigkeit task-status-sync ermöglicht es Entwicklern, den Aufgabenstatus mit Spec-Driven Development und Claude Code zu synchronisieren O task-status-sync permite que você transforme ideias de produtos em lançamentos de produção com Spec-Driven Development ИИ Агент task-status-sync позволяет превратить идеи продуктов в производственные запуски с Spec-Driven Development يسمح لك task-status-sync بتحويل أفكار المنتجات إلى إطلاقات الإنتاج مع Spec-Driven Development Turn product ideas into production launches with Spec-Driven Development. Repeatable Claude Code workflows with quality gates, token budgets, and auditable artifacts. AI智能代理 任务状态同步 Spec-Driven Development Claude Code 如何使用AI智能代理 AI智能代理安装 AI智能代理设置指南 Turn product ideas into production launches with Spec-Driven Development. Repeatable Claude Code workflows with quality gates, token budgets, and auditable artifacts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zby/llm-do/decomplect-py', 'community', 'zby', 'llm-do', 'zby/llm-do', 'decomplect-py', 0, 0, 45, '2026-03-04T13:07:01.754Z', '2026-03-04T14:13:23.209Z', 'c7495484fe8ff66f28289d8233864cbb63eb16e274bf7044c07bf1274fd8262c', '{"id":"zby/llm-do/decomplect-py","name":"decomplect-py","description":{"zh":"decomplect-py是一个AI智能工具，允许您使用LLM探索和Python稳定代码","ja":"decomplect-pyはAIエージェントであり、LLMで探索し、Pythonでコードを安定化する","ko":"decomplect-py는 AI 에이전트로서 LLM로 탐색하고 Python으로 코드를 안정화하는 도구","es":"decomplect-py es una herramienta de AI que permite a los desarrolladores explorar y estabilizar su código con Python","fr":"decomplect-py est un outil d''IA qui permet aux développeurs d''explorer et de stabiliser leur code avec Python","de":"decomplect-py ist ein KI-Tool, das es Entwicklern ermöglicht, ihren Code mit Python zu erkunden und zu stabilisieren","pt":"O decomplect-py é uma ferramenta de IA que combina a exploração com LLM e a estabilização com código Python. Aprenda a refatorar entre trabalhadores e ferramentas","ru":"ИИ Агент decomplect-py - это инструмент, который объединяет исследование с LLM и стабилизацию с помощью кода Python. Узнайте, как рефакторить между работниками и инструментами","ar":"برنامج decomplect-py هو أداة ذكاء اصطناعي التي تجمع بين الاستكشاف مع LLM وتثبيت مع كود Python. تعرف على كيفية إعادة هيكلة بين العمال والأدوات","en":"\"Extend with llm, stabilise with code\" - Prompts when you''re exploring, Python when you''re certain. Workers and tools form one function space—refactor between them."},"seo":{"title":{"zh":"AI智能工具 decomplect-py - 扩展LLM，稳定代码","ja":"AIエージェント decomplect-py - LLMを拡張、コードを安定化","ko":"AI 에이전트 decomplect-py - LLM 확장, 코드 안정화","es":"Herramientas de AI: decomplect-py para Desarrolladores","fr":"Outils d''IA : decomplect-py pour les Développeurs","de":"KI-Tools: decomplect-py für Entwickler","pt":"F