INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gAmUssA/vscode-open-in-marked2/openspec-new-change', 'openspec-new-change', 'gAmUssA', 'vscode-open-in-marked2', 'community', 'openspec-new-change gAmUssA vscode-open-in-marked2 community openspec-new-change是一个VS Code扩展，允许开发者在Marked 2中打开Markdown和AsciiDoc文件，简化开发流程 openspec-new-changeは、開発者がMarked 2でMarkdownとAsciiDocファイルを開くことができるVS Code拡張機能です openspec-new-change는 개발자가 Marked 2에서 마크다운 및 AsciiDoc 파일을 열 수 있는 VS Code 확장機能입니다 La extensión openspec-new-change para VS Code abre archivos Markdown y AsciiDoc en Marked 2 para una mejor edición L''extension openspec-new-change pour VS Code ouvre des fichiers Markdown et AsciiDoc dans Marked 2 pour une meilleure édition Die Erweiterung openspec-new-change für VS Code öffnet Markdown- und AsciiDoc-Dateien in Marked 2 für eine bessere Bearbeitung A extensão openspec-new-change do VS Code permite abrir arquivos Markdown e AsciiDoc em Marked 2, melhorando a produtividade dos desenvolvedores Расширение openspec-new-change для VS Code позволяет открывать файлы Markdown и AsciiDoc в Marked 2, улучшая производительность разработчиков موسع openspec-new-change من VS Code يمكن فتح ملفات Markdown و AsciiDoc في Marked 2، مما يعزز إنتاجية المطورين VS Code extension to open Markdown and AsciiDoc files in Marked 2 如何使用openspec-new-change 什么是openspec-new-change openspec-new-change安装 VS Code扩展 Marked 2 Markdown编辑器 AsciiDoc编辑器 开发工具 VS Code extension to open Markdown and AsciiDoc files in Marked 2');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SlySlayer32/dashboard-link-saas/request-enhancer', 'community', 'SlySlayer32', 'dashboard-link-saas', 'SlySlayer32/dashboard-link-saas', 'request-enhancer', 0, 0, 45, '2026-03-04T13:07:01.814Z', '2026-03-04T14:35:34.643Z', '66d964746b011870ffae5f722872a09f509dd9e8fdea9527eb1b0bda6ed2b3cc', '{"id":"SlySlayer32/dashboard-link-saas/request-enhancer","name":"request-enhancer","description":{"zh":"request-enhancer 是一个 SaaS 平台，用于通过 SMS 提供个性化的日报表。它帮助开发者快速构建和发送定制化的报告","ja":"request-enhancer は、SMS を介してカスタマイズ可能な日報ダッシュボードを提供する SaaS プラットフォームです。開発者が迅速にカスタマイズ可能なレポートを構築して送信するのを支援します","ko":"request-enhancer는 SMS를 통해 개인화된 일일 대시보드를 제공하는 SaaS 플랫폼입니다. 개발자가 빠르게 맞춤형 보고서를 구축하고 전송하도록 지원합니다","es":"request-enhancer es una plataforma SaaS que ofrece tableros personalizados diarios a través de SMS. Está diseñada para mejorar la experiencia del usuario","fr":"request-enhancer est une plateforme SaaS qui propose des tableaux de bord personnalisés quotidiens via SMS. Elle est conçue pour améliorer l''expérience utilisateur","de":"request-enhancer ist eine SaaS-Plattform, die personalisierte tägliche Dashboards über SMS anbietet. Sie ist darauf ausgelegt, die Benutzererfahrung zu verbessern","pt":"O request-enhancer é uma plataforma SaaS que entrega dashboards personalizados diários via SMS, utilizando Inteligência Artificial para melhorar a produtividade do desenvolvedor","ru":"ИИ Агент request-enhancer - это платформа SaaS, которая доставляет персонализированные ежедневные панели через SMS, используя ИИ для повышения производительности разработчика","ar":"أداة request-enhancer هي منصة سحابية لتسليم لوحات القيادة الشخصية اليومية عبر رسائل الاشرطة القصيرة، باستخدام الذكاء الاصطناعي لتحسين إنتاجية المطور","en":"SaaS platform for delivering personalized daily dashboards via SMS"},"seo":{"title":{"zh":"AI智能代理 request-enhancer：个性化日报表SMS平台","