INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gpu-cli/gpu/gpu-cli', 'gpu-cli', 'gpu-cli', 'gpu', 'community', 'gpu-cli gpu-cli gpu community gpu-cli 是一个用于管理和优化 GPU 资源的命令行工具，提供公共文档和问题跟踪 gpu-cli は GPU リソースを管理および最適化するための CLI ツールで、パブリックドキュメントと問題追跡を提供します gpu-cli는 GPU 리소스를 관리하고 최적화하는 명령줄 도구로, 공개 문서와 문제 추적을 제공합니다 gpu-cli es una herramienta de línea de comandos para GPU con documentación y problemas públicos gpu-cli est un outil en ligne de commande pour GPU avec documentation et problèmes publics gpu-cli ist ein GPU-CLI-Tool mit öffentlicher Dokumentation und Problemen A gpu-cli é uma ferramenta de linha de comando para GPU, com documentação e problemas públicos disponíveis. ИИ Агент gpu-cli - это командная строка для GPU с общедоступной документацией и проблемами. أداة الذكاء الاصطناعي gpu-cli هي سطر أوامر للوحدات العصبونية، مع توثيق ومشاكل عامة متاحة. Public facing GPU cli docs and issues gpu-cli AI工具 GPU命令行工具 如何使用gpu-cli gpu-cli安装 gpu-cli替代品 Public facing GPU cli docs and issues ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nrwl/nx/ci-monitor', 'community', 'nrwl', 'nx', 'nrwl/nx', 'ci-monitor', 0, 0, 45, '2026-03-04T13:07:01.889Z', '2026-03-04T14:54:05.759Z', 'a124ec3b3bd0e12152c9729b1239df7f69da2321c3a4d8be2014943056d3f6b6', '{"id":"nrwl/nx/ci-monitor","name":"ci-monitor","description":{"zh":"Nx是一个Monorepo平台，用于优化构建、扩展CI和自动修复失败的PR，帮助开发者和AI代理更高效地工作","ja":"Nxは、ビルドを最適化し、CIを拡張し、失敗したPRを自動的に修復するMonorepoプラットフォームです。開発者とAIエージェントがより効率的に作業できるようにします","ko":"Nx는 빌드를 최적화하고 CI를 확장하고 실패한 PR을 자동으로 修復하는 Monorepo 플랫폼입니다. 개발자와 AI 에이전트가 더 효율적으로 작업할 수 있도록 합니다","es":"La plataforma Monorepo que amplifica a los desarrolladores y agentes de inteligencia artificial, optimizando builds y CI con Nx","fr":"La plateforme Monorepo qui amplifie les développeurs et les agents d''intelligence artificielle, en optimisant les builds et la CI avec Nx","de":"Die Monorepo-Plattform, die Entwickler und KI-Agents verstärkt, indem sie Builds und CI mit Nx optimiert","pt":"O ci-monitor é uma plataforma que amplifica os desenvolvedores e os Agentes de IA, otimizando compilações e escalando CI","ru":"Ci-monitor - это платформа, которая усиливает разработчиков и ИИ Агентов, оптимизируя сборки и масштабируя CI","ar":"ci-monitor هو منصة تعزز المطورين وأدوات الذكاء الاصطناعي، وتحسين الترجمات وتوسيع نطاق CI","en":"The Monorepo Platform that amplifies both developers and AI agents. Nx optimizes your builds, scales your CI, and fixes failed PRs automatically. Ship in half the time."},"seo":{"title":{"zh":"CI监控AI代理 - Nx优化您的构建","ja":"CIモニタリングAIエージェント - Nxでビルドを最適化","ko":"CI 모니터링 AI 에이전트 - Nx로 빌드 최적화","es":"Herramientas de Agente de Inteligencia Artificial: ci-mon...","fr":"Outils d''Agent d''Intelligence Artificielle: ci-monitor","de":"KI-Agent-Tools: ci-monitor","pt":"Ferramentas de IA: ci-monitor para Desenvolvedores","ru":"ИИ Агенты: ci-monitor для Разработчиков","ar":"أدوات الذكاء الاصطناعي: ci-monitor للمطورين","en":"ci-monitor"},"description":{"zh":"Nx是一个Monorepo平台，用于优化构建、扩展CI和自动修复失败的PR，帮助开发者和AI代理更高效地工作","ja":"Nxは、ビルドを最適化し、CIを拡張し、失敗したPRを自動的に修復するMonorepoプラットフォームです。開発者とAIエージェントがより効率的に作業できるようにします","ko":"Nx는 빌드를 최적화하고 CI를 확장하고 실패한 PR을 자동으로 修復하는 Monorepo 플랫폼입니다. 개발자와 AI 에이전트가 더 효율적으로 작업할 수 있도록 합니다","es":"La plataforma Monorepo que amplifica a los desarrolladores y agentes de inteligencia artificial, optimizando builds y CI con Nx","fr":"La plateforme Monorepo qui amplifie les développeurs et les agents d''intelligence artificielle, en optimisant les builds et la CI avec Nx","de":"Die Monorepo-Plattform, die Entwickler und KI-Agents verstärkt, indem sie Builds und CI mit Nx optimiert","pt":"O ci-monitor é uma plataforma que amplifica os desenvolvedores e os Agentes de IA, otimizando compilações e escalando CI","ru":"Ci-monitor - это платформа, которая усиливает разработчиков и ИИ Агентов, оптимизируя сборки и масштабируя CI","ar":"ci-monitor هو منصة تعزز المطورين وأدوات الذكاء الاصطناعي، وتحسين الترجمات وتوسيع نطاق CI","en":"The Monorepo Platform that amplifies both developers and AI agents. Nx optimizes your builds, scales your CI, and fixes failed PRs automatically. Ship in hal..."},"definition":{"en":"The Monorepo Platform that amplifies both developers and AI agents. Nx optimizes your builds, scales your CI, and fixes failed PRs automatically. Ship in half the time."},"features":{"zh":["优化构建","扩展CI","自动修复失败的PR","提高开发效率","支持Monorepo"],"ja":["ビルドを最適化","CIを拡張","失敗したPRを自動的に修復","開発効率を向上","Monorepoをサポート"],"ko":["빌드를 최적화","CI를 확장","실패한 PR을 자동으로 修復","개발 효율을 향상","Monorepo를 지원"],"es":["Optimización de builds con Nx","Escala de CI","Corrección automática de PRs fallidas","Despliegue en la mitad de tiempo","Integración con herramientas de desarrollo populares"],"fr":["Optimisation des builds avec Nx","Mise à l''échelle de la CI","Correction automatique des PR échouées","Livraison en deux fois moins de temps","Intégration avec des outils de développement populaires"],"de":["Optimierung von Builds mit Nx","Skalierung von CI","Automatische Korrektur fehlgeschlagener PRs","Lieferung in halber Zeit","Integration mit beliebten Entwicklungstools"],"pt":["Otimização de compilações","Escalabilidade de CI","Automação de fluxos de trabalho","Integração com Agentes de IA","Suporte a monorepo"],"ru":["Оптимизация сборок","Масштабирование CI","Автоматизация рабочих процессов","Интеграция с ИИ Агентами","Поддержка монорепо"],"ar":["تحسين الترجمات","توسيع نطاق CI","تحسين تدفقات العمل","التكامل مع أدوات الذكاء الاصطناعي","دعم مونوريبو"]},"keywords":{"zh":["如何使用CI监控AI代理","什么是Monorepo","CI监控AI代理安装","Nx与Jenkins比较","CI监控AI代理设置指南","如何优化构建","CI监控AI代理的优势"],"ja":["CIモニタリングAIエージェントの使用方法","Monorepoとは","CIモニタリングAIエージェントのインストール","NxとJenkinsの比較","CIモニタリングAIエージェントの設定ガイド","ビルドを最適化する方法","CIモニタリングAIエージェントの利点"],"ko":["CI 모니터링 AI 에이전트 사용법","Monorepo란","CI 모니터링 AI 에이전트 설치","Nx와 Jenkins 비교","CI 모니터링 AI 에이전트 설정 가이드","빌드를 최적화하는 방법","CI 모니터링 AI 에이전트의 장점"],"es":["cómo usar ci-monitor","herramientas de agente de inteligencia artificial","alternativas a ci-monitor","ci-monitor vs Jenkins","instalación de ci-monitor","guía de configuración de ci-monitor"],"fr":["comment utiliser ci-monitor","outils d''agent d''intelligence artificielle","alternatives à ci-monitor","ci-monitor vs Jenkins","installation de ci-monitor","guide de configuration de ci-monitor"],"de":["wie man ci-monitor verwendet","KI-Agent-Tools","Alternativen zu ci-monitor","ci-monitor vs Jenkins","Installation von ci-monitor","Konfigurationsanleitung für ci-monitor"],"pt":["como usar ci-monitor","o que é ci-monitor","ci-monitor alternative","ci-monitor vs Jenkins","instalar ci-monitor","guia de configuração do ci-monitor"],"ru":["как использовать ci-monitor","что такое ci-monitor","альтернативы ci-monitor","ci-monitor vs Jenkins","установка ci-monitor","руководство по настройке ci-monitor"],"ar":["كيفية استخدام ci-monitor","ما هو ci-monitor","بديل ci-monitor","ci-monitor مقابل Jenkins","تثبيت ci-monitor","دليل إعداد ci-monitor"]}},"owner":"nrwl","repo":"nx","repoPath":"nrwl/nx","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.889Z","topics":[],"category":"community","skillMd":{"name":"ci-monitor","description":"Monitor Nx Cloud CI pipeline and handle self-healing fixes automatically. Checks for Nx Cloud connection before starting.","bodyPreview":"# CI Monitor Command\n\nYou are the orchestrator for monitoring Nx Cloud CI pipeline executions and handling self-healing fixes. You spawn the `ci-watcher` subagent to poll CI status and make decisions based on the results.\n\n## Context\n\n- **Current Branch:** !`git branch --show-current`\n- **Current Commit:** !`git rev-parse --short HEAD`\n- **Remote Status:** !`git status -sb | head -1`\n\n## User Instructions\n\n$ARGUMENTS\n\n**Important:** If user provides specific instructions, respect them over defau","body":"# CI Monitor Command\n\nYou are the orchestrator for monitoring Nx Cloud CI pipeline executions and handling self-healing fixes. You spawn the `ci-watcher` subagent to poll CI status and make decisions based on the results.\n\n## Context\n\n- **Current Branch:** !`git branch --show-current`\n- **Current Commit:** !`git rev-parse --short HEAD`\n- **Remote Status:** !`git status -sb | head -1`\n\n## User Instructions\n\n$ARGUMENTS\n\n**Important:** If user provides specific instructions, respect them over default behaviors described below.\n\n## Configuration Defaults\n\n| Setting                   | Default       | Description                                                         |\n| ------------------------- | ------------- | ------------------------------------------------------------------- |\n| `--max-cycles`            | 10            | Maximum CIPE cycles before timeout                                  |\n| `--timeout`               | 120           | Maximum duration in minutes                                         |\n| `--verbosity`             | medium        | Output level: minimal, medium, verbose                              |\n| `--branch`                | (auto-detect) | Branch to monitor                                                   |\n| `--subagent-timeout`      | 60            | Subagent polling timeout in minutes                                 |\n| `--fresh`                 | false         | Ignore previous context, start fresh                                |\n| `--auto-fix-workflow`     | false         | Attempt common fixes for pre-CIPE failures (e.g., lockfile updates) |\n| `--new-cipe-timeout`      | 10            | Minutes to wait for new CIPE after action                           |\n| `--local-verify-attempts` | 3             | Max local verification + enhance cycles before pushing to CI        |\n\nParse any overrides from `$ARGUMENTS` and merge with defaults.\n\n## Nx Cloud Connection Check\n\n**CRITICAL**: Before starting the monitoring loop, verify the workspace is connected to Nx Cloud.\n\n### Step 0: Verify Nx Cloud Connection\n\n1. **Check `nx.json`** at workspace root for `nxCloudId` or `nxCloudAccessToken`\n2. **If `nx.json` missing OR neither property exists** → exit with:\n   ```\n   [ci-monitor] Nx Cloud not connected. Unlock 70% faster CI and auto-fix broken PRs with https://nx.dev/nx-cloud\n   ```\n3. **If connected** → continue to main loop\n\n## Session Context Behavior\n\n**Important:** Within a Claude Code session, conversation context persists. If you Ctrl+C to interrupt the monitor and re-run `/ci-monitor`, Claude remembers the previous state and may continue from where it left off.\n\n- **To continue monitoring:** Just re-run `/ci-monitor` (context is preserved)\n- **To start fresh:** Use `/ci-monitor --fresh` to ignore previous context\n- **For a completely clean slate:** Exit Claude Code and restart `claude`\n\n## Default Behaviors by Status\n\nThe subagent returns with one of the following statuses. This table defines the **default behavior** for each status. User instructions can override any of these.\n\n| Status              | Default Behavior                                                                                                                                                  |\n| ------------------- | ----------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| `ci_success`        | Exit with success. Log \"CI passed successfully!\"                                                                                                                  |\n| `fix_auto_applying` | Fix will be auto-applied by self-healing. Do NOT call MCP. Record `last_cipe_url`, spawn new subagent in wait mode to poll for new CIPE.                          |\n| `fix_available`     | Compare `failedTaskIds` vs `verifiedTaskIds` to determine verification state. See **Fix Available Decision Logic** section below.                                 |\n| `fix_failed`        | Self-healing failed to generate fix. Attempt local fix based on `taskOutputSummary`. If successful → commit, push, loop. If not → exit with failure.              |\n| `environment_issue` | Call MCP to request rerun: `update_self_healing_fix({ shortLink, action: \"RERUN_ENVIRONMENT_STATE\" })`. New CIPE spawns automatically. Loop to poll for new CIPE. |\n| `no_fix`            | CI failed, no fix available (self-healing disabled or not executable). Attempt local fix if possible. Otherwise exit with failure.                                |\n| `no_new_cipe`       | Expected CIPE never spawned (CI workflow likely failed before Nx tasks). Report to user, attempt common fixes if configured, or exit with guidance.               |\n| `polling_timeout`   | Subagent polling timeout reached. Exit with timeout.                                                                                                              |\n| `cipe_canceled`     | CIPE was canceled. Exit with canceled status.                                                                                                                     |\n| `cipe_timed_out`    | CIPE timed out. Exit with timeout status.                                                                                                                         |\n| `error`             | Increment `no_progress_count`. If >= 3 → exit with circuit breaker. Otherwise wait 60s and loop.                                                                  |\n\n### Fix Available Decision Logic\n\nWhen subagent returns `fix_available`, main agent compares `failedTaskIds` vs `verifiedTaskIds`:\n\n#### Step 1: Categorize Tasks\n\n1. **Verified tasks** = tasks in both `failedTaskIds` AND `verifiedTaskIds`\n2. **Unverified tasks** = tasks in `failedTaskIds` but NOT in `verifiedTaskIds`\n3. **E2E tasks** = unverified tasks where target contains \"e2e\" (task format: `<project>:<target>` or `<project>:<target>:<config>`)\n4. **Verifiable tasks** = unverified tasks that are NOT e2e\n\n#### Step 2: Determine Path\n\n| Condition                               | Path                                     |\n| --------------------------------------- | ---------------------------------------- |\n| No unverified tasks (all verified)      | Apply via MCP                            |\n| Unverified tasks exist, but ALL are e2e | Apply via MCP (treat as verified enough) |\n| Verifiable tasks exist                  | Local verification flow                  |\n\n#### Step 3a: Apply via MCP (fully/e2e-only verified)\n\n- Call `update_self_healing_fix({ shortLink, action: \"APPLY\" })`\n- Record `last_cipe_url`, spawn subagent in wait mode\n\n#### Step 3b: Local Verification Flow\n\nWhen verifiable (non-e2e) unverified tasks exist:\n\n1. **Detect package manager:**\n   - `pnpm-lock.yaml` exists → `pnpm nx`\n   - `yarn.lock` exists → `yarn nx`\n   - Otherwise → `npx nx`\n\n2. **Run verifiable tasks in parallel:**\n   - Spawn `general` subagents to run each task concurrently\n   - Each subagent runs: `<pm> nx run <taskId>`\n   - Collect pass/fail results from all subagents\n\n3. **Evaluate results:**\n\n| Result                    | Action                       |\n| ------------------------- | ---------------------------- |\n| ALL verifiable tasks pass | Apply via MCP                |\n| ANY verifiable task fails | Apply-locally + enhance flow |\n\n4. **Apply-locally + enhance flow:**\n   - Run `nx apply-locally <shortLink>`\n   - Enhance the code to fix failing tasks\n   - Run failing tasks again to verify fix\n   - If still failing → increment `local_verify_count`, loop back to enhance\n   - If passing → commit and push, record `expected_commit_sha`, spawn subagent in wait mode\n\n5. **Track attempts** (wraps step 4):\n   - Increment `local_verify_count` after each enhance cycle\n   - If `local_verify_count >= local_verify_attempts` (default: 3):\n     - Get code in commit-able state\n     - Commit and push with message indicating local verification failed\n     - Report to user:\n       ```\n       [ci-monitor] Local verification failed after <N> attempts. Pushed to CI for final validation. Failed: <taskIds>\n       ```\n     - Record `expected_commit_sha`, spawn subagent in wait mode (let CI be final judge)\n\n#### Commit Message Format\n\n```bash\ngit commit -m \"fix(<projects>): <brief description>\n\nFailed tasks: <taskId1>, <taskId2>\nLocal verification: passed|enhanced|failed-pushing-to-ci\"\n```\n\n### Unverified Fix Flow (No Verification Attempted)\n\nWhen `verificationStatus` is `FAILED`, `NOT_EXECUTABLE`, or fix has `couldAutoApplyTasks != true` with no verification:\n\n- Analyze fix content (`suggestedFix`, `suggestedFixReasoning`, `taskOutputSummary`)\n- If fix looks correct → apply via MCP\n- If fix needs enhancement → use Apply Locally + Enhance Flow above\n- If fix is wrong → reject via MCP, fix from scratch, commit, push\n\n### Auto-Apply Eligibility\n\nThe `couldAutoApplyTasks` field indicates whether the fix is eligible for automatic application:\n\n- **`true`**: Fix is eligible for auto-apply. Subagent keeps polling while verification is in progress. Returns `fix_auto_applying` when verified, or `fix_available` if verification fails.\n- **`false`** or **`null`**: Fix requires manual action (apply via MCP, apply locally, or reject)\n\n**Key point**: When subagent returns `fix_auto_applying`, do NOT call MCP to apply - self-healing handles it. Just spawn a new subagent in wait mode.\n\n### Apply vs Reject vs Apply Locally\n\n- **Apply via MCP**: Calls `update_self_healing_fix({ shortLink, action: \"APPLY\" })`. Self-healing agent applies the fix in CI and a new CIPE spawns automatically. No local git operations needed.\n- **Apply Locally**: Runs `nx apply-locally <shortLink>`. Applies the patch to your local working directory and sets state to `APPLIED_LOCALLY`. Use this when you want to enhance the fix before pushing.\n- **Reject via MCP**: Calls `update_self_healing_fix({ shortLink, action: \"REJECT\" })`. Marks fix as rejected. Use only when the fix is completely wrong and you''ll fix from scratch.\n\n### Apply Locally + Enhance Flow\n\nWhen the fix needs enhancement (use `nx apply-locally`, NOT reject):\n\n1. Apply the patch locally: `nx apply-locally <shortLink>` (this also updates state to `APPLIED_LOCALLY`)\n2. Make additional changes as needed\n3. Commit and push:\n   ```bash\n   git add -A\n   git commit -m \"fix: resolve <failedTaskIds>\"\n   git push origin $(git branch --show-current)\n   ```\n4. Loop to poll for new CIPE\n\n### Reject + Fix From Scratch Flow\n\nWhen the fix is completely wrong:\n\n1. Call MCP to reject: `update_self_healing_fix({ shortLink, action: \"REJECT\" })`\n2. Fix the issue from scratch locally\n3. Commit and push:\n   ```bash\n   git add -A\n   git commit -m \"fix: resolve <failedTaskIds>\"\n   git push origin $(git branch --show-current)\n   ```\n4. Loop to poll for new CIPE\n\n### Environment Issue Handling\n\nWhen `failureClassification == ''ENVIRONMENT_STATE''`:\n\n1. Call MCP to request rerun: `update_self_healing_fix({ shortLink, action: \"RERUN_ENVIRONMENT_STATE\" })`\n2. New CIPE spawns automatically (no local git operations needed)\n3. Loop to poll for new CIPE with `previousCipeUrl` set\n\n### No-New-CIPE Handling\n\nWhen `status == ''no_new_cipe''`:\n\nThis means the expected CIPE was never created - CI likely failed before Nx tasks could run.\n\n1. **Report to user:**\n\n   ```\n   [ci-monitor] No CI attempt for <sha> after 10 min. Check CI provider for pre-Nx failures (install, checkout, auth). Last CI attempt: <previousCipeUrl>\n   ```\n\n2. **If user configured auto-fix attempts** (e.g., `--auto-fix-workflow`):\n   - Detect package manager: check for `pnpm-lock.yaml`, `yarn.lock`, `package-lock.json`\n   - Run install to update lockfile:\n     ```bash\n     pnpm install   # or npm install / yarn install\n     ```\n   - If lockfile changed:\n     ```bash\n     git add pnpm-lock.yaml  # or appropriate lockfile\n     git commit -m \"chore: update lockfile\"\n     git push origin $(git branch --show-current)\n     ```\n   - Record new commit SHA, loop to poll with `expectedCommitSha`\n\n3. **Otherwise:** Exit with `no_new_cipe` status, providing guidance for user to investigate\n\n## Exit Conditions\n\nExit the monitoring loop when ANY of these conditions are met:\n\n| Condition                                   | Exit Type        |\n| ------------------------------------------- | ---------------- |\n| CI passes (`cipeStatus == ''SUCCEEDED''`)     | Success          |\n| Max CIPE cycles reached                     | Timeout          |\n| Max duration reached                        | Timeout          |\n| 3 consecutive no-progress iterations        | Circuit breaker  |\n| No fix available and local fix not possible | Failure          |\n| No new CIPE and auto-fix not configured     | Pre-CIPE failure |\n| User cancels                                | Cancelled        |\n\n## Main Loop\n\n### Step 1: Initialize Tracking\n\n```\ncycle_count = 0\nstart_time = now()\nno_progress_count = 0\nlocal_verify_count = 0\nlast_state = null\nlast_cipe_url = null\nexpected_commit_sha = null\n```\n\n### Step 2: Spawn Subagent\n\nSpawn the `ci-watcher` subagent to poll CI status:\n\n**Fresh start (first spawn, no expected CIPE):**\n\n```\nTask(\n  agent: \"ci-watcher\",\n  prompt: \"Monitor CI for branch ''<branch>''.\n           Subagent timeout: <subagent-timeout> minutes.\n           New-CIPE timeout: <new-cipe-timeout> minutes.\n           Verbosity: <verbosity>.\"\n)\n```\n\n**After action that triggers new CIPE (wait mode):**\n\n```\nTask(\n  agent: \"ci-watcher\",\n  prompt: \"Monitor CI for branch ''<branch>''.\n           Subagent timeout: <subagent-timeout> minutes.\n           New-CIPE timeout: <new-cipe-timeout> minutes.\n           Verbosity: <verbosity>.\n\n           WAIT MODE: A new CIPE should spawn. Ignore old CIPE until new one appears.\n           Expected commit SHA: <expected_commit_sha>\n           Previous CIPE URL: <last_cipe_url>\"\n)\n```\n\n### Step 3: Handle Subagent Response\n\nWhen subagent returns:\n\n1. Check the returned status\n2. Look up default behavior in the table above\n3. Check if user instructions override the default\n4. Execute the appropriate action\n5. **If action expects new CIPE**, update tracking (see Step 3a)\n6. If action results in looping, go to Step 2\n\n### Step 3a: Track State for New-CIPE Detection\n\nAfter actions that should trigger a new CIPE, record state before looping:\n\n| Action                        | What to Track                                 | Subagent Mode |\n| ----------------------------- | --------------------------------------------- | ------------- |\n| Fix auto-applying             | `last_cipe_url = current cipeUrl`             | Wait mode     |\n| Apply via MCP                 | `last_cipe_url = current cipeUrl`             | Wait mode     |\n| Apply locally + push          | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| Reject + fix + push           | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| Fix failed + local fix + push | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| No fix + local fix + push     | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n| Environment rerun             | `last_cipe_url = current cipeUrl`             | Wait mode     |\n| No-new-CIPE + auto-fix + push | `expected_commit_sha = $(git rev-parse HEAD)` | Wait mode     |\n\n**CRITICAL**: When passing `expectedCommitSha` or `last_cipe_url` to the subagent, it enters **wait mode**:\n\n- Subagent will **completely ignore** the old/stale CIPE\n- Subagent will only wait for new CIPE to appear\n- Subagent will NOT return to main agent with stale CIPE data\n- Once new CIPE detected, subagent switches to normal polling\n\n**Why wait mode matters for context preservation**: Stale CIPE data can be very large (task output summaries, suggested fix patches, reasoning). If subagent returns this to main agent, it pollutes main agent''s context with useless data since we already processed that CIPE. Wait mode keeps stale data in the subagent, never sending it to main agent.\n\n### Step 4: Progress Tracking\n\nAfter each action:\n\n- If state changed significantly → reset `no_progress_count = 0`\n- If state unchanged → `no_progress_count++`\n- On new CI attempt detected → reset `local_verify_count = 0`\n\n## Status Reporting\n\nBased on verbosity level:\n\n| Level     | What to Report                                                             |\n| --------- | -------------------------------------------------------------------------- |\n| `minimal` | Only final result (success/failure/timeout)                                |\n| `medium`  | State changes + periodic updates (\"Cycle N \\| Elapsed: Xm \\| Status: ...\") |\n| `verbose` | All of medium + full subagent responses, git outputs, MCP responses        |\n\n## User Instruction Examples\n\nUsers can override default behaviors:\n\n| Instruction                                      | Effect                                        |\n| ------------------------------------------------ | --------------------------------------------- |\n| \"never auto-apply\"                               | Always prompt before applying any fix         |\n| \"always ask before git push\"                     | Prompt before each push                       |\n| \"reject any fix for e2e tasks\"                   | Auto-reject if `failedTaskIds` contains e2e   |\n| \"apply all fixes regardless of verification\"     | Skip verification check, apply everything     |\n| \"if confidence < 70, reject\"                     | Check confidence field before applying        |\n| \"run ''nx affected -t typecheck'' before applying\" | Add local verification step                   |\n| \"auto-fix workflow failures\"                     | Attempt lockfile updates on pre-CIPE failures |\n| \"wait 45 min for new CIPE\"                       | Override new-CIPE timeout (default: 10 min)   |\n\n## Error Handling\n\n| Error                    | Action                                                                                |\n| ------------------------ | ------------------------------------------------------------------------------------- |\n| Git rebase conflict      | Report to user, exit                                                                  |\n| `nx apply-locally` fails | Report to user, attempt manual patch or exit                                          |\n| MCP tool error           | Retry once, if fails report to user                                                   |\n| Subagent spawn failure   | Retry once, if fails exit with error                                                  |\n| No new CIPE detected     | If `--auto-fix-workflow`, try lockfile update; otherwise report to user with guidance |\n| Lockfile auto-fix fails  | Report to user, exit with guidance to check CI logs                                   |\n\n## Example Session\n\n### Example 1: Normal Flow with Self-Healing (medium verbosity)\n\n```\n[ci-monitor] Starting CI monitor for branch ''feature/add-auth''\n[ci-monitor] Config: max-cycles=5, timeout=120m, verbosity=medium\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] CI attempt: IN_PROGRESS | Self-Healing: NOT_STARTED | Elapsed: 1m\n[CI Monitor] CI attempt: FAILED | Self-Healing: IN_PROGRESS | Elapsed: 3m\n[CI Monitor] CI attempt: FAILED | Self-Healing: COMPLETED | Elapsed: 5m\n\n[ci-monitor] Fix available! Verification: COMPLETED\n[ci-monitor] Applying fix via MCP...\n[ci-monitor] Fix applied in CI. Waiting for new CI attempt...\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] New CI attempt detected!\n[CI Monitor] CI attempt: SUCCEEDED | Elapsed: 8m\n\n[ci-monitor] CI passed successfully!\n\n[ci-monitor] Summary:\n  - Total cycles: 2\n  - Total time: 12m 34s\n  - Fixes applied: 1\n  - Result: SUCCESS\n```\n\n### Example 2: Pre-CI Failure (medium verbosity)\n\n```\n[ci-monitor] Starting CI monitor for branch ''feature/add-products''\n[ci-monitor] Config: max-cycles=5, timeout=120m, auto-fix-workflow=true\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] CI attempt: FAILED | Self-Healing: COMPLETED | Elapsed: 2m\n\n[ci-monitor] Applying fix locally, enhancing, and pushing...\n[ci-monitor] Committed: abc1234\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] Waiting for new CI attempt... (expected SHA: abc1234)\n[CI Monitor] ⚠️  CI attempt timeout (10 min). Returning no_new_cipe.\n\n[ci-monitor] Status: no_new_cipe\n[ci-monitor] --auto-fix-workflow enabled. Attempting lockfile update...\n[ci-monitor] Lockfile updated. Committed: def5678\n\n[ci-monitor] Spawning subagent to poll CI status...\n[CI Monitor] New CI attempt detected!\n[CI Monitor] CI attempt: SUCCEEDED | Elapsed: 18m\n\n[ci-monitor] CI passed successfully!\n\n[ci-monitor] Summary:\n  - Total cycles: 3\n  - Total time: 22m 15s\n  - Fixes applied: 1 (self-healing) + 1 (lockfile)\n  - Result: SUCCESS\n```\n"},"lastSynced":"2026-03-04T14:54:05.759Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated CI pipeline monitoring and self-healing capabilities.","zh":"适用于需要自动化CI管道监控和自愈能力的DevOps代理。","ja":"DevOpsエージェントが自動化されたCIパイプラインの監視と自己回復機能を必要とする場合に最適です。","ko":"자동화된 CI 파이프라인 모니터링 및 자가 치유 기능을 필요로 하는 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren monitoreo automatizado de pipelines de CI y capacidades de autoreparación.","fr":"Idéal pour les agents DevOps nécessitant un monitoring automatique de pipeline CI et des capacités d''auto-réparation.","de":"Ideal für DevOps-Agents, die ein automatisiertes Monitoring von CI-Pipelines und Selbstheilungsfähigkeiten erfordern.","pt":"Ideal para agentes DevOps que exigem monitoramento automatizado de pipeline de CI e capacidades de autocura.","ru":"Идеально подходит для агентов DevOps, требующих автоматизированного мониторинга конвейера CI и возможностей самоисцеления.","ar":"مثالي لعميل DevOps الذي يتطلب مراقبة تلقائية لأنابيب CI وقدرات الشفاء الذاتي."},"recommendation":{"en":"Empowers agents to monitor Nx Cloud CI pipeline executions, poll CI status, and make decisions based on the results using the `ci-watcher` subagent, leveraging Git commands like `git branch`, `git rev-parse`, and `git status` for comprehensive analysis.","zh":"赋予代理监控Nx Cloud CI管道执行，轮询CI状态，并使用`ci-watcher`子代理根据结果做出决定，利用Git命令如`git branch`、`git rev-parse`和`git status`进行综合分析。","ja":"エージェントにNx Cloud CIパイプラインの実行を監視し、CIステータスをポーリングし、`ci-watcher`サブエージェントを使用して結果に基づいて決定を下すことを可能にし、`git branch`、`git rev-parse`、`git status`などのGitコマンドを使用して包括的な分析を行います。","ko":"에이전트가 Nx Cloud CI 파이프라인 실행을 모니터링하고 CI 상태를 폴링하며 `ci-watcher` 서브 에이전트를 사용하여 결과를 기반으로 결정을 내리며, `git branch`, `git rev-parse`, `git status` 등의 Git 명령을 사용하여 전체적인 분석을 수행할 수 있습니다.","es":"Habilita a los agentes a monitorear las ejecuciones de pipelines de CI de Nx Cloud, sondear el estado de CI y tomar decisiones basadas en los resultados utilizando el subagente `ci-watcher`, aprovechando comandos de Git como `git branch`, `git rev-parse` y `git status` para un análisis exhaustivo.","fr":"Permet aux agents de surveiller les exécutions de pipeline CI de Nx Cloud, d''interroger l''état de CI et de prendre des décisions basées sur les résultats en utilisant le sous-agent `ci-watcher`, en exploitant des commandes Git comme `git branch`, `git rev-parse` et `git status` pour une analyse exhaustive.","de":"Ermächtigt die Agenten, die Ausführungen von CI-Pipelines von Nx Cloud zu überwachen, den CI-Status abzufragen und Entscheidungen basierend auf den Ergebnissen zu treffen, indem sie den Subagenten `ci-watcher` verwenden, der Git-Befehle wie `git branch`, `git rev-parse` und `git status` für eine umfassende Analyse nutzt.","pt":"Habilita os agentes a monitorar execuções de pipeline de CI do Nx Cloud, sondar o status do CI e tomar decisões com base nos resultados usando o subagente `ci-watcher`, aproveitando comandos Git como `git branch`, `git rev-parse` e `git status` para análise abrangente.","ru":"Наделяет агентов возможностью мониторить выполнение конвейера CI Nx Cloud, опрашивать статус CI и принимать решения на основе результатов с помощью субагента `ci-watcher`, используя команды Git, такие как `git branch`, `git rev-parse` и `git status`, для всестороннего анализа.","ar":"تمكين الوكلاء من مراقبة تنفيذ أنابيب CI السحابية Nx ، واستطلاع حالة CI ، واتخاذ القرارات بناءً على النتائج باستخدام وكلاء فرعيين `ci-watcher` ، و الاستفادة من أوامر Git مثل `git branch` ، `git rev-parse` و `git status` لتحليل شامل."},"useCases":{"en":["Automating CI pipeline monitoring","Debugging failed PRs using automatic self-healing fixes","Optimizing build processes with Nx"],"zh":["自动化CI管道监控","使用自动化自愈修复来调试失败的PR","使用Nx优化构建过程"],"ja":["CIパイプラインの監視を自動化する","自動化された自己回復による失敗したPRのデバッグ","Nxを使用したビルドプロセスの最適化"],"ko":["CI 파이프라인 모니터링 자동화","자동 자가 치유를 통해 실패한 PR 디버깅","Nx를 사용한 빌드 프로세스 최적화"],"es":["Automatización del monitoreo de pipelines de CI","Depuración de PR fallidas utilizando correcciones de autoreparación automáticas","Optimización de procesos de compilación con Nx"],"fr":["Automatisation du monitoring de pipeline CI","Débogage de PR échouées en utilisant des corrections de auto-réparation automatiques","Optimisation des processus de construction avec Nx"],"de":["Automatisierung des Monitorings von CI-Pipelines","Fehlerbehebung fehlgeschlagener PRs unter Verwendung automatischer Selbstheilungsmaßnahmen","Optimierung von Build-Prozessen mit Nx"],"pt":["Automatizar monitoramento de pipeline de CI","Depurar PRs com falhas usando correções de autocura automática","Otimizar processos de compilação com Nx"],"ru":["Автоматизировать мониторинг конвейера CI","Отладить неудавшиеся PR с помощью автоматических исправлений самоисцеления","Оптимизировать процессы сборки с помощью Nx"],"ar":["تأتمتة مراقبة أنابيب CI","تصحيح PRs الفاشلة باستخدام إصلاحات الشفاء الذاتي التلقائية","تحسين عمليات البناء مع Nx"]},"limitations":{"en":["Requires Nx Cloud setup","Dependent on Git for version control","Limited to CI pipeline executions within the Nx ecosystem"],"zh":["需要Nx Cloud设置","依赖于Git进行版本控制","仅限于Nx生态系统内的CI管道执行"],"ja":["Nx Cloudの設定が必要","バージョン管理にGitに依存する","Nxエコシステム内のCIパイプラインの実行のみ"],"ko":["Nx Cloud 설정이 필요합니다","버전 관리에 Git에 의존합니다","Nx 생태계 내의 CI 파이프ライン 실행만 해당"],"es":["Requiere configuración de Nx Cloud","Dependiente de Git para el control de versiones","Limitado a las ejecuciones de pipelines de CI dentro del ecosistema de Nx"],"fr":["Nécessite une configuration de Nx Cloud","Dépendant de Git pour le contrôle de version","Limité aux exécutions de pipeline CI au sein de l''écosystème Nx"],"de":["Benötigt Nx Cloud-Konfiguration","Von Git für die Versionskontrolle abhängig","Begrenzt auf CI-Pipeline-Ausführungen innerhalb des Nx-Ökosystems"],"pt":["Exige configuração do Nx Cloud","Dependente do Git para controle de versão","Limitado a execuções de pipeline de CI dentro do ecossistema Nx"],"ru":["Требует настройки Nx Cloud","Зависит от Git для контроля версий","Ограничен выполнением конвейера CI внутри экосистемы Nx"],"ar":["يتطلب إعداد Nx السحابي","يعتمد على Git للتحكم في الإصدار","محدود بتنفيذ أنابيب CI داخل نظام Nx"]},"version":3},"contentHash":"a124ec3b3bd0e12152c9729b1239df7f69da2321c3a4d8be2014943056d3f6b6","qualityScore":45}');
