INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('saeed-vayghan/mitra/workflow-loader', 'workflow-loader', 'saeed-vayghan', 'mitra', 'community', 'workflow-loader saeed-vayghan mitra community Mitra是一个多智能体集体智能系统，通过专门的AI人物实现协作问题解决 Mitraは、専門のAIパーソナを通じて共同問題解決を実現するマルチエージェント集団知能システム Mitra는 협作 문제 해결을 위한 전문 AI 인물을 통해 多智能体集体智能システム Mitra es un sistema de inteligencia colectiva multiagente que facilita la resolución de problemas colaborativos a través de personalidades de IA especializadas. Mitra est un système d''intelligence collective multiagent qui facilite la résolution de problèmes collaboratifs via des personnalités IA spécialisées. Mitra ist ein multiagentenes System der kollektiven Intelligenz, das die kollaborative Problemlösung durch spezialisierte KI-Persönlichkeiten erleichtert. O workflow-loader é uma ferramenta de IA que facilita a resolução de problemas em equipe Workflow-loader - это инструмент ИИ, предназначенный для коллективного решения проблем workflow-loader هو أداة ذكاء اصطناعي مصممة للعمل الجماعي لحل المشكلات Mitra is a multi-agent collective intelligence system designed to facilitate collaborative problem-solving through specialized AI personas. AI智能代理 workflow-loader Mitra 集体智能系统 协作问题解决 AI工具 如何使用workflow-loader workflow-loader安装 Mitra替代品 Mitra is a multi-agent collective intelligence system designed to facilitate collaborative problem-solving through specialized AI personas.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('simplefarmer69/ape-claw/ape-claw', 'community', 'simplefarmer69', 'ape-claw', 'simplefarmer69/ape-claw', 'ape-claw', 0, 0, 45, '2026-03-04T13:07:01.934Z', '2026-03-04T15:08:31.943Z', 'f74ffe5248ddfcfbb323988569a1f2b94f639357346da88b9ca4b26da4d5d690', '{"id":"simplefarmer69/ape-claw/ape-claw","name":"ape-claw","description":{"zh":"Ape Claw 是一个安全的CLI + OpenClaw技能，用于ApeChain NFT操作，提供发现、报价、模拟、购买和桥接功能","ja":"Ape Clawは安全なCLI + OpenClawスキルで、ApeChain NFT操作をサポートします","ko":"Ape Claw는 안전한 CLI + OpenClaw 스킬로 ApeChain NFT 운영을 지원합니다","es":"Ape Claw es una herramienta de AI Agent que proporciona operaciones NFT seguras con CLI y OpenClaw","fr":"Ape Claw est un outil d''Agent IA qui fournit des opérations NFT sécurisées avec CLI et OpenClaw","de":"Ape Claw ist ein KI-Agent-Tool, das sichere NFT-Operationen mit CLI und OpenClaw bietet","pt":"O Ape Claw é uma ferramenta de segurança para operações NFT em ApeChain, oferecendo recursos de descoberta de coleções, listagem, cotação, simulação e compra com guardrails de políticas e telemetria estruturada","ru":"ИИ Агент Ape Claw - это безопасный инструмент для операций NFT в ApeChain, предоставляющий функции обнаружения коллекций, списков, котировок, симуляции и покупки с политическими ограничениями и структурированной телеметрией","ar":"أداة الأپ كلAW هي أداة أمنية لعمليات NFT على سلاسل الأپ، توفر ميزات اكتشاف المجموعات والقوائم والتسعير والتحاكي وعمليات الشراء مع حواجز سياسات وتيليمетري منظم","en":"Ape Claw is a safety-first CLI + OpenClaw skill for ApeChain NFT operations: discover collections/listings, quote/simulate/buy flows, and bridge quote/execute/status with policy guardrails, allowlist enforcement, structured telemetry, and a live dashboard for agent activity."},"seo":{"title":{"zh":"Ape Claw AI工具：安全的NFT操作","ja":"Ape Claw AIエージェント：安全なNFT操作","ko":"Ape Claw AI 에이전트: 안전한 