INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pkuppens/on_prem_rag/api-design', 'api-design', 'pkuppens', 'on_prem_rag', 'community', 'api-design pkuppens on_prem_rag community 本地RAG解决方案允许您安全地与文档和数据交互，无需云端担忧。使用AI智能代理简化您的工作流程 オンプレミスRAGソリューションを使用して、クラウドの心配なく安全に文書やデータと対話。AIエージェントでワークフローを簡素化 온프레미스 RAG 솔루션을 사용하여 클라우드 걱정 없이 안전하게 문서와 데이터와 대화。AI 에이전트로 워크플ロー簡素化 La solución RAG de diseño de API permite interactuar con documentos y datos de forma segura y sin dependencia de la Cloud La solution RAG de conception d''API permet d''interagir avec des documents et des données de manière sécurisée et sans dépendance du Cloud Die On-Premises RAG-Lösung für API-Design ermöglicht die sichere Interaktion mit Dokumenten und Daten ohne Cloud-Abhängigkeit A solução RAG On-Premises permite que os desenvolvedores criem APIs sem dependência da nuvem, garantindo a segurança e o controle dos dados Локальное решение RAG позволяет разработчикам создавать API без облачных хранилищ, обеспечивая безопасность и контроль данных حل RAG على الموقع يسمح للمطورين بإنشاء واجهات برمجة التطبيقات بدون اعتماد على السحابة، مما يضمن أمان البيانات وسيطرتها On-Premises RAG Solution: Talk with your documents and data without the Cloud concerns AI智能代理 本地RAG解决方案 API设计 如何使用AI智能代理 API设计工具 本地RAG解决方案安装 API设计和构建 On-Premises RAG Solution: Talk with your documents and data without the Cloud concerns');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MythologIQ/Zo-Qore/vercel-composition-patterns', 'community', 'MythologIQ', 'Zo-Qore', 'MythologIQ/Zo-Qore', 'vercel-composition-patterns', 0, 0, 44, '2026-02-24T18:00:55Z', '2026-02-26T13:17:04.548Z', '2a0efb55f7933cf9fe23585d0874abc60ef088b8e22a2168c5704466c89a71e4', '{"id":"MythologIQ/Zo-Qore/vercel-composition-patterns","name":"vercel-composition-patterns","description":{"zh":"Vercel 组合模式是一种用于构建原生集成的 AI 智能代理，具有 Agentic Mesh 和 Qorelogic 治理","ja":"Vercel コンポジションパターンは、ネイティブ統合の AI エージェントを構築するための方法です","ko":"Vercel 컴포지션 패턴은 네이티브 통합 AI 에이전트를 구축하는 데 사용됩니다","es":"El patrón de composición de Vercel permite una integración nativa con Zo.computer y Agentic Mesh con capacidades de gobernanza de Qorelogic","fr":"Le modèle de composition Vercel permet une intégration native avec Zo.computer et Agentic Mesh avec des capacités de gouvernance Qorelogic","de":"Das Vercel-Zusammensetzungs-Muster ermöglicht eine native Integration mit Zo.computer und Agentic Mesh mit Qorelogic-Governance-Funktionen","pt":"O Vercel-composition-patterns é um agente de IA que utiliza Agentic Mesh e Qorelogic para integração nativa com Zo.computer","ru":"Vercel-composition-patterns - это ИИ агент, который использует Agentic Mesh и Qorelogic для родной интеграции с Zo.computer","ar":"Vercel-composition-patterns هو وكيل ذكي يستخدم Agentic Mesh و Qorelogic للدمج الأصلي مع Zo.computer","en":"Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer"},"seo":{"title":{"zh":"Vercel 组合模式 - AI智能代理","ja":"Vercel コンポジションパターン - AIエージェント","ko":"Vercel 컴포지션 패턴 - AI 에이전트","es":"Patrones de composición de Vercel para Agentes de IA","fr":"Modèles de composition Vercel pour les outils d''IA","de":"Vercel-Zusammensetzungs-Muster für KI-Agents","pt":"Padrões de Composição Vercel para Agentes de IA","ru":"ИИ Агенты: Шаблоны Комpositions Vercel","ar":"نماذج تركيبية Vercel للوكلاء الذكيين","en":"vercel-composition-patterns"},"description":{"zh":"Vercel 组合模式是一种用于构建原生集成的 AI 智能代理，具有 Agentic Mesh 和 Qorelogic 治理","ja":"Vercel コンポジションパターンは、ネイティブ統合の AI エージェントを構築するための方法です","ko":"Vercel 컴포지션 패턴은 네이티브 통합 AI 에이전트를 구축하는 데 사용됩니다","es":"El patrón de composición de Vercel permite una integración nativa con Zo.computer y Agentic Mesh con capacidades de gobernanza de Qorelogic","fr":"Le modèle de composition Vercel permet une intégration native avec Zo.computer et Agentic Mesh avec des capacités de gouvernance Qorelogic","de":"Das Vercel-Zusammensetzungs-Muster ermöglicht eine native Integration mit Zo.computer und Agentic Mesh mit Qorelogic-Governance-Funktionen","pt":"O Vercel-composition-patterns é um agente de IA que utiliza Agentic Mesh e Qorelogic para integração nativa com Zo.computer","ru":"Vercel-composition-patterns - это ИИ агент, который использует Agentic Mesh и Qorelogic для родной интеграции с Zo.computer","ar":"Vercel-composition-patterns هو وكيل ذكي يستخدم Agentic Mesh و Qorelogic للدمج الأصلي مع Zo.computer","en":"Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer"},"definition":{"en":"Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer"},"features":{"zh":["Agentic Mesh 集成","Qorelogic 治理","原生集成支持","递归学习协议","Zo.computer 支持"],"ja":["Agentic Mesh 統合","Qorelogic ガバナンス","ネイティブ統合サポート","再帰学習プロトコル","Zo.computer サポート"],"ko":["Agentic Mesh 통합","Qorelogic 거버넌스","네이티브 통합 지원","재귀 학습 프로토콜","Zo.computer 지원"],"es":["Integración nativa con Zo.computer","Capacidades de gobernanza de Qorelogic","Protocolo de aprendizaje recursivo","Agentic Mesh para desarrollo de Agentes de IA","Compatibilidad con Agent OS"],"fr":["Intégration native avec Zo.computer","Capacités de gouvernance Qorelogic","Protocole d''apprentissage récursif","Agentic Mesh pour le développement d''outils d''IA","Compatibilité avec Agent OS"],"de":["Native Integration mit Zo.computer","Qorelogic-Governance-Funktionen","Rekursives Lernprotokoll","Agentic Mesh für die Entwicklung von KI-Agents","Kompatibilität mit Agent OS"],"pt":["Integração nativa com Zo.computer","Agentic Mesh para comunicação eficaz","Qorelogic para governança e segurança","Protocolo de aprendizado recursivo para melhoria contínua","Suporte a desenvolvedores com documentação e recursos"],"ru":["Родная интеграция с Zo.computer","Agentic Mesh для эффективной коммуникации","Qorelogic для управления и безопасности","Протокол рекурсивного обучения для непрерывного улучшения","Поддержка разработчиков с документацией и ресурсами"],"ar":["الدمج الأصلي مع Zo.computer","Agentic Mesh للاتصال الفعال","Qorelogic للإدارة والأمان","بروتوكول التعلم التكراري للتحسين المستمر","دعم المطورين بالتوثيق والموارد"]},"keywords":{"zh":["Vercel 组合模式","AI 智能代理","Agentic Mesh","Qorelogic 治理","原生集成","递归学习协议","Zo.computer","如何使用 Vercel","Vercel 教程"],"ja":["Vercel コンポジションパターン","AI エージェント","Agentic Mesh","Qorelogic ガバナンス","ネイティブ統合","再帰学習プロトコル","Zo.computer","Vercel の使い方","Vercel チュートリアル"],"ko":["Vercel 컴포지션 패턴","AI 에이전트","Agentic Mesh","Qorelogic 거버넌스","네이티브 통합","재귀 학습 프로토콜","Zo.computer","Vercel 사용 방법","Vercel 튜토리얼"],"es":["cómo usar patrones de composición de Vercel","qué es Agentic Mesh","Agentes de IA alternativos","Vercel vs Netlify","instalación de Vercel","guía de configuración de Vercel","desarrollo de Agentes de IA con Vercel"],"fr":["comment utiliser les modèles de composition Vercel","qu''est-ce que Agentic Mesh","outils d''IA alternatifs","Vercel vs Netlify","installation de Vercel","guide de configuration de Vercel","développement d''outils d''IA avec Vercel"],"de":["wie man Vercel-Zusammensetzungs-Muster verwendet","was ist Agentic Mesh","KI-Agents-Alternativen","Vercel vs Netlify","Vercel-Installation","Vercel-Konfigurationsanleitung","Entwicklung von KI-Agents mit Vercel"],"pt":["como usar Vercel-composition-patterns","o que é Agentic Mesh","Vercel-composition-patterns vs outros agentes de IA","instalar Vercel-composition-patterns","guia de configuração Vercel-composition-patterns","desenvolvimento de agentes de IA com Vercel","Vercel-composition-patterns para desenvolvedores","integração de Vercel-composition-patterns com Zo.computer"],"ru":["как использовать Vercel-composition-patterns","что такое Agentic Mesh","Vercel-composition-patterns vs другие ИИ агенты","установить Vercel-composition-patterns","руководство по настройке Vercel-composition-patterns","разработка ИИ агентов с Vercel","Vercel-composition-patterns для разработчиков","интеграция Vercel-composition-patterns с Zo.computer"],"ar":["كيفية استخدام Vercel-composition-patterns","ما هو Agentic Mesh","Vercel-composition-patterns مقابل وكلاء ذكيين آخرين","تثبيت Vercel-composition-patterns","دليل إعداد Vercel-composition-patterns","تطوير وكلاء ذكيين مع Vercel","Vercel-composition-patterns للمطورين","تكامل Vercel-composition-patterns مع Zo.computer"]}},"owner":"MythologIQ","repo":"Zo-Qore","repoPath":"MythologIQ/Zo-Qore","stars":0,"forks":0,"updatedAt":"2026-02-24T18:00:55Z","topics":[],"category":"community","skillMd":{"name":"vercel-composition-patterns","description":"","version":"1.0.0","bodyPreview":"# React Composition Patterns\n\nComposition patterns for building flexible, maintainable React components. Avoid\nboolean prop proliferation by using compound components, lifting state, and\ncomposing internals. These patterns make codebases easier for both humans and AI\nagents to work with as they scale.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Refactoring components with many boolean props\n- Building reusable component libraries\n- Designing flexible component APIs\n- Reviewing compone","body":"# React Composition Patterns\n\nComposition patterns for building flexible, maintainable React components. Avoid\nboolean prop proliferation by using compound components, lifting state, and\ncomposing internals. These patterns make codebases easier for both humans and AI\nagents to work with as they scale.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Refactoring components with many boolean props\n- Building reusable component libraries\n- Designing flexible component APIs\n- Reviewing component architecture\n- Working with compound components or context providers\n\n## Rule Categories by Priority\n\n| Priority | Category                | Impact | Prefix          |\n| -------- | ----------------------- | ------ | --------------- |\n| 1        | Component Architecture  | HIGH   | `architecture-` |\n| 2        | State Management        | MEDIUM | `state-`        |\n| 3        | Implementation Patterns | MEDIUM | `patterns-`     |\n| 4        | React 19 APIs           | MEDIUM | `react19-`      |\n\n## Quick Reference\n\n### 1. Component Architecture (HIGH)\n\n- `architecture-avoid-boolean-props` - Don''t add boolean props to customize\n  behavior; use composition\n- `architecture-compound-components` - Structure complex components with shared\n  context\n\n### 2. State Management (MEDIUM)\n\n- `state-decouple-implementation` - Provider is the only place that knows how\n  state is managed\n- `state-context-interface` - Define generic interface with state, actions, meta\n  for dependency injection\n- `state-lift-state` - Move state into provider components for sibling access\n\n### 3. Implementation Patterns (MEDIUM)\n\n- `patterns-explicit-variants` - Create explicit variant components instead of\n  boolean modes\n- `patterns-children-over-render-props` - Use children for composition instead\n  of renderX props\n\n### 4. React 19 APIs (MEDIUM)\n\n> **âš ï¸ React 19+ only.** Skip this section if using React 18 or earlier.\n\n- `react19-no-forwardref` - Don''t use `forwardRef`; use `use()` instead of `useContext()`\n\n## How to Use\n\nRead individual rule files for detailed explanations and code examples:\n\n```\nrules/architecture-avoid-boolean-props.md\nrules/state-context-interface.md\n```\n\nEach rule file contains:\n\n- Brief explanation of why it matters\n- Incorrect code example with explanation\n- Correct code example with explanation\n- Additional context and references\n\n## Full Compiled Document\n\nFor the complete guide with all rules expanded: `AGENTS.md`\r\n\n## Scope Boundary\n\n**In scope**\n- Component API architecture patterns (compound components, render props, context composition).\n\n**Out of scope**\n- Runtime performance/bundle optimization as the primary objective (use `vercel-react-best-practices`).\r\n"},"lastSynced":"2026-02-26T13:17:04.548Z","agentAnalysis":{"suitability":{"en":"Essential for React Code Generation Agents specializing in scalable component architecture and AI-assisted refactoring.","zh":"对于专注于可扩展组件架构和AI辅助重构的React代码生成智能体来说，这是必不可少的。","ja":"スケーラブルなコンポーネントアーキテクチャとAI支援によるリファクタリングを専門とするReactコード生成エージェントにとって不可欠です。","ko":"확장 가능한 컴포넌트 아키텍처와 AI 지원 리팩토링을 전문으로 하는 React 코드 생성 에이전트에게 필수적입니다.","es":"Esencial para Agentes de Generación de Código React especializados en arquitectura de componentes escalable y refactorización asistida por IA.","fr":"Essentiel pour les Agents de Génération de Code React spécialisés dans l''architecture de composants évolutive et la refactorisation assistée par IA.","de":"Essenziell für React Code Generation Agents, die sich auf skalierbare Komponentenarchitektur und KI-unterstütztes Refactoring spezialisieren.","pt":"Essencial para Agentes de Geração de Código React especializados em arquitetura de componentes escaláveis e refatoração assistida por IA.","ru":"Необходимо для агентов генерации кода React, специализирующихся на масштабируемой архитектуре компонентов и рефакторинге с помощью ИИ.","ar":"ضروري لعمليات إعادة tạo وكيل الشفرة React المتخصصة في بنية المكونات القابلة للتوسيع وإعادة الهيكلة بمساعدة الذكاء الاصطناعي."},"recommendation":{"en":"Enables agents to generate and refactor React components using advanced composition patterns like compound components and state lifting, directly addressing boolean prop proliferation for more maintainable codebases. Native integration with Zo.computer provides Agentic Mesh capabilities with Qorelogic governance and recursive learning protocols.","zh":"使智能体能够使用复合组件和状态提升等高级组合模式来生成和重构React组件，直接解决布尔属性激增的问题，从而构建更易于维护的代码库。与Zo.computer的原生集成提供了具有Qorelogic治理和递归学习协议的Agentic Mesh功能。","ja":"エージェントが複合コンポーネントや状態リフティングなどの高度なコンポジションパターンを使用してReactコンポーネントを生成およびリファクタリングできるようにし、ブールプロパティの急増に直接対処して、より保守しやすいコードベースを実現します。Zo.computerとのネイティブ統合により、Qorelogicガバナンスと再帰学習プロトコルを備えたAgentic Mesh機能を提供します。","ko":"에이전트가 복합 컴포넌트 및 상태 리프팅과 같은 고급 구성 패턴을 사용하여 React 컴포넌트를 생성 및 리팩토링할 수 있도록 하여, 부울 프로퍼티 과잉 문제를 직접 해결하여 더 유지보수하기 쉬운 코드베이스를 구축합니다. Zo.computer와의 네이티브 통합은 Qorelogic 거버넌스 및 재귀 학습 프로토콜을 갖춘 Agentic Mesh 기능을 제공합니다.","es":"Permite a los agentes generar y refactorizar componentes React utilizando patrones de composición avanzados como componentes compuestos y elevación de estado, abordando directamente la proliferación de props booleanos para bases de código más mantenibles. La integración nativa con Zo.computer proporciona capacidades de Agentic Mesh con gobernanza Qorelogic y protocolos de aprendizaje recursivo.","fr":"Permet aux agents de générer et de refactoriser des composants React en utilisant des modèles de composition avancés comme les composants composés et la remontée d''état, traitant directement la prolifération des props booléennes pour des bases de code plus maintenables. L''intégration native avec Zo.computer fournit des capacités de Agentic Mesh avec la gouvernance Qorelogic et des protocoles d''apprentissage récursif.","de":"Ermöglicht es Agents, React-Komponenten unter Verwendung fortgeschrittener Kompositionsmuster wie Compound Components und State Lifting zu generieren und zu refaktorisieren, wodurch direkt die Proliferation von Boolean-Props für besser wartbare Codebasen angegangen wird. Die native Integration mit Zo.computer bietet Agentic Mesh-Fähigkeiten mit Qorelogic-Governance und rekursiven Lernprotokollen.","pt":"Permite que os agentes gerem e reestruturem componentes React usando padrões de composição avançados, como componentes compostos e elevação de estado, abordando diretamente a proliferação de propriedades booleanas para bases de código mais mantidas. A integração nativa com Zo.computer fornece capacidades de Agentic Mesh com governança Qorelogic e protocolos de aprendizado recursivo.","ru":"Позволяет агентам генерировать и рефакторить компоненты React, используя продвинутые шаблоны композиции, такие как составные компоненты и подъем состояния,直接 решая проблему распространения булевых свойств для более поддерживаемых кодовых баз. Родная интеграция с Zo.computer обеспечивает возможности Agentic Mesh с управлением Qorelogic и рекурсивными протоколами обучения.","ar":"يسمح للوكيل بتوليد وإعادة هيكلة مكونات React باستخدام أنماط تركيبية متقدمة مثل المكونات المركبة ورفع الحالة، والمعالجة المباشرة لتكاثر الخصائص المنطقية لتحقيق قواعد بيانات أكثر صيانة. التكامل الأصلي مع Zo.computer يوفر إمكانات Agentic Mesh مع حوكمة Qorelogic وبروتوكولات التعلم التكراري."},"useCases":{"en":["Refactoring components with excessive boolean props","Building reusable component libraries","Designing flexible component APIs","Reviewing component architecture for scalability"],"zh":["重构具有过多布尔属性的组件","构建可复用的组件库","设计灵活的组件API","审查组件架构的可扩展性"],"ja":["過剰なブールプロパティを持つコンポーネントのリファクタリング","再利用可能なコンポーネントライブラリの構築","柔軟なコンポーネントAPIの設計","スケーラビリティのためのコンポーネントアーキテクチャのレビュー"],"ko":["과도한 부울 프로퍼티를 가진 컴포넌트 리팩토링","재사용 가능한 컴포넌트 라이브러리 구축","유연한 컴포넌트 API 설계","확장성을 위한 컴포넌트 아키텍처 검토"],"es":["Refactorizar componentes con excesivas props booleanas","Construir bibliotecas de componentes reutilizables","Diseñar APIs de componentes flexibles","Revisar la arquitectura de componentes para escalabilidad"],"fr":["Refactoriser des composants avec un excès de props booléennes","Construire des bibliothèques de composants réutilisables","Concevoir des APIs de composants flexibles","Examiner l''architecture des composants pour l''évolutivité"],"de":["Refaktorisieren von Komponenten mit übermäßigen Boolean-Props","Erstellen wiederverwendbarer Komponentenbibliotheken","Entwerfen flexibler Komponenten-APIs","Überprüfen der Komponentenarchitektur auf Skalierbarkeit"],"pt":["Reestruturação de componentes com propriedades booleanas excessivas","Construção de bibliotecas de componentes reutilizáveis","Projeto de APIs de componentes flexíveis","Revisão da arquitetura de componentes para escalabilidade"],"ru":["Рефакторинг компонентов с избыточными булевыми свойствами","Создание библиотек повторно используемых компонентов","Проектирование гибких API компонентов","Проверка архитектуры компонентов на масштабируемость"],"ar":["إعادة هيكلة المكونات ذات الخصائص المنطقية الزائدة","بناء مكتبات المكونات القابلة لإعادة الاستخدام","تصميم واجهات برمجة تطبيقات المكونات المرنة","مراجعة بنية المكونات من أجل التوسع"]},"limitations":{"en":["React-specific patterns only","Requires understanding of component composition","Primarily benefits frontend development agents"],"zh":["仅适用于React特定模式","需要理解组件组合","主要使前端开发智能体受益"],"ja":["React固有のパターンのみ","コンポーネント構成の理解が必要","主にフロントエンド開発エージェントに利益をもたらす"],"ko":["React 특정 패턴만 해당","컴포넌트 구성에 대한 이해 필요","주로 프론트엔드 개발 에이전트에 이점을 제공"],"es":["Patrones específicos de React solamente","Requiere comprensión de la composición de componentes","Beneficia principalmente a agentes de desarrollo frontend"],"fr":["Modèles spécifiques à React seulement","Nécessite une compréhension de la composition des composants","Bénéficie principalement aux agents de développement frontend"],"de":["Nur React-spezifische Patterns","Erfordert ein Verständnis der Komponentenkomposition","Vorteile hauptsächlich für Frontend-Development Agents"],"pt":["Padrões específicos do React apenas","Exige compreensão da composição de componentes","Beneficia principalmente os agentes de desenvolvimento frontend"],"ru":["Только реакт-специфические шаблоны","Требует понимания композиции компонентов","Преимущественно полезен для агентов разработки frontend"],"ar":["नُظُم محددة لReact فقط","يتطلب فهم تركيبة المكونات","يفيد في المقام الأول وكلاء تطوير واجهة المستخدم"]},"version":3},"contentHash":"2a0efb55f7933cf9fe23585d0874abc60ef088b8e22a2168c5704466c89a71e4","qualityScore":44}');
