INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MythologIQ/Zo-Qore/vercel-composition-patterns', 'vercel-composition-patterns', 'MythologIQ', 'Zo-Qore', 'community', 'vercel-composition-patterns MythologIQ Zo-Qore community Vercel 组合模式是一种用于构建原生集成的 AI 智能代理，具有 Agentic Mesh 和 Qorelogic 治理 Vercel コンポジションパターンは、ネイティブ統合の AI エージェントを構築するための方法です Vercel 컴포지션 패턴은 네이티브 통합 AI 에이전트를 구축하는 데 사용됩니다 El patrón de composición de Vercel permite una integración nativa con Zo.computer y Agentic Mesh con capacidades de gobernanza de Qorelogic Le modèle de composition Vercel permet une intégration native avec Zo.computer et Agentic Mesh avec des capacités de gouvernance Qorelogic Das Vercel-Zusammensetzungs-Muster ermöglicht eine native Integration mit Zo.computer und Agentic Mesh mit Qorelogic-Governance-Funktionen O Vercel-composition-patterns é um agente de IA que utiliza Agentic Mesh e Qorelogic para integração nativa com Zo.computer Vercel-composition-patterns - это ИИ агент, который использует Agentic Mesh и Qorelogic для родной интеграции с Zo.computer Vercel-composition-patterns هو وكيل ذكي يستخدم Agentic Mesh و Qorelogic للدمج الأصلي مع Zo.computer Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer Vercel 组合模式 AI 智能代理 Agentic Mesh Qorelogic 治理 原生集成 递归学习协议 Zo.computer 如何使用 Vercel Vercel 教程 Agent OS, with Agentic Mesh capabilities with Qorelogic governance and recursive learning protocol intended for native integration with Zo.computer');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shinpr/agentic-code/documentation-criteria', 'community', 'shinpr', 'agentic-code', 'shinpr/agentic-code', 'documentation-criteria', 35, 3, 44, '2026-03-02T14:33:29Z', '2026-03-03T02:00:12.419Z', 'd44ef2ecfa66db6c6aeec22525a38f071cde63e7934d40d85c6054294ed84a31', '{"id":"shinpr/agentic-code/documentation-criteria","name":"documentation-criteria","description":{"zh":"一个由AGENTS.md驱动的AI代理编码框架，为Cursor、Codex和Gemini CLI提供系统化的测试优先工作流和质量门控，提升AI编程代理的开发效率和代码质量。","ja":"AGENTS.mdによって駆動されるAIエージェントコーディングフレームワーク。システム化されたテストファーストワークフローと品質ゲートを提供し、AIプログラミングエージェントの開発効率とコード品質を向上させます。","ko":"AGENTS.md로 구동되는 AI 에이전트 코딩 프레임워크. Cursor, Codex, Gemini CLI를 위한 체계적인 테스트 우선 워크플로우와 품질 게이트를 제공하여 AI 프로그래밍 에이전트의 개발 효율성과 코드 품질을 향상시킵니다.","es":"El marco de codificación Agentic, impulsado por AGENTS.md, ofrece flujos de trabajo sistemáticos y automatizados con agentes de codificación AI","fr":"Le cadre de codage Agentic, alimenté par AGENTS.md, propose des flux de travail systématiques et automatisés avec des agents de codage IA","de":"Das Agentic-Coding-Framework, angetrieben von AGENTS.md, bietet systematische und automatisierte Workflows mit KI-Coding-Agenten","pt":"A estrutura de codificação Agentic é uma plataforma de workflow sistemático que utiliza agents de IA para melhorar a produtividade","ru":"Платформа Agentic представляет собой системный workflow, который использует ИИ Агентов для повышения производительности","ar":"تعتبر إطار العمل Agentic منصة سير عمل منهجي تستخدم وكلاء الذكاء الاصطناعي لتحسين الإنتاجية","en":"Agentic coding framework powered by AGENTS.md — systematic, test-first workflows with quality gates for Cursor, Codex, Gemini CLI, and AI coding agents."},"seo":{"title":{"zh":"AGENTS.md文档标准AI工具：提升AI编程代理工作流","ja":"AGENTS.mdドキュメント基準AIエージェント：コーディング自動化","ko":"AGENTS.md 문서 기준 AI 에이전트: 코딩 워크플로우 자동화","es":"Herramientas de AI: M